/* 平成17年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h17.committeeSessions.push(...[{"id":"h17-20050830-5","meetingId":"h17-cm08","date":"2005年8月30日","dateIso":"2005-08-30","committee":"総務委員会","time":"午後１時０４分～午後２時５５分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を42件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"本田委員","kind":"質問","question":"１点だけ、需要算定、補正審議を行っておりますけれども、渋谷区、港区が交付金が以前は逆に出さなければならない区が問題があって、その点は改善をされているでしょうけれども、２区のほうからはこういうやり方、水平調整についての意見というのは何か出ているのか尋ねました。","respondent":"日下部企画財政課長","answer":"実は、渋谷区は第３ブロックに入っております。全く入ってこないということで、区民感情の点からするとなかなか説明がしにくいと、そういう話を伺ったという経緯があります。","id":"exchange-001"},{"speaker":"本田委員","kind":"意見","question":"どうしてもこういう問題が出てきますから、もし品川区がこういう状況になったら、やはりいろいろと意見は出さざるを得ないと思うんです。これで１００％、２３区の水平調整のあり方がこれでいいのかなという疑問はずっと持っているんですけれども、答弁は結構ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-002"},{"speaker":"宮崎委員","kind":"質問・要望","question":"二、三伺いたいのですけれども、相談窓口を開設されたと言っていたんですけれども、この間の実績があったら教えていただきたい。それから、具体的にどういうふうに徹底していくのかというところで、具体的に強制力はどの程度なのかということをお伺いしたいと思います。","respondent":"日下部企画財政課長","answer":"解体工事の指導の関係ですけれども、これはきちんと徹底していきたいと考えておりますけれども、それから窓口での指導ということになってまいります。それぞれ罰則規定もありますので、その辺との関係も含めまして、できる限り指導を図ってまいりたいと考えております。","id":"exchange-003"},{"speaker":"宮崎委員","kind":"質問","question":"そうすると、あくまでも指導を図っていくという理解でいいわけですね。もう１回お伺いしておきたいんですけれども、３,０００種類とかいろいろ言われているんですけれども、改めてお伺いしたいと思います。","respondent":"日下部企画財政課長","answer":"含有している状況については、目視ではとてもではないけれども確認できないので、これはＸ線の解析調査をしっかりやっていくということが前提です。","id":"exchange-004"},{"speaker":"宮崎委員","kind":"質問・要望","question":"どの辺まで除去の対象にしていくのかというところは、本来であればゼロにしていただきたいというのが区民感情だと思うんですけれども、ここのところはどう考えたらいいのか尋ねました。","respondent":"日下部企画財政課長","answer":"昭和６２年のときにもやりましたように、その点も含めまして、私どもは現実的な対応をしっかりとやっていくというお話しを申し上げました。ただ実態をまず把握しないと、その辺は実態調査の結果を踏まえた上で、具体策についての検討をしっかり進めていきたいと考えております。","id":"exchange-005"},{"speaker":"宮崎委員","kind":"質問・要望","question":"実態調査を踏まえてということでありますので、その辺についても実態調査をしっかりやってほしいと求めました。やはり基本的にゼロというのが区民感情だと思いますので、ぜひそういう方向で対応をお願いしたいなと、これは要望しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"鈴木（真）委員","kind":"質問","question":"２点ほど、解体現場のご説明がありましたけれども、やはり我々の中にもそういう質問が大分入ってきております。それからもう１点は、大変厳しい状況の中で枠が取れるのかどうかという心配もあったので、簡単で結構です。","respondent":"日下部企画財政課長","answer":"その辺のところもありますし、最大でも今年度は１０件程度でおさまるだろうと、その程度で見込んでいるところです。それから、実際の利子補給等につきましては、既定の予算がありますので、たとえそれが増えたとしても対応できると、このように見込んです。","id":"exchange-007"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"現実にどうなんですか、把握していらっしゃるのかなと思うんですけれども、その辺も考えといていただきたいなと思います。お願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"原委員","kind":"質問・要望","question":"個人の場合と中小企業の場合、それぞれのあっ旋制度の中にアスベスト対策資金をつくって、融資限度額を求めているわけですね。件数はともかくとして、その辺の考え方の中で、今後限度額は有効なのかどうかという検証はどうなんか尋ねました。","respondent":"日下部企画財政課長","answer":"資料の中にも出てありますけれども、個人の場合は１,０００万円、中小企業の場合は１,５００万円ということで限度額を設定しています。例えば個人の住宅の場合は１,０００万円の限度額で対応できるのではないかということで、今私どもは見込んでおりますので。","id":"exchange-009"},{"speaker":"原委員","kind":"意見","question":"アスベストの積み上げがいいのか悪いのかということもいろいろあると思うんですが、その辺をもっと具体的に検討するとか、そういうのはとの意見を述べました。","respondent":"日下部企画財政課長","answer":"つまり、中小企業事業資金融資あっ旋制度は全部一緒ということではなくて、それぞれの目的別に活用できるような形になっております。それはそれで別立てということになりますので、それは比較的その切り分けの中で活用いただくのではないかと、そのように見込んでいるところです。","id":"exchange-010"},{"speaker":"藤田委員","kind":"意見","question":"それをだれが判断するのか、素人の会社の社長は、アスベストが使われているのかいないのかというのは判断つかないのではないかと思うんです。","respondent":"日下部企画財政課長","answer":"今、現状ではこういう分析を専門にしている会社もありますので、そちらのほうをご紹介をさせていただいているという状況です。いずれにしましても、そういう形で専門家をご紹介させていただいているという状況ですので、ご理解いただければということです。","id":"exchange-011"},{"speaker":"藤田委員","kind":"質問・要望","question":"解体をする業者が、本当にこれはアスベストかどうかというのはわからないと思うんです。紹介だけでは弱いのではないかというふうに思うんですけれども、これから予算をつけてやるわけですから、これは要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"三村委員","kind":"質問","question":"どういう施設でアスベストが利用されていたのか、施設面ですとか吹き付けアスベストが使用されていた状況等を公表すべきではないかと思いますけれども、いかがか尋ねました。","respondent":"日下部企画財政課長","answer":"これは既に校長会を通しまして、具体的な今の現状、それから今後の取り組みということで各施設にも伝えてあるところです。まず現状についてはっきりと利用者の方にご説明できるような対応をしていますので、当面はそういうことで対処していきたいと考えております。","id":"exchange-013"},{"speaker":"三村委員","kind":"質問","question":"そういう状況ですと、今実際に学校を利用されている方には情報が行ったと思うんですけれども、実際に被害を受けている可能性がある、そういった方には情報が、その施設を利用していたのだけれども、被害の可能性があったかもしれない人たちには情報が行かないということにならないか尋ねました。","respondent":"日下部企画財政課長","answer":"前提といたしましては、基本的にはその時点でもう２０年ほど経過しておりますけれども、また２０施設のうち１２施設は大体機械室です。そういう現状も含めて、私どもとしましては問い合わせがあれば、それはそれとして実情についてもしっかりお伝えしていきたいと考えております。","id":"exchange-014"},{"speaker":"三村委員","kind":"意見","question":"よく学校の機械室で遊んだ記憶があるんですね。だから、あれが原因かなという判断もできるかと思うので、どこの施設にどういうふうに使われていたかを情報として公開をすることは考えていないのかとの意見を述べました。","respondent":"日下部企画財政課長","answer":"情報の提供とか公表というのは、なかなか難しい面があります。私どもとしましては、情報の提供とか公表については事実関係の確認を含めて慎重に対応していきたいと、このように考えております。","id":"exchange-015"},{"speaker":"高星委員","kind":"質問・要望","question":"その辺のところ、一環境課だけでの総合窓口というような考え方でいいのかどうなのかという、基本的な考え方を教えていただきたいということが一つ。総務委員会でこの辺のところを話していいかどうかというのはわからないけれども、どんなふうに話し合われているのかお聞きしたい。","respondent":"日下部企画財政課長","answer":"１点目の庁内の取り組む体制の問題ですけれども、先ほど申し上げましたように関係課長によるアスベストの庁内連絡会は既に何回も開催しています。","id":"exchange-016"},{"speaker":"高星委員","kind":"意見","question":"だから、現実的に例えば２階建ての一部駐車場というのは、おそらく１日あれば潰してしまうわけです。役所はどういう対応をするのかも含めて、マニュアルをつくるという話もあるけれども、よろしくお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-017"},{"speaker":"本田委員","kind":"質問","question":"１点お聞きしたいのは、日本全体の問題であって、財政的なものも含めてどういう対応をしていくかというのが非常に問われているんです。今日のＳＬのことについては、当然区民から問い合わせが来ているのではないかと思うんですけれども、この点と２点伺います。","respondent":"日下部企画財政課長","answer":"１点目の国や都との関係ですけれども、そういった意味では本当に一市区町村だけで対応しようとしても、これは現実問題無理な話です。当然除去費用もかなりな金額に上ってまいりますので、東京都、今後しっかりと対応してまいりたいと考えております。","id":"exchange-018"},{"speaker":"本田委員","kind":"質問・要望","question":"都の関連というのも、やはり厳しく要望するものは要望して、連携して対応していかないと対応仕切れないというふうに思うんです。ですから、品川区の現状を踏まえながら、厳しく問題提起するところは行政サイドとして言うことを私は要望していきたいというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"アスベストを除去した後の処理も教えて、ちょっとわからなかったので、最終処分というのはどういう形をしていらっしゃるのか。それから、そういう施設というのは、品川区の中にあるのか、処分先が気になったので、おわかりになれば教えてほしいと求めました。","respondent":"日下部企画財政課長","answer":"これは８月２日の委員会でも申し上げましたけれども、東京都の環境保全局が仕分けしておりますけれども、別立ての扱いになります。これは民間も区も同様です。","id":"exchange-020"},{"speaker":"鈴木（真）委員","kind":"意見","question":"最終処分はどういう状況になっているのか、例えば品川区の中にあるのかどうか、その辺だけ気になったのでとの意見を述べました。","respondent":"日下部企画財政課長","answer":"私も最終的に焼却するのか、埋め立て処分をするのか、その辺私ども把握しておりませんので、それはまた確認をさせていただきたいと思います。","id":"exchange-021"},{"speaker":"宮崎委員","kind":"意見","question":"改めて、負担はどこでどういうふうに負担するかということをお願いしますとの意見を述べました。","respondent":"上野都市開発課長","answer":"本件の部分につきましては、明電舎の開発に合わせて整備することになってありますが、基本的に整備費用負担につきましては、明電舎の負担で行うことになってありますが、一部必要な区間につきましては、国費を導入できるところについては導入するということにしています。","id":"exchange-022"},{"speaker":"宮崎委員","kind":"質問","question":"国費を導入と言ったときに補助金はどうなるのか尋ねました。","respondent":"上野都市開発課長","answer":"本件４号線の明電舎の負担につきましても、対象額につきまして都市再生総合整備事業というメニューを使いまして補助金を入れてあります。","id":"exchange-023"},{"speaker":"宮崎委員","kind":"質問","question":"具体的に１億４,１１０万円ですけれども、このうち幾らぐらいになるのか尋ねました。","respondent":"上野都市開発課長","answer":"国費といたしましては４,５００万円が入ってくる予定になってあります。","id":"exchange-024"},{"speaker":"宮崎委員","kind":"意見","question":"４,５００万円というと、３分の１ぐらいが国費ということですけれども、こういうのはどういうものかと感じました。改めて申し上げておきますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-025"}]},{"id":"topic-02","title":"(4)、平成１７年９月１１日執行の衆議院議員選挙および最高裁判所裁判官国民審査の執行要領","agenda":"(4)、平成１７年９月１１日執行の衆議院議員選挙および最高裁判所裁判官国民審査の執行要領","exchanges":[{"speaker":"宮崎委員","kind":"確認","question":"細かいことで確認をしたいんですけれども、不在者投票や期日前投票の場合、衆議院議員選挙と最高裁判所裁判官国民審査は期日が違うわけですね。早めに行った方というのは、最高裁判所裁判官国民審査はできないということになるんですか、それともまた来てもらうということになるんか尋ねました。","respondent":"野田口選挙管理委員会事務局長","answer":"なぜ期日前投票で１週間前でなければできないですけれども、裁判官に付される審査される期日が公示日ということで、手続上今日決まるわけです。これは制度上、そういった仕組みがあるということで、ご理解いただきたいです。","id":"exchange-026"}]},{"id":"topic-03","title":"２の行政視察","agenda":"２の行政視察","exchanges":[{"speaker":"三村委員","kind":"質問","question":"前回の８月２日の視察の件でお伺いしたいんですけれども、提供があったんですけれども、こちらとしても申し出をするのが筋ではなかったかということ。区のマイクロバスの大井競馬場からの出発が８時半であったということで、超過勤務という形になりますから、この２点についてお伺いしたいと思います。","respondent":"市岡区議会事務局長","answer":"お弁当等の件につきましては、先方から提供していただいたもので、直接私どもの判断では関係なかろうかというふうに考えてあります。それから、当然それは委員会の開催時間だけが職務時間ではございませんので、必要な所管委員会での対象になるというふうに理解しております。","id":"exchange-027"},{"speaker":"三村委員","kind":"質問","question":"お弁当ですとかビールの提供というのは、例年行われていたのかどうか、その辺のところはご存じか尋ねました。","respondent":"市岡区議会事務局長","answer":"私が知っている範囲では、ここ数年は行われていたかと思います。","id":"exchange-028"},{"speaker":"三村委員","kind":"質問","question":"向こう側の用意ということでお答えがありましたけれども、私がお尋ねしているのは、例年そういう準備が向こうのほうからされているのであれば、こちらのほうからそういった準備をしないでいいというような申し出をしてはいかがでしょうかということです。","respondent":"市岡区議会事務局長","answer":"そういう論点があったということは、伝えします。必要であれば、そういうご意見があったことも、競馬組合のほうにお伝えすることは可能です。","id":"exchange-029"},{"speaker":"三村委員","kind":"質問","question":"委員会活動は５時半で終了ということだと思うんですけれども、各委員の活動でもマイクロバスの使用はできるという理解でよろしいのですか。５時半から８時半まで議員が残っていたので、区のマイクロバスが空いていれば、そういった利用も可能だということの理解でよろしいのか尋ねました。","respondent":"市岡区議会事務局長","answer":"それは委員会としての活動が終わりましたが、各議員としての活動が一定程度のグループで行われておりますので、ほかにも議員活動の中でも利用しており、このようなケースも相当な範囲だと考えております。","id":"exchange-030"},{"speaker":"三村委員","kind":"質問","question":"もう１点、委員会外の方が３名同行されておりましたけれども、そういった際は会議規則によりますと、委員を派遣する場合は議長あてに書類を提出するということになっておりますけれども、そういった処理がされての同行だったのか、その辺のところをお伺いいたします。","respondent":"市岡区議会事務局長","answer":"委員会の議員の派遣ではなくて委員の派遣ですから、当然委員会が競馬場の視察に行くことについては議長の承認を得ております。規則で説明をされているところですので、事務的に必要な調査でありましたら、特段手続は必要ありません。","id":"exchange-031"},{"speaker":"三村委員","kind":"質問","question":"そういう方は普通マイクロバスの移動で交通事故等に遭った場合、そういった場合は委員は公務災害という形で取られるかと思うんですけれども、こういったあいまいな位置づけだと、そういった対象にならない方も出てくるかと思うんですけれども、そういった点についてはどうか尋ねました。","respondent":"市岡区議会事務局長","answer":"それは議員活動もそうですし、一般の公務災害もそうですが、個々のケースによって認定者が決めるところでございまして、一般的にこういうのが適用になるのかならないのかは、ここで判断できるものではございません。","id":"exchange-032"},{"speaker":"三村委員","kind":"質問","question":"どういう手続で何日前までに連絡をもらっているとか、内々の基準があるかと思うんですけれども、その辺を詳しく教えていただいたと思います。","respondent":"市岡区議会事務局長","answer":"一般的にどの説明でもされていると思いますが、議員本来の活動の一つとして他の委員会を傍聴するということは当然の権限ということになります。","id":"exchange-033"},{"speaker":"宮崎委員","kind":"質問・要望","question":"確認なんですが、私も伺いたいと思います。要するにこちらのほうが監視する監視されるという関係に出てくるわけですから、これはしっかりそういう関係の前に、これはやめていただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"原委員","kind":"意見","question":"そういうことを考えると、要するによく見てほしいという部分を含めて、向こうの競馬組合では配慮してくれたのではないかというふうに思っております。要するに、現状の中で見てくださいという部分を含んでの話だと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-035"},{"speaker":"高星委員","kind":"質問","question":"２３区が競馬組合をつくってやっているわけですから、そういう意味でちょっと違うかなと思うんです。公職選挙法で定めている５００円以内のお茶ぐらいだったらいいけれども、コーヒーはだめだとか、そういうスタンスの話ではないだろうと思うんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"},{"speaker":"鈴木（真）委員","kind":"意見","question":"どのぐらいの方が来ているということが見えると思いますし、またこういうことをやっているというのが、あの日も馬車にお客さんを乗せていましたね。次回の委員会の話になってしまうかもしれませんけれども、正副で次期に申し送りしていただければ、その中でまた検討をしてほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-037"},{"speaker":"藤田委員","kind":"質問","question":"品川で開催されているナイター競馬についてどういう実態なのかという視察に行って、今回は４時ですか、それまでに競馬場の実情を聞いて質疑をすると。ですから、ではどうですか」ということは、先方にすれば考えるところだと思うんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-038"},{"speaker":"宮崎委員","kind":"意見","question":"される側の関係の中での問題なんだということは、やはりこちらのほうが、「そういう点は心配しなくていい」ということは言うべきだと思います。それをしないというのは、やはりあらぬ話にもなりかねないというふうに思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-039"},{"speaker":"高星委員","kind":"意見","question":"地元区ということで、廃止するかどうするかも含めて相当時間をかけて議論した。そのことをつけ加えておきますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-040"},{"speaker":"本田委員","kind":"質問・要望","question":"思い起こせば、ナイターをやるかどうか、法律まで新たにつくって大井競馬場は全国でナイターを最初にやった競馬場ですから。青少年対策、いろいろな地元の町会や商店街がやっているわけですから、そういうことを踏まえて来るんだなと先方は取るだろうと思うんですね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-041"},{"speaker":"高星委員","kind":"意見","question":"できれば問題が視察ならば、ナイターをやっている期間中は大井競馬の出入りの人たちが品川区内の公園をパトロールしているわけです。そういった実態をやはり我々もしっかり見ていく必要があったのかなというような気がしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-042"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/594587?Template=document&Id=1694#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2005-01-01&TermEnd=2005-12-31"}],"sourceMeta":{"pages":0,"characters":32541,"voices":101}},{"id":"h17-20050831-11","meetingId":"h17-cm08","date":"2005年8月31日","dateIso":"2005-08-31","committee":"自治制度特別委員会","time":"午後１時０５分～午後２時２０分","status":"正式会議録","sourceType":"formal","overview":"自治制度特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を13件整理しています。","topics":[{"id":"topic-01","title":"特定事件調査といたしまして、都区制度改革・主要５課題に関すること","agenda":"特定事件調査といたしまして、都区制度改革・主要５課題に関すること","exchanges":[{"speaker":"土井委員","kind":"質問・要望","question":"どうにもいかないシーンがあるんですが、この間の２２日の最後の段階のお話、そこがどうも１つ何かポイントがあるような気がしてしようがないんです。もしというか、どうもそんな形になっていくとするならば、我々もそれだったらするぞというような後押しをすることにならざるを得ないわけですから。","respondent":"日下部企画財政課長","answer":"どうしても改めなければ別途の対応を考えざるを得ない、１つはやはりこれははっきりしておりますのは、自治法に定められた幾つかの方法があります。最終的な１つの方法としては、そういうことを１つ視野に入れての発言である、このように私どもは受けとめてあります。","id":"exchange-001"},{"speaker":"塚本委員","kind":"質問","question":"２３区の議会としては、当事者がどこまで頑張っているのかわからないので、ちょっと教えてほしい。要するに、５課題のこうだああだというのではなくて、どういうような話し合いの状況になっているかということを聞きたい。","respondent":"日下部企画財政課長","answer":"そのときの１つの反応といいますか、例えば、今年度中の合意形成に向けて誠意を持って取り組んでいきたい。非常に抽象的な物言いになりましたが、そういうことでとらまえているところです。","id":"exchange-002"},{"speaker":"塚本委員","kind":"質問","question":"それは重大な決議を持って臨まなければいけないような状況にあるよと言っているわけですから、我々は今、メッセージとして受け取ったんです。その熱度というものがどうなっているのか。","respondent":"日下部企画財政課長","answer":"今回、２カ月ちょっとの間で５回集中審議をやっているということは今までにないわけでありますし、区としても不退転の決意で臨んでいる。そういう意味では今までになく、より真剣な、こういう交渉に臨んでいるです。","id":"exchange-003"},{"speaker":"塚本委員","kind":"質問・要望","question":"調停を求めるというのもそうでしょうし、その時に応じて、その場面に応じて何が必要かということを見ていく。とりあえず。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"どういう形で公表されて、どの程度の都民のところに行っているのかというふうなことをちょっとお聞きしたいのと、そこの考え方についてちょっと説明を求めました。","respondent":"日下部企画財政課長","answer":"東京都のホームページで財務局を開きますと、それにこれが出てまいります。それから２点目の件ですけれども、そういう姿勢もあるだろうということで、今は具体的な中身の検討も含めて準備を進めているです。","id":"exchange-005"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"それはすごい大きな力になると思いますので、ぜひそういう区民生活を守るというところで、そういう区民に知らせるという取り組みもぜひお願いしたいというふうに思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-006"},{"speaker":"石田委員","kind":"質問・要望","question":"７ページの都の主張のところには、２３区の主張は、ちょっとその考え方を教えていただきたいというのが１つ。助役が出席されてないから確認できないけれども、行ったのか、ここら辺のところも教えていただければなと思います。","respondent":"日下部企画財政課長","answer":"１つ今、方法として考えられておりますのは、その辺の検討を今進めているです。そういうことを射程に入れて取り組んでいくということでありますので、最後の別途の対応ということも、抜き方というのはあると思うんです。","id":"exchange-007"},{"speaker":"石田委員","kind":"確認","question":"やっぱりもう１回、ちゃんとそこら辺の確認をするところを明確にして質問をしていただくとか、そういうことも行うべきなんだろうなと思います。もう１点こちらにお聞きしたいのは、その紛争に向けてどうするとか、いかがか尋ねました。","respondent":"日下部企画財政課長","answer":"それを考えたときに、そういう大都市行政論の１つの論拠というものが完全に崩れてしまいますから、向こうも必死な面はあろうかと。幅広い形での包囲網をつくって、そういうことで今、具体的なその辺の図面をしつつあるということでご理解をいただきたいと思います。","id":"exchange-008"},{"speaker":"本田委員","kind":"質問・要望","question":"ですから、同じ第２８２条のご答弁が部課長よりあったんですけれども、そういう段階に来ているのではないかと私は思うんです。もう何年もたつわけですから、９月６日の第４回の協議でどうなるのか注目をするわけですけれども、きょう報告を聞いて強くしているところです。","respondent":"日下部企画財政課長","answer":"ただ、非常に東京都に対する風当たり、財政的な問題を１つとってみても非常に風当たりが強いということははっきりしていると思います。これは２３区も含めてのことでございまして、そういった意味では、そういうことも含めているところです。","id":"exchange-009"},{"speaker":"本田委員","kind":"質問・要望","question":"当面、日程がこうやって組まれているわけですから、それから都区の都側も合意形成に誠意を持って対応するというようなご報告も今あるわけですから。ですから、もう１つ、その辺は議長の方で何かあればお聞かせほしいと求めました。","respondent":"原議長","answer":"直接は区長会が対応する話なんですが、いろいろな形をとって、ぜひ区長会をバックアップしていこうというような気持ちでは一致しております。２３区の議長会としては、とにかく統一することにして、意思を１つにしてこの問題に対処していこうということでは一致しております。","id":"exchange-010"},{"speaker":"土井委員","kind":"質問","question":"それは区長会から多摩の市の方々に申し入れをするのかどうかはともかくとしても、２３区の出身の議員ばかりではなくて、こっちが質問したって。そっちの人をあおり立てるような答弁をするわけですから、議長会レベルでも、少しその辺の戦略をやっていただかなければいけないのではないだろうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"本田委員","kind":"提案","question":"第３回定例会の決議のご提案はされているので、私はしたらいいんじゃないかと。どういうふうにするか、その辺はいろいろ検討するとして、第３回定例会でやったらいいんじゃないかなとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-012"},{"speaker":"石田委員","kind":"質問・要望","question":"質問のどういう要旨で問うということも言っても、こういう答えを欲しいというぐらいの要望ぐらいはしたほうがいいのではないのかなと思っています。今後もしそれをやるというなら、そこら辺のところまでも、１カ月間内だったら、それぐらいをやった方がいいのではないかと。","respondent":"山路委員長","answer":"では、それぞれご意見もいただきまして、第３回定例会に向けて決議を上げるという方向で進めさせていただいてよろしいでしょうか。〔「異議なし」と呼ぶ者あり〕 ９月６日の件も先ほど出ましたけれども、９月１２日の週あたりで閉会中の委員会を１回開催したいと考えておりますが、いかがでしょうか。","id":"exchange-013"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/918758?Template=document&Id=5578#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=11&TermStart=2005-01-01&TermEnd=2005-12-31"}],"sourceMeta":{"pages":0,"characters":23039,"voices":32}},{"id":"h17-20050831-16","meetingId":"h17-cm08","date":"2005年8月31日","dateIso":"2005-08-31","committee":"街づくり特別委員会","time":"午後１時１１分～午後５時０１分","status":"正式会議録","sourceType":"formal","overview":"街づくり特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を19件整理しています。","topics":[{"id":"topic-01","title":"今後の委員会運営","agenda":"今後の委員会運営","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"委員長１人、副委員長１人で、運営していったらいかがなものでしょうかと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"},{"speaker":"南委員","kind":"確認","question":"先ほどの委員長のお話で、議決をしたということであれば、２人体制ということでいくというふうに判断せざるを得ないのかなと考えていますので、私としてはそういうことで進めて、確認をしていっていいんじゃないかと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"本間委員","kind":"質問・要望","question":"２名の副委員長を設置するということで推移しておりますが、正副委員長でお取り計らいいただきたいという言い方で終わっていると思います。その辺も全部含めた、ほかの皆さんの意見も含めたりして、運営そのものについては正副委員長に取り扱い方お任せをしたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"西本委員","kind":"質問・要望","question":"前回、意見を言わせていただいたときに、運営上どうなのかということで確認をさせていただいたと思います。ただ副委員長２名にするかどうかについては、ほかのところとの兼ね合いかありますので、議運等で議論をしていただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"}]},{"id":"topic-02","title":"東急目黒線（武蔵小山駅周辺・西小山駅周辺）に関すること","agenda":"東急目黒線（武蔵小山駅周辺・西小山駅周辺）に関すること","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"下の方にずっと現況の図面が資料３にありますけど、これは昭和医大の桜並木、昭和医大とぶつかって直結するところですか。それとも将来はそこに信号を設置して、上下線両方入れるような計画という考えなんか尋ねました。","respondent":"中島街路事業担当課長","answer":"今、見直し区間として２３０ｍありますけれども、この区間についての見直しの協議を警視庁としているですので。ですから今、委員の言われた中原街道の入り口の部分については今回の見直しの対象になってございません。","id":"exchange-005"},{"speaker":"須貝委員","kind":"質問","question":"西小山の駅前まででしたら道路幅も狭いし、途中までは、桜並木へ出るほんの１００ｍぐらいですか。あそこは一方通行ですから、あそこを相互交通にすればそんなに支障はないかと思うんですね。","respondent":"中島街路事業担当課長","answer":"城南信用金庫の位置がちょっと今あれなんですけれども、先ほどの繰り返しになりますけれども、今の西小山の駅から中原街道に向かっての２３０ｍの区間の見直しということですので。","id":"exchange-006"},{"speaker":"須貝委員","kind":"意見","question":"後、相互通行だと幅員の問題も結構ありますよね。そうすると、交通量もそこら辺も増えてはきますけど、相互通行だとちょっと狭いのかなというとの意見を述べました。","respondent":"中島街路事業担当課長","answer":"今、須貝委員がおっしゃるとおり、幅員１１ｍは非常に厳しいです。車がくねくね曲がりながらお互いを通るようなことを考えていまして、できれば、うまくいくのであればそこもやっていきたいです。","id":"exchange-007"},{"speaker":"須貝委員","kind":"質問・要望","question":"要望なんですけれども、その辺は十分地元の意見に配慮していただいて、ご検討くださるよう要望いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"西本委員","kind":"質問・要望","question":"武蔵小山駅東地区の再開発準備組合についてちょっと教えていただきたいんですが、この関係はどういう関係になっているんでしょうか。ここは再開発になっているわけですから、再開発準備組合の区域だけであって、ほかのところは考えないということなんか尋ねました。","respondent":"伊勢住環境整備担当課長","answer":"それから８８名の権利者の件ですけれども、皆さんは１００％を目指すけれども、当面は８０％ぐらいを目指していきたいと。できるだけ多くということ、今の状況はそんなようなことです。","id":"exchange-009"},{"speaker":"西本委員","kind":"質問","question":"Ｅ地区、Ｆ地区、Ｄ地区というのは全く別々に計画されているということなんですか。全体的に考えながら計画を立てていくべきではないかなと思うんですが、そういう形になって調和がとれていくのか、そこら辺はいかがなんか尋ねました。","respondent":"伊勢住環境整備担当課長","answer":"今後ガイドラインが地区の再生方針の中で、６月１５日の地区計画では、手法としては必ずしも再開発だけとは考えておりません。今のところはこの地区でそういう地元の方の熱意といいますか、そういう気運が盛り上がってきているです。","id":"exchange-010"},{"speaker":"西本委員","kind":"質問","question":"そこの中に例えばＤ地区の方たちが一緒にやりたいとなってきたら、そこも含めてまたみんなで考えていくという形になっていくんでしょうか。例えば街ですから、ある一定の統一した景観も含めて進めていくほうが、将来的にはいいんじゃないかなと。","respondent":"伊勢住環境整備担当課長","answer":"その中で地区計画の方針区域が３.１haで告示されておりますけれども、そのコンセプトは、そういうものはこの区域全体で統一されたものになります。それから例えばＧの下の部分の方がそこだけで単独でということであれば、単独で事業を進めるということになっております。","id":"exchange-011"},{"speaker":"南委員","kind":"質問・要望","question":"あそこの地域に現在住んでおられる方たちの構成というんでしょうか、その辺を概略的に教えていただきたいのと、Ｃ。地権者の関係では８８名のうちの５４名が入られて６１％というんですが、そういうところもわかったら教えてほしいと求めました。","respondent":"伊勢住環境整備担当課長","answer":"居住者は約２１０世帯の人口が３５０人です。申しわけございません。","id":"exchange-012"},{"speaker":"南委員","kind":"質問","question":"自分たちのまちに愛着があるし、どういうまちにしていこうかというそれぞれのいろいろなイメージというのは持っておられると思うんですね、だれしも。その辺についてはどういうふうに区としては考えていらっしゃるんか尋ねました。","respondent":"伊勢住環境整備担当課長","answer":"先ほどの８８名は所有者、これを進めるに当たって、その辺は地権者の方とご相談する。大家さんと一義的にはやるようなお話かなと考えています。","id":"exchange-013"},{"speaker":"南委員","kind":"質問・要望","question":"それともう一回継続するのかについては相談をしていただきたいというお話なんですけれども、その辺についても継続していけるかどうかは、最終的には。あるいはＤ地区でも、戻ってきて営業を再開したいんだという方たちはどの程度いらっしゃるのか、それについてもお伺いしたいと思います。","respondent":"岩田まちづくり事業部次長","answer":"前にもちょっとご説明申し上げたと思うんですけれども、この地区計画全体の区域は法律に基づいていろいろな網をかけます。まだ法律でスタートする以前の、まず地権者の方たちの意見の合意と事業が成り立つかどうかをこれからきちっと検討していこうと、こういう段階です。","id":"exchange-014"},{"speaker":"南委員","kind":"質問","question":"その辺のことをどういうスタイルとして設定されているのかというのを１つ伺いたいのと、それを伺うということと、例えば都心共同住宅ですから。１階でやるのと、地下でやるのと、その辺についてはどういうふうに考えたらいいのかということも教えていただいて終わりにしたいと思います。","respondent":"伊勢住環境整備担当課長","answer":"それから、公的に公共団体がそういう方の意見を取り入れてやっていく仕組みというのはないと考えております。ただ都心共同住宅供給事業を予定しているということで、できるだけ大家さんと店子さんの関係ですけれども、何度も指示しているところです。","id":"exchange-015"},{"speaker":"南委員","kind":"質問・要望","question":"品川の区民として、積極的に自治体の方がそういう方々への思いを伺う場面というのは提供していく必要があるんじゃないかと思っているんです。だから、せっかくのまちづくりという大きなフレームの中でやっている事業ですから、何らかの形でそういう努力をしていただきたいと思っています。","respondent":"岩田まちづくり事業部次長","answer":"法定再開発の場合、ただ当地区はもともと１０年近く前から、ここの商店街の役員が中心になってずっと勉強会を続けてこられたんですね。基本は中心に活動されているのは商店の方というふうに我々は考えておりますので、この地区においてはまずないだろうと考えております。","id":"exchange-016"},{"speaker":"中塚委員","kind":"質問","question":"視察で武蔵小山駅周辺を歩きまして、一番通りを歩いて、周りを見ても２階建ての低層が多くて、高くてもぱっと見でも七、八階ですかね。なぜここがイコール１９階建てになるのか、ここがよくわからないので、この街並み、Ｄ地区の目的を教えていただけますか。","respondent":"岩田まちづくり事業部次長","answer":"これは今回、大体ここはこういう方針に基づいて、街区ごとに大体整備計画を建てられれば何％ぐらいの容積までは最大認められますよと。建設費、補償費を賄って事業をやる、こういう仕組みだというふうにご理解をお願いしたいと思います。","id":"exchange-017"},{"speaker":"中塚委員","kind":"質問・要望","question":"もちろんマンションですから、震度５、６で倒れるということはないでしょうね、できたばかりのマンションだから。この１９階建てというのが本当に武蔵小山のまちにとって求められている姿なのか、どうしてもそれが理解できないので、もう一度教えていただけますか。","respondent":"岩田まちづくり事業部次長","answer":"こういう密集市街地というか、大都市においてはある程度上に積んで、その分空地をつくり出していくしか事業手法としてはないわけですね。","id":"exchange-018"},{"speaker":"中塚委員","kind":"質問","question":"同じ面積のところで上に伸びるわけですから、当然そこに人口が増えるわけですよね。建物が倒壊された方がとりあえず、収容人数ですか、あそこで暮らしているんですかね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/664767?Template=document&Id=6308#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=16&TermStart=2005-01-01&TermEnd=2005-12-31"}],"sourceMeta":{"pages":0,"characters":23010,"voices":59}},{"id":"h17-20050901-14","meetingId":"h17-cm09","date":"2005年9月1日","dateIso":"2005-09-01","committee":"行財政改革特別委員会","time":"","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を35件整理しています。","topics":[{"id":"topic-01","title":"行財政改革に関すること」のうち、「民間委託等に関すること","agenda":"行財政改革に関すること」のうち、「民間委託等に関すること","exchanges":[{"speaker":"川西副委員長","kind":"質問","question":"一つだけ伺います。そういった中身は、福祉高齢事業部以下の施設と同じようになって、議会からの評議員というのはなくなるというふうに考えてよろしいか尋ねました。","respondent":"榎本行財政改革担当課長","answer":"建物の運営企業者を指定しているという形になりますので、その団体自体は変更はないということで、それを公の施設が受託するのかしないのかというところの切り分けになっております。","id":"exchange-001"},{"speaker":"川西副委員長","kind":"質問","question":"今度、指定管理者制度で自由な運営が目的に沿ってできますよね。ですから、何も議会選出の評議員なんか要らない、その分は、区民公募でやるよとこの団体が言えば、そうなるのかどうかということを聞きたいだけです。","respondent":"榎本行財政改革担当課長","answer":"その財団の運営と、公の施設の指定の管理というのは別の項目になりまして、財団運営自体は今と変わりません。きゅりあんという建物の維持管理をだれが受託するのかということで考えておりますので、そのことと財団の運営とは別物という形でお考えいただきたい。","id":"exchange-002"},{"speaker":"川西副委員長","kind":"質問","question":"暗黙の了解として、公設民営でやってきましたから、ある程度、有能な理事者の方を送り込んで活動してもらっている。そういうのは、こういうふうなシステムに変わるとできるのかできないのか伺いたい。","respondent":"榎本行財政改革担当課長","answer":"指定管理者としての受託先と、法人としての運営というのは、形式的には別物という形になりますので、できます。ただし、この類型２というのは、政策目的によってそういう形をとってきたという形で、今現在こういう形に整理してきたです。","id":"exchange-003"},{"speaker":"林（宏）委員","kind":"提案","question":"２ページ目の指定期間のところには、提案型公募（プロポーザル方式）という言葉が出てくるんだけど、プロポーザルで公募型でないのってあるんですか。だから、公募型プロポーザルという言葉が、正しい表現なのかどうかというのを最初に確認したいんだけどとの意見を述べました。","respondent":"榎本行財政改革担当課長","answer":"特定の登録しているところだけに声をかけて募るという形も考えられますので、公募型プロポーザルと、普通のプロポーザル型という形があり得ます。","id":"exchange-004"},{"speaker":"林（宏）委員","kind":"意見","question":"その辺の分け方と同じというふうに認識をしておけばいいのか、その辺の整理をちょっと聞かせてくれますか。今、お答えの中だと、指名型というのも出てくる可能性があるようなお話だったんですけれども、その辺をもう１回説明を求めました。","respondent":"榎本行財政改革担当課長","answer":"基本的にはそういう形で、広い部分と特定の限られた方だけにプロポーザルをお願いするという形で、範囲としては同じ形があり得ます。","id":"exchange-005"},{"speaker":"林（宏）委員","kind":"質問","question":"一番最後のページのスケジュールのところで説明をされてきたんだけど、１１月のところが指定管理者の指定の議決というふうに書かれているわけですね。個別の話で、議会の仕事ということは、この指定に限定されているんか尋ねました。","respondent":"榎本行財政改革担当課長","answer":"議会の議決という意味で行くと、この指定の議決という形があります。指定議決のときのみ、指定期間満了後の更新をするときにもう１回指定議決をいただいて、そのときが議会の関与の形態という形になります。","id":"exchange-006"},{"speaker":"林（宏）委員","kind":"提案","question":"今度の定例会にそれぞれ提案されてくるという意味で、１１月の指定の議決をしますと、そこと協定書を結んでくるわけですよね。Ａ業者と協定を結ぶのに、議会側の考えが伝わらないという懸念があるんだけど、その辺についてはいかがか尋ねました。","respondent":"榎本行財政改革担当課長","answer":"その３点、団体の名称、指定期間というものが議決すべき事項だという形になっております。実際には、そういう個別の条項までは入らなくても、大枠としてどういうふうに事業を運営しようかというものは十分説明をした上で議決をいただいて。","id":"exchange-007"},{"speaker":"林（宏）委員","kind":"提案","question":"提案がこういうふうにすばらしいから、会社に決めていくということで提案されてくるんだろうと思うんだけど、協定書の中に入ってくるんだろうと思う。いわゆるプロポーザルをされた提案の次に来る部分が、非常に大事だろうと思うんですよねとの意見を述べました。","respondent":"新美企画部長","answer":"より強化されたというふうに私どもは考えておりますし、今回でいえば第４回定例会のときには、当然ご説明する。この案件に付随する説明事項というふうになっていくかと思いますので、ご意見いただき、実際上はなっていこうかと考えています。","id":"exchange-008"},{"speaker":"林（宏）委員","kind":"確認","question":"その中で、直すとかいう話もできるというようなふところの深いお考えをお持ちいただければ幸いだなと思うので、お願いだけしておきます。それからもう１点だけ、確認だけします。","respondent":"榎本行財政改革担当課長","answer":"包括的な業務委託の範ちゅうという形で考えられるので、公の施設として独立した施設を個別に洗い出して、こういう形に移行していくという方針です。","id":"exchange-009"},{"speaker":"飯沼委員","kind":"質問・要望","question":"この辺の根拠をもう１回改めてお聞きしたいのと、３点目の選定のところで、指定委員会の構成メンバーも聞きたい。選定委員会の公平性とか透明性というのは、どういうところで確保されるのかお聞かせてほしいと求めました。","respondent":"榎本行財政改革担当課長","answer":"何年間かに１回、５年間に１回は、指定管理者で一々５年とかごとにチェックがかかるようにするよりはずっと望ましいだろうという考えです。","id":"exchange-010"},{"speaker":"飯沼委員","kind":"質問・要望","question":"その点が１点と、ここは握って離さないというところがあるのかどうかお聞かせいただきたいのと、審議会は非公開にもなっていますよね。だからここが選ばれたんだというような、だれもが見たり聞いたりしてはっきりするような、そういった中身というのは出るんか尋ねました。","respondent":"榎本行財政改革担当課長、新美企画部長","answer":"区でも設置して管理できる、民間事業者が活用できない仕組みになっていたというのが、まずこの管理委託制度だった。民間事業者の中で、一概には… 実績のある方が基本的になじむ制度という考え方で、実質上の地域の方々との協働の方式、そういったもう一つの地域連携の方式を探っていく。… その選考経過等を説明した上で、その段階ではそういう形で説明をした上で、なぜそうなったかという形に入っていくような形になっております。","id":"exchange-011"},{"speaker":"沢田委員","kind":"質問・要望","question":"ここの３ページ目の一覧表の中で、別表１－１の部分なのか、どういう出方をするのかちょっとわからないので教えていただきたいんですが。","respondent":"榎本行財政改革担当課長","answer":"条例の出方は、結論的には別表１－１と１－２、両方とも関連条例と書いてある、その設置条例の条例改正案として出ます。別表１－２の方につきましては、管理委託制度をとることができるという条文が入っていますので、それを削除するというのが端的な内容です。","id":"exchange-012"},{"speaker":"沢田委員","kind":"質問","question":"これも指定管理者制度の明文化を条例ですると、この部分も全部、委託のやり直しになるんですか。そこらのやり方をちょっと教えてほしいんです。","respondent":"榎本行財政改革担当課長","answer":"１８年４月が年度別で切りがいいので、４月を目指して、区の方として方針を決めたという形です。ですから、現行の切りかえだというふうに思っていただければと思います。","id":"exchange-013"},{"speaker":"沢田委員","kind":"意見","question":"この類型１の部分ですね。その辺は、都市整備公社のあり方そのものも、変更を考えた上でのことなのか、そこらの考え方をちょっと聞かせてほしいんですとの意見を述べました。","respondent":"榎本行財政改革担当課長","answer":"そういう経由事務に関してはなくなるという形で、ほかはまだいっぱい業務がありますので、それについては特に変わるものではございません。","id":"exchange-014"},{"speaker":"沢田委員","kind":"意見","question":"改めて、都市整備公社が、今、やっている仕事のほかにどんなものがあるのか。指定管理者制度をどんどんやっていくと、都市整備公社の存在そのものに触れてこないのかどうなのか、ちょっとわからないので説明していただけますかとの意見を述べました。","respondent":"榎本行財政改革担当課長","answer":"入居管理、それから建物的には、メープルセンターの部分の維持管理等を行っております。その他、あと駐車場等の設備の維持管理も行っておりますので、それは従来どおり行っているという形です。","id":"exchange-015"},{"speaker":"鈴木（真）委員","kind":"確認","question":"ちょっと確認なんですけど、指定期間が５年になっていますよね。５年過ぎたときにどうするような形になるのか、その辺の確認をちょっとさせてください。","respondent":"榎本行財政改革担当課長","answer":"制度的には５年で見直すという形になっておりますけれども、政策目的的にここがいいという特命でやっていく、継続でやっていくという判断が大きく分かれると考えております。","id":"exchange-016"},{"speaker":"鈴木（真）委員","kind":"意見","question":"例えば５年後、今の指定管理者でいいんだという判断があると、どうとるのかなという疑問がちょっとあるんですけどとの意見を述べました。","respondent":"新美企画部長","answer":"ただし５年ごとに、言ってみれば継続も含む評価をするというような仕組みで運営していったほうがいいのではないかと考えているところです。とりあえず１８年度は継続でやって、最初の委託から５年後に、同じところに行くかもしれないという選定の手続をとっていく次第です。","id":"exchange-017"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"殊に直営の、別表の３番あたりなんかに行きますと、健康センターですとか、有料駐輪場というと、いろいろなものが出てくると思うんですね。同じ次の５年間ということにならないような形、効率的になるような形でお願いしたいなと思いまして、これは要望にしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"武内委員","kind":"質問","question":"そうすると、この３枚目の、第３回定例会で改正が必要となる施設と、今後必要な施設と、全部出していただいているんですけど、品川区で来年９月までですか、指定管理者に移行するかどうかということの対象になるのがここに全て載っているというふうな考え方でよろしいか尋ねました。","respondent":"榎本行財政改革担当課長","answer":"方針の１ページ目の、１ページ右側の真ん中あたりですね、その他の直営施設もまだあります。今後民間事業者の動向等を踏まえた上でまた考えていかなければいけないということで、当面考えられる部分はここの別表に全部載っているという形です。","id":"exchange-019"},{"speaker":"武内委員","kind":"質問","question":"特には類型１の部分のいろいろな趣旨、別表１－１に関しては当てはまらないということなのかどうかということと、特に別表１－１に関しては。その辺を説明を求めました。","respondent":"榎本行財政改革担当課長","answer":"例えば別表１－１の部分で、区が先取りをして、民間企業を活用してやってきたという形です。こういう民間企業へ直接、適法にきちんとできるという制度ができましたので、その趣旨は生かしていきたいと考えています。","id":"exchange-020"},{"speaker":"武内委員","kind":"意見","question":"わかりました。この別表１－１の区営住宅、この別表３の方で健康センター、理由みたいなのがありましたらとの意見を述べました。","respondent":"榎本行財政改革担当課長","answer":"業務委託開始から５年たった時点で、新たな次の公募プロポーザルという形で考えておりまして、今のところ１９年度からの変更を予定しております。１９年度４月からプロポーザルの結果に基づいたところに委託をするという考えで準備を進めるという予定です。","id":"exchange-021"},{"speaker":"林（宏）委員","kind":"質問","question":"２回目で申しわけないんだけど、一番最初の１行目に書かれているんだけど、「管理委託制度が廃止され」と書いてある。管理委託をするという内容じゃないのかなということで聞いているんだけど、その辺の仕切り線、ちょっと説明を求めました。","respondent":"榎本行財政改革担当課長","answer":"実際には、委員のおっしゃるとおりです。管理委託制度から指定管理者制度という形を便宜的に使っているだけで、指定管理者制度がやることは、公の施設の管理を行うという形です。","id":"exchange-022"},{"speaker":"林（宏）委員","kind":"確認","question":"要は、それに指定管理者になってもらうということで、中身は従来と同じという理解をしておけばいいわけだよね。ちょっと確認させてください。","respondent":"榎本行財政改革担当課長","answer":"委員のおっしゃるとおりです。","id":"exchange-023"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"制度が変わったから管理委託ではありません」というようなやりとりになりかねないので、ちょっと整理をしていただきたいなと思うんだけど、その辺はどういうことになるんですかね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"林（宏）委員","kind":"質問","question":"その辺はわかりました。それで、業務委託に限定されたときは指定管理者制度でなくても、民間委託ができるというふうに理解していいんか尋ねました。","respondent":"榎本行財政改革担当課長","answer":"業務委託の場合には、いろいろな形態がありますけれども、民間企業に今までも委託していますし、例えば庁舎ですと清掃の委託ですとか、受付の委託ですとか、そういうのはみんな業務委託という形態の中で入ってきているという形です。","id":"exchange-025"},{"speaker":"林（宏）委員","kind":"質問","question":"団体と、いわゆるその施設の内容的な、いわゆる業務上のノウハウを持っている会社と２種類ありますね。両方備えている会社ももちろんあるわけだけど、そうすると、ＪＶ的なプロポーザル参加というのも認められるんか尋ねました。","respondent":"榎本行財政改革担当課長","answer":"他自治体の例を見ていますと、そういう形で参入しているのが多いです。ＪＶを組まないと、一体の施設を受託したときに包括的な管理ができないという形になりますので、ＪＶの例はいっぱいあります。","id":"exchange-026"},{"speaker":"林（宏）委員","kind":"意見","question":"その辺はきちんと伝えておかないと、さっき言った「個人はだめですよ。ＪＶもよしというのをきちんと伝えておかないと、その辺はきちんと公にするときに伝えてほしいなと思いますので、よろしくお願いしておきますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-027"},{"speaker":"鈴木（真）委員","kind":"質問","question":"議会にはそのときはかからないで、そのまま流れるんですか。指定されちゃっているから、その契約の期間の延長だから指定になるのかどうか、そこら辺がちょっとわからなかった。","respondent":"榎本行財政改革担当課長","answer":"指定の議決につきましては、指定期間が何年度から何年度と定められておりますので、それの切れる前年度にもう１回指定の議決を議会に諮っていただくという形でないと、翌年度からの指定管理委託ができないという形になります。","id":"exchange-028"},{"speaker":"川西副委員長","kind":"確認","question":"私は誤解していたから確認だけしておきたいんですが、例えばこの３ページの特養ホーム、このほかにもありますよね。ですから、これらの、大変な仕事を区がこの１年間なりにするんだなと思っていました。","respondent":"新美企画部長","answer":"社会福祉法人立です。ということで、区立施設でないので、ここには挙がってこないということです。","id":"exchange-029"},{"speaker":"川西副委員長","kind":"質問","question":"そういう関係にあるところは、管理委託じゃなくて、どういう形になっていくのか教えておいてください。","respondent":"新美企画部長","answer":"現行と同じで、社会福祉法人の事業として、社会福祉法人が適切に継続する間は事業が継続されるです。","id":"exchange-030"},{"speaker":"沢田委員","kind":"質問","question":"汚職・腐敗というのは、業界と官僚がいろいろな形でくっついちゃって起きている、それを制限をする条文というのはないんですか。民間ならだれでも参入、手を上げることが、プロポーザルなり何なりにできるんか尋ねました。","respondent":"榎本行財政改革担当課長","answer":"指定管理を選ぶときに１００社からもらうのか、それとも１０社ぐらい参入すればいいのかというところで、そういう要件を定めるような形になっています。","id":"exchange-031"},{"speaker":"沢田委員","kind":"質問","question":"例えば、法律で補助を受けている団体だとか、そういう団体は指定管理者として手を挙げることができないというような縛りみたいなものはないんか尋ねました。","respondent":"榎本行財政改革担当課長","answer":"そういうような縛りは、法律上ございません。この自治法の管理委託の制度という形の中では、そういうような縛りは特に規定されておりません。","id":"exchange-032"}]},{"id":"topic-02","title":"議員定数に関すること」でございますので、事務局長以外の理事者の皆さんは、どうぞご退席をしていただきまして、自席でお仕事の方をお願いいたします。 それでは…","agenda":"議員定数に関すること」でございますので、事務局長以外の理事者の皆さんは、どうぞご退席をしていただきまして、自席でお仕事の方をお願いいたします。 それでは…","exchanges":[{"speaker":"沢田委員","kind":"質問・要望","question":"そこらをもう一度教えていただきたいことと、９人の議員、議員のほかに年間２５万ドルから３０万ドルの活動費が交付されている。局長にいきなりこういう質問を言うのは酷だというのはわかっていて、ちょっと質問したいんですが。","respondent":"市岡区議会事務局長","answer":"それから２点目のご質問ですが、単に人数だけの比較はできないなということは、そのとおりだろうと思います。以上です。","id":"exchange-033"},{"speaker":"林（宏）委員","kind":"質問","question":"平均値がどういうふうにとらえられるかは別としても、極端に言うと１０倍ぐらいの数字になってくるわけで、これはいかんともしがたい。非常に難しい質問なんだけど、ここで言うべきことではないということであれば、ちょっとお答えいただけますか。","respondent":"市岡区議会事務局長","answer":"住民代表の中でも地域代表という性格がありますので、これも議員定数を考える場合の一つの大切な要素だというふうに、最近は言われているようです。この３点ぐらいが、今回いろいろ調査をする中から、特徴としてご報告できるだろうと思います。","id":"exchange-034"},{"speaker":"林（宏）委員","kind":"質問","question":"大きい歯車の中ですから、どういう機能が発揮されているのか、我々議員としての一つの責任だろう。基準をどこに持っていくかによって、導き出される数字がいろいろ出てくるというのが、正直なところの今の僕の考え方だと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/787035?Template=document&Id=5784#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2005-01-01&TermEnd=2005-12-31"}],"sourceMeta":{"pages":0,"characters":39192,"voices":85}},{"id":"h17-20050913-11","meetingId":"h17-cm09","date":"2005年9月13日","dateIso":"2005-09-13","committee":"自治制度特別委員会","time":"午後１時０５分～午後２時３０分","status":"正式会議録","sourceType":"formal","overview":"自治制度特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を34件整理しています。","topics":[{"id":"topic-01","title":"特定事件調査、都区制度改革・主要５課題に関すること","agenda":"特定事件調査、都区制度改革・主要５課題に関すること","exchanges":[{"speaker":"石田委員","kind":"質問","question":"都の見解が変わっていないということであると、もちろん区長会を支援していくことは構わないですから、そういう手段にも出るということ。これはただ意見だけで、あとはそのぐらいのきつい言葉も使ったほうがいいのではないかなと、これは私の意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"},{"speaker":"土井委員","kind":"質問","question":"私も最初に読ませていただいたときに、逸脱しているという書き方なんだけれども、逸脱していたらどうするのというところでは、やはりそれを明確に示してあげないと、どうもおわかりにならないのではないかと思うので、明確、簡単にでないと、なかなか世の中はうまくいかないようですから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"本田委員","kind":"質問","question":"「的」という言葉を２３区の議長会では入れていない。議長会のほうは、やはり今の事態の中で反映した文書でいくという正副委員長のお考えですけれども、その辺はどういう検討をされたのか尋ねました。","respondent":"市岡区議会事務局長","answer":"案文自体は当委員会でいろいろご協議をいただければいいと思いますが、ちょっと経過がありますので、私のほうからご説明申し上げます。ただ、基礎的自治体ということを正副のご議論の中で整理していただいたという経過です。","id":"exchange-003"},{"speaker":"本田委員","kind":"意見","question":"よくわかりました。２８日でもまた新しい方針がこの秋に出ると思いますので、そういう検討をして出されたのであれば、それはそれで問題ありませんので結構ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-004"},{"speaker":"塚本委員","kind":"質問","question":"２２区の議会のほうは、それぞれどんな感触があるのかどうか、うちはもうどうでもいいやという区があるのかどうか。もう１点は、基本的に決議ですから、今想定しているのはどういうところか尋ねました。","respondent":"原議長、山路委員長","answer":"一つということで、６点挙げられておりますけれども、こういったものについては各区とも文面の中に明記してくださいということは話しをされました。それから… 送付先についてですけれども、都知事、都議会議長、都議会の各派を予定しております。","id":"exchange-005"},{"speaker":"塚本委員","kind":"質問","question":"そうすると、他の議会は賛同ということに、２２区に品川区はこんなことを言ったよと知らせないのか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"土井委員","kind":"確認","question":"今の確認なんだけれども、２２区の区長と議長のところに送るんですよね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"堺委員","kind":"確認","question":"確認し合うという意味では、よそからもらいうちからもあげるということはしてもいいのかなと、やったほうがいいと思います。この案文で結構です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"塚本委員","kind":"意見","question":"法的措置のこともありましたし、手続的に文書の調整というのももう１回手続をやるんだなと思いながらも弱いのではないかなという気がします。入れるなら一番最初に、どこかに入れ込んでやるのが、ちょっと奇異に感じるけれどもとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-009"},{"speaker":"木下副委員長","kind":"意見","question":"そのまま載せさせていただいたというのが現状ということで、ご理解をほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-010"},{"speaker":"本田委員","kind":"質問","question":"これは大都市事務の政治に関しての、そんな意味での表現かなと思ったんですね。最後にまたこのように入れたのかなというふうに、私なりに感心していたんですが、議長会はどういう議論でこれを入れたんか尋ねました。","respondent":"原議長","answer":"今のような議論はちょっと出たのですが、特に取り立ててどうのという話は出ませんでした。","id":"exchange-011"},{"speaker":"塚本委員","kind":"意見","question":"こんな言葉づかいはあまり聞いたことがないね。「都区制度の構築と運用」ならわかるけれども、ちょっと考え方が違うんじゃないのとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-012"},{"speaker":"石田委員","kind":"意見","question":"例えば、今の財調そのものの財源のあり方、例えば固定資産税を含めたいろいろなものの運用も含めやり方を変えていく運用を構築していくんだよと。運用の構築という局長が言った部分はどこを指して言っているのかなと、ちょっと違うなと思ったから、それを聞きたいとの意見を述べました。","respondent":"市岡区議会事務局長","answer":"端的に言えば、自治法で実現した新しい都区制度の法制度どおりの実現を図るということで、都区制度の実現という意味しかなかろうと思います。","id":"exchange-013"},{"speaker":"塚本委員","kind":"意見","question":"この部分だけ直すなら、１項目減らして最初に入れ込んで総論的なことを文章をなおせば、持ちまわりで委員会を開かなくてもいいし、本文を直すならもう１回委員会を開くということになると思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-014"},{"speaker":"土井委員","kind":"意見","question":"最後の６項目目を最初の１項目目のところに包含するようなというのは、逆に一番最後に法的な手段も辞さないよということは、我々の決意としてあってもいいのではないかとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-015"},{"speaker":"若林委員","kind":"質問","question":"新しい１項目が増えるという理解でいいのですか。一番下に「自治紛争も含めた不退転の決意で取り組むことを表明する」というふうに変えてみると、すっきりとわかりやすいようにしたほうがいい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"土井委員","kind":"提案","question":"下の項に明解に書くというのも一つの手だろうということで先ほど提案したんですけれども、本文の中でも、明解にその部分が表明されていれば私はいいだろうと思いますが、皆さんのご賛同があればとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-017"},{"speaker":"堺委員","kind":"意見","question":"ある程度、あとは先ほどからご意見が出ておりますように６項目の一番最後の部分を１番目の中に包含するという形のほうが整理される。形としてはそのように整理した決議の案文になるではないかと、このように思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-018"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"私も今の意見に賛成です。具体的に５項目が入っているので、項目そのものは５項目にしたほうが、それであればここの時点で一致できるのではないかというふうに思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-019"},{"speaker":"土井委員","kind":"意見","question":"要するに、今の都の態度、対応では、我々としてはこれはもう紛争と言わざるを得ない方向に行っていますよ。我々はもう紛争ととらえてやりますよというものを打ち出さなければいけないのではないのとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-020"},{"speaker":"石田委員","kind":"意見","question":"そこに向かってそういう気持ちでやれよということは、幾らでも品川区議会として言えるわけで、その辺の文言がちょっとわからない。だけど、そのぐらいの言葉はしっかり伝えるべきだと思うんですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-021"},{"speaker":"本田委員","kind":"質問","question":"では法的手段というのは、具体的に取れる手段というのは何があるかということになりますと、一つは自治紛争調停ですね。それから、所管大臣が勧告というのですか、指導するということを申請するという二つ、そのほかに法的手段というのはありますか。","respondent":"日下部企画財政課長","answer":"区長会としても、いろいろな検討はしておりますけれども、その中で具体的に出ております方法は、今委員がおっしゃったような二つの方法です。","id":"exchange-022"},{"speaker":"本田委員","kind":"意見","question":"そのほかに何か法的手段があるかなと。ある意味では包括的になるから、法的手段も含めて不退転の決意でというのは、それはそれでも私はあまりこだわらないんですがねとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-023"},{"speaker":"石田委員","kind":"質問","question":"我々は怒ってしまうだろうけれども、それが不退転の決意が上にあるわけですから、一番その部分を強く言っているという形になるわけですよ。その項目にするほうが、相手に訴える力があるだろう。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"若林委員","kind":"質問","question":"紛争、紛争とそういうふうになっているんですが、具体的にもしそういう場面になりますと、品川区が東京都に対して、そういう機関に対してどう訴えるのか、そういう法的手段を品川区がやる、それとも２３区の区長会、議長会で、つまり両方あるわけか尋ねました。","respondent":"日下部企画財政課長","answer":"相手方の国のほうの窓口は総務大臣ということになります。おそらく、そういった意味ではおそらく２３区が連名で総務大臣に調停の申請を求めるとか、手順としてはそういう形になるのではないかと思います。","id":"exchange-025"},{"speaker":"若林委員","kind":"意見","question":"そうしますと、他の２２区との連携がやはりある程度必要だということになれば、項目の中には当然そういう考えでいくと入らないのではないか。以下の６項目を実現するために、要するに２２区に送付するとなれば、そういう表現しかないのかなというように考えますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-026"},{"speaker":"石田委員","kind":"意見","question":"それは区長に対しても、もちろん他区に対しても、それはしっかりと強く打ち出すべきだろうと。強く打ち出すには項目に入れたほうがいいと思うとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-027"},{"speaker":"土井委員","kind":"質問","question":"「以下の項目の実現に向けて」の「実現」のところに皆さんがこだわっているのだったら、それを取ってしまったらということになるので、問題はどれだけ強く打ち出すということをみんなが決議するかということですから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"やはり５項目の実現が目的であって、やはり５項目の中に法的な手段を目的として入れるというのは、決議文としては難しいような気がするんです。やはり本文の中に、５項目の実現に向けて法的手段ということで入れるのが、一番すっきりと文章としてはなるような感じがしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-029"},{"speaker":"本田委員","kind":"質問","question":"強い表現にどう入れるかということですから、今回第３回定例会で決議するわけですが、そういう事態はこれから来るのではないかなと思うんです。ですから、ここの委員会でもそういう議論がされたということを踏まえて、これでいいのではないですかね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"塚本委員","kind":"質問","question":"前回の委員会で、区長会のアピールがあったと思うんですけれども、これを引用すればいかがか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"堺委員","kind":"意見","question":"訂正した正副委員長案を再開後にお示しいただいて、その場で同意が得られれば、それで第３回定例会に持っていくという運びもいいかな。ただ、口頭での修正ということで賛成したいと思いますが、全体的に同意が得られるための手段として再度案文を出すということもいいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-032"},{"speaker":"塚本委員","kind":"確認","question":"今、休憩してやるのもひとつですし、正副一任を取りつけて後ほど正式な文を配付いただくのもあるし、議会運営委員会の直前に委員会を開いて確認を取るなど、いろいろな手段があると思うんですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"},{"speaker":"堺委員","kind":"意見","question":"私はなるべく早い時期に委員会としての意思統一を図るという形のほうがいいかなと思いましたので、休憩をとっていただき、案文を訂正後、再度委員会を再開していただいたほうがよいと思いますとの意見を述べました。","respondent":"山路委員長","answer":"正副で打ち合わせをしまして、案文を修正します。○午後２時００分休憩 ○午後２時２５分再開 ６番目は、内容に加味してありますので、同じような意味ですので、議長にもご説明を申し上げまして削らせていただきました。","id":"exchange-034"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/918758?Template=document&Id=5580#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=11&TermStart=2005-01-01&TermEnd=2005-12-31"}],"sourceMeta":{"pages":0,"characters":13062,"voices":87}},{"id":"h17-20050922-4","meetingId":"h17-c-settlement","date":"2005年9月22日","dateIso":"2005-09-22","committee":"決算特別委員会","time":"午後４時０７分～午後４時１６分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を2件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"若林副委員長","kind":"意見","question":"委員長にご推薦をいただきました。委員の皆様のご協力のもと、審議が滞りなく進みますように、委員長をしっかり支え守り努力してまいりますので、どうぞよろしくお願い申し上げますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-001"},{"speaker":"山村副委員長","kind":"質問・要望","question":"時計がとまりませんように、全力で目をこじあけまして、今回は頑張らせてほしいと求めました。私も委員長を全力でお守りいたしまして、体を張って頑張らせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/311242?Template=document&Id=1242#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2005-01-01&TermEnd=2005-12-31"}],"sourceMeta":{"pages":0,"characters":2453,"voices":18}},{"id":"h17-20050926-6","meetingId":"h17-cm09","date":"2005年9月26日","dateIso":"2005-09-26","committee":"区民委員会","time":"午前１０時０４分～午後３時０４分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を40件整理しています。","topics":[{"id":"topic-01","title":"第５４号議案、品川区立総合区民会館条例の一部を改正する条例","agenda":"第５４号議案、品川区立総合区民会館条例の一部を改正する条例","exchanges":[{"speaker":"林（宏）副委員長","kind":"意見","question":"基本のところで、どういうふうに変化があるのか、例えば権限の移譲だとか、そういうところのことをもう１回、条例の変更の部分は今わかりました。基本的に指定管理者になったら、今までとこう違うんだという説明をしてくれますかとの意見を述べました。","respondent":"長田区民課長","answer":"設置者たる地方公共団体が管理権限を有するというような部分になるわけですけれども、管理の基準、業務の範囲。主にこういった内容が変わってくるものであるというふうに理解をしています。","id":"exchange-001"},{"speaker":"伊藤委員","kind":"確認","question":"確認なんですが、条例で定めるという話があったんですけれども、矛盾した感じがするんですね。条例で定めて指定管理者がそれに従うんじゃないかと思うんですが、そのことについてのご意見を先にお願いします。","respondent":"長田区民課長","answer":"ご指摘いただいたことについてはそのとおりです。条例の定める範囲について、利用料金等につきましても、その範囲内において、指定管理者が区長の承認を得て決める、こういうことになってあります。","id":"exchange-002"},{"speaker":"伊藤委員","kind":"質問","question":"となれば、次の本会議までに業者を決める算段が多少あるんでしょうか。それから、それを具体的に選抜していく内容とか、その手順と方法について説明を求めました。","respondent":"長田区民課長","answer":"選考委員会とともに、それから選考の基準、こういったものによりまして選考をしていく。そういった部分と、それから費用的に効率が出るものというようなことの観点から選ばれる、こういう基準になってあります。","id":"exchange-003"},{"speaker":"伊藤委員","kind":"質問","question":"そういうところまで権限を与えてしまうんですかということが１つ。ですから、ほかの部分は対応していますよというきっちり線引きがほしいと思うんですが、いかがか尋ねました。","respondent":"長田区民課長","answer":"区民会館のほうは５億４,０００万円弱ですね、全体の経費でかかっておりますけれども、利用料収入が２億７,０００万円と記憶しております。ですから、その差額につきましては指定管理料というような料金で、区がお支払いをするというような形になってこようかと思います。","id":"exchange-004"},{"speaker":"伊藤委員","kind":"確認","question":"ですから、もう一つ確認したいのが、指定管理者制度に移行をすることについては、私たちとしては問題ないと思っています。ほかのところは民間に開放しながらコストを下げていきますよというその線引きをもう一度確認したいんですが。","respondent":"長田区民課長","answer":"ですから、例えばやりたいと手を挙げても、例えば小さな業者さんにはなかなか難しいだろうという部分があろうかと思います。第４回定例会までの間に私どものほうで選考基準によりまして、選考委員会の中で十分議論をしながら選んでいきたい、このように考えているところです。","id":"exchange-005"},{"speaker":"武内委員","kind":"質問・要望","question":"確認ですけれども、ここでは先ほどあるように、細かい内容までは全部決められていないというところがありますね。その中で区が業者がどこだとか指定管理者の方と区側のいろんな要望を入れながら、我々としてはわからないという考え方でいいんか尋ねました。","respondent":"長田区民課長","answer":"基本的には先ほど申し上げました手続きにより進めていくような形になりますので、第４回定例会の議案として提出をしていく。ただ、現状の委託を受けているところを継続するというようなことで、説明をさせていただいたところです。","id":"exchange-006"},{"speaker":"武内委員","kind":"質問","question":"どうだったかなと思ったんですけれども、またそういう議案のときに補足をしてほしいと求めました。こんなことでお願いしたい、どうもそれは変わらず、その辺のところはどうか尋ねました。","respondent":"山田区民生活事業部長、長田区民課長","answer":"１点だけ補足をさせてください。これから当然選定委員会を設置し、それから採算性についてということで、改めて聴取を図りながら厳密に選定はしていきたいと考えています。問題点等への対応ですけれども、利用の承認ですとか利用の料金、こういった部分についても指定管理者の権限になってきます。","id":"exchange-007"},{"speaker":"武内委員","kind":"意見","question":"そういう情報が区のほうへ上がってこないというようなことがあるとまた困るかなと、ちょっとそういう心配があるので、そういう部分についてをうかがいたいと思いますとの意見を述べました。","respondent":"長田区民課長","answer":"先ほど、一定の権限の中での裁量権が増えるよというようなことで説明を申し上げました。これから第４回定例会でご承認をいただくというようなことになれば、その協定の中できちっと結んでいきたいということで考えてあります。","id":"exchange-008"},{"speaker":"中塚委員","kind":"質問・要望","question":"若干説明を伺いたいのは、ここをまずはっきり教えていただきたいのと、条例に基づいて規則がありますよね。ここの規定は変わるのか、変わらないのか、ここをちょっと確認をさせてほしいと求めました。","respondent":"長田区民課長","answer":"現行のまま行く予定です。管理に関する部分、こういった部分の経費が指定管理者のほうへ入る、こういう形になろうかと思います。","id":"exchange-009"},{"speaker":"中塚委員","kind":"質問・要望","question":"その関係の中で、本来の目的が失われないのかどうか、その点をもう１回確認をしていただきたい。メイプルセンターとかはどういう形なのか、ほかのお話も教えていただけますか。","respondent":"長田区民課長","answer":"基本的には実績に基づく、実績が１つの成果ですので、それに基づいて算定をするというような形になろうかというふうに思います。ですから、そういった部分では今回の対象からは外れます。","id":"exchange-010"},{"speaker":"中塚委員","kind":"質問・要望","question":"実績に基づいて差し引き云々かんぬん、その辺わからないんですけれども、もう一度教えていただきたい。今後どこになるかは別にしても、その管理した先がきちんと区の情報公開の対象になるのかどうか、そこを教えていただきたいんですけれども。","respondent":"長田区民課長","answer":"これは大変難しい条件だというふうに聞いているところです。区の条例に準じましてそれぞれ規定をつくっておりますので、そういった中での情報公開というのは十分対応していけるというふうに思ってあります。","id":"exchange-011"},{"speaker":"中塚委員","kind":"確認","question":"指定管理という形で契約時にそのことをきちんと相手と確認しないと、こういうのを契約時に確認しないと、やはりこのまま情報公開が狭められる可能性。協定時というんですか、それにはっきりしないといけないんじゃないかなと思うんですけれども、いかがか尋ねました。","respondent":"長田区民課長","answer":"今度の１５条には、ご指摘いただいた部分については、協定書の中できちんと整理をするべき内容だというふうに思っているところです。それから情報公開の関係、こういった部分につきましては、協定書の中に明記するような形で準備を進めていきたいというふうに思っております。","id":"exchange-012"},{"speaker":"中塚委員","kind":"質問","question":"協定書の中に盛り込むという話ですけれども、これは条例の中に文言を入れられないかどうか伺いたいです。区民の心配、まずここを明らかにしてほしいと思っています。","respondent":"山田区民生活事業部長","answer":"情報公開についてはそれぞれの情報公開条例の中で対応されておりますし、それぞれの団体等が検討される中身ですので、このようにやりますというふうにご答弁は申し上げられないということでご理解いただきたいと思います。","id":"exchange-013"},{"speaker":"藤原委員","kind":"質問","question":"課長のご答弁を伺っていて、区の持ち物なんだから、まず権利と義務という最終的な責任は区が負うという義務があるわけですね。区としてどのようなもの申す権利といいますか、言っていくような、どういうチェックをしていくのか。","respondent":"長田区民課長","answer":"ですから、先ほどから申しているように、これは区の施設ですから、区として当然全体的な責任を持ちます。仮に間違った対応がされるようなことがあったり、これは区として当然その辺の是正について指導するべき立場にあるというふうに思っているところです。","id":"exchange-014"},{"speaker":"藤原委員","kind":"質問","question":"是正できる立場なんですね。外すというのか、業者の指定を外すという手続きというのは、どのようになっているんか尋ねました。","respondent":"長田区民課長","answer":"当然、１年ごとですと民間の対応がなかなかしにくいという部分がありますから、管理をお任せをするというようなことになろうかと思います。そういった部分については、そういった何か問題があって修正ができないような部分があれば、取り消しというような形になろうかと思います。","id":"exchange-015"},{"speaker":"藤原委員","kind":"質問","question":"５年って長くないですか。５年間、もっと細かに業者として管理者とやっていかなきゃいけないかと思うんですけれども、その辺はいかがか尋ねました。","respondent":"長田区民課長","answer":"実はこれはさきの行財政改革特別委員会でも説明をした内容ですけれども、区として方針を出しました。その辺については柔軟な対応ができるというようなことで規定をしているものです。","id":"exchange-016"},{"speaker":"木下委員","kind":"質問・要望","question":"ですから、そういう点ではオープンにやっていただきたいなという部分を考えております。そこら辺、もう一度詳しく確認で教えていただければ。","respondent":"長田区民課長","answer":"今後の手続きですけれども、先ほどちょっと申し上げましたけれども、当面、品川区立総合区民会館につきましては公募をする予定はありません。なおかつ経費的にも一定のところで抑えられる、こういったような業者の選考について、今後とも私ども努力をしていくつもりです。","id":"exchange-017"},{"speaker":"木下委員","kind":"提案","question":"いろいろ打診しても受け手がないというようなお話ですよね。提案制度であれば金額等、その中に含めるような形でその安いところでやっていただくような形をとらないと、それはお願いしておきたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-018"},{"speaker":"須貝委員","kind":"質問","question":"極論を言えば４億かかったんですけれども、区でその分を補填をしてくれるんですかという話にもなりかねないのかなと。そうすると、それもちょっときりがなく区の持ち出しが増えるということになるかと思うんですけれども、その辺はどのようにお考えなんか尋ねました。","respondent":"長田区民課長","answer":"逆に指定管理者を取り入れたらサービスが悪くなり、現状の中でも最低限でもその部分は確保できるんではないかというふうに思っているところです。","id":"exchange-019"},{"speaker":"須貝委員","kind":"質問・要望","question":"ただ、できれば、将来区が負担する応分の負担が減っていく方向にできるだけやっぱり持っていくような努力をしてもらいたいと思います。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"林（宏）副委員長","kind":"意見","question":"特に人が今どういう配置になっていて、指定管理者制度になると全くナッシングになるのか、その辺の人の配置の部分の違い。その辺の考え方が、ここだけじゃないと思うんで、事業部全体に言えることなんだけれども、その辺をちょっと聞かせてくださいとの意見を述べました。","respondent":"長田区民課長","answer":"２点目ですけれども、副委員長から出たように、直営に戻すというようなことは時代の逆戻りだろうというようなことだというふうに理解をしています。選定委員会の中で検討をする、こういうような手続きを踏んでまいりますので、このように判断をしています。","id":"exchange-021"},{"speaker":"林（宏）副委員長","kind":"質問","question":"僕は一般質問の中で市場化テストの話をして、区長も検討されるようです。じゃあやろうという地方公共団体の決意なんだから、その辺はもうちょっと前向きに物事をとらえてほしいなと思うんだけれども、それについて。","respondent":"山田区民生活事業部長","answer":"そうしたことを総合的に勘案して、いわゆるここを仮に現在の業者に３年間ということで指定したらどうだろうかと内部的には話をしているわけですね。より効率的なよりよいサービスということで検討していく時間だというふうにご理解いただけたらというふうに考えてあります。","id":"exchange-022"},{"speaker":"林（宏）副委員長","kind":"質問","question":"３年もかけなきゃ検討ができないようじゃどうにもならない。ちょっと細かい点で１点気になったのでお尋ねしておきますけれども、いわゆる区の独自の、そこの管理費を指定管理者に払うんか尋ねました。","respondent":"長田区民課長","answer":"今、ご指摘いただきました２施設につきましては、区が直接管理をするというような形になります。","id":"exchange-023"},{"speaker":"林（宏）副委員長","kind":"確認","question":"ソフトの部分も含めてということなんですか。とすると、それのいろいろ管理とか運営とかいうハード的な部分とソフトがあるから、そのすみ分けはどういうふうにするんか尋ねました。","respondent":"長田区民課長","answer":"この部分についても一定の、費用がかかるわけですけれども、これは区が直接その部分の経費については支払いをする。こういう形です。","id":"exchange-024"},{"speaker":"中塚委員","kind":"質問","question":"品川文化振興事業団が１億６,０００万円のアルゼンチン国債の問題を出した中での管理だからこそ、この部分というのは絶対に外せないと思うんです。それを理由として、この条例に対しては反対といたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"武内委員","kind":"意見","question":"区の直営になって、業務委託で今まで自主的に一生懸命やってこられた方が、そのまま運営管理をできるということなんですけれども、今までは、そうすると自主的にということなので。","respondent":"田村地域活動課長","answer":"あくまで条例上業務の委託という項目で、区の業務は業務でしたから、荏原区民センターのほうで金額で言いますと、人件費も含めまして３,９００万円。予算的には２,３００万円、その中の内訳で１,２００万円ほどが人件費ということで、そのような状況です。","id":"exchange-026"},{"speaker":"武内委員","kind":"意見","question":"そうすると、今度は区の直営になって業務委託ということで、全くこの辺のところはじゃあ、これから多少変わってくるかもしれませんが、大幅な金銭的な委託料の変更とか、業務内容の変更とか、そういうのは特にないのかどうなのかとの意見を述べました。","respondent":"田村地域活動課長","answer":"それと、若干気になるのが、指定管理者制度をとらない、直営に戻しました。それ以外のものについては、若干でも内容を精査して、区で直接して契約するというやり方を残す必要があるのかなというふうに思っております。","id":"exchange-027"},{"speaker":"武内委員","kind":"質問","question":"例えば、このグループの方から、逆にそういう団体をつくって、ＮＰＯとかそういうことで、指定管理者みたいな、そういう考え方というのは、そういう意見が出たのか出ないのかとか、もしくはそういう考え方というのについて、お伺いいたします。","respondent":"田村地域活動課長","answer":"人数も定めていますけれども、やはり町会の推薦だとかいろいろあって、固定したメンバーじゃない部分もあります。できれば、それぞれの委員長とすれば今までどおりの形で何とか引き続き業務を実施したいというような動きなので、そんな状況です。","id":"exchange-028"},{"speaker":"須貝委員","kind":"意見","question":"おそらく人件費のほうも区から委託されて、所長とか、そういう方たちの人件費がほとんどだと思うんですね。それが主体だと思うんですけれども、その辺をちょっとお考えをお聞かせ願えればと思うんですがとの意見を述べました。","respondent":"田村地域活動課長","answer":"それぞれ荏原区民センターのほうが３０名弱、それと東大井の運営委員が１８名、それぞれ町会長だとか地区委員の会長だとか掛け持ちでやっています。もっと運営委員会自体がもう要らないよという考え方があれば、現行の体制でしばらく様子を見ていきたい、そのように考えています。","id":"exchange-029"},{"speaker":"須貝委員","kind":"質問・要望","question":"ＯＢの派遣なんかも、地域の人の話とはちょっと違ったんですけれども、それはそういうことでよろしいんですか。例えば要望があれば、区のほうにまた直接要望を出しても言えるという感じが、それは、ちょっとお願いします。","respondent":"田村地域活動課長","answer":"１回は私のほうに直接ではなく、自主運営のところを尊重したいなと思いますので、よろしくお願いしたいと思います。","id":"exchange-030"},{"speaker":"中塚委員","kind":"質問","question":"２つの区民センターと区民集会所ですけれども、維持管理というか大規模改修というんですか、そういう場合はどういう形に今現状はなっていて、今後はどうなっていくのか、そこら辺を教えていただけますか。","respondent":"田村地域活動課長","answer":"まだ具体的に大規模改修という話はうちのほうは受けていません。そういう経費の部分は先ほど言った委託料の中で見込めませんので、我々のほうを通じて区のほうの予算要求にいくという形になろうかと思います。","id":"exchange-031"},{"speaker":"伊藤委員","kind":"質問・要望","question":"確認したいといいましょうか、この２つの施設の区の直営にする理由について、結果として運営委員会に業務委託していくわけです。なぜ法改正があったからという理由が一番大きな問題なのかもしれませんですけれども、ご説明をほしいと求めました。","respondent":"田村地域活動課長","answer":"そういうような、ましてや利用率を高めるための工夫もできるということが、やはり今回の直営に戻して委託するという形の一番のメリットなのかなと。","id":"exchange-032"},{"speaker":"伊藤委員","kind":"確認","question":"もう一つ確認したいのが、それぞれ先ほど３,９００万円と２,３００万円の委託料の話がありました。そういう委託料が上がっていくことと、それから、そういうことをどういうふうに考えていくんでしょうかということを説明を求めました。","respondent":"田村地域活動課長","answer":"今伊藤委員がおっしゃっていた内容は大変難しい話だと思います。幸いに、その都度予算がつくかどうかわかりませんけれども、その辺はもう一度実際に連絡調整をして考えていきたいというふうに考えております。","id":"exchange-033"},{"speaker":"伊藤委員","kind":"提案","question":"これは実際の事実の話ですから、今言った地域の皆さんのいろんな要望、これを担保する仕組みはどういうふうにしていくか。その運営委員会がしっかりされていらっしゃるわけですから、次の新しいステップに向けて提案なり予算の仕組みなり、いかがか尋ねました。","respondent":"田村地域活動課長","answer":"伊藤委員おっしゃるとおり、やはりこういう先駆的な地域の自主的運営の芽を摘んだりしてしまったら、本当に行政として重大なことになりますので、やはり連携をとりながら、状況も踏まえて今後も引き続き協力をしながら調整をしていきたい、そのように考えております。","id":"exchange-034"}]},{"id":"topic-02","title":"第７号および第１０号と進めていきたいと思いますので、よろしくお願いします。 それでは、請願第８号および請願第１１号…","agenda":"第７号および第１０号と進めていきたいと思いますので、よろしくお願いします。 それでは、請願第８号および請願第１１号…","exchanges":[{"speaker":"木下委員","kind":"質問・要望","question":"今回の軽減措置の目的は、本請願につきましても当然固定資産税および都市計画税の軽減措置の継続を求めるものであります。あくまでも固定資産税および都市計画税の軽減措置を求める趣旨の請願ですので、ひとつ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"},{"speaker":"武内委員","kind":"質問","question":"はいろんな２３区の中で、いろんな意見書がどこからか出ているのか、その辺がもしわかれば説明を求めました。","respondent":"太田税務課長","answer":"来年度、平成１８年度が３年ごとの評価替えの年になるですので、税制改正の動向等を踏まえて今後検討していくというような趣旨と聞いてあります。それから、２点目の他区の状況は申しわけございませんけれども、その後はちょっと聞いてございません。","id":"exchange-036"},{"speaker":"中塚委員","kind":"質問・要望","question":"請願趣旨の中で２３区の約６割に当たる２１万件の中ですと、品川区の状況をちょっとわかる範囲でいいんですけれども、区ではこの固定資産等の軽減措置について、どれぐらいの影響といいますか、恩恵といいますか、そういうのがあれば教えていただきたいんですが。","respondent":"太田税務課長","answer":"金額にすると１６０億円ということなんですけれども、固定資産税で約４,０００人、都市計画税のほうで約４,２００人。固定資産税が７億円弱、都市計画税でいいますと１４億５,０００万円ということで聞いてありますけれども、結果としてはそういう数字です。","id":"exchange-037"}]},{"id":"topic-03","title":"請願第６号および請願第９号、都市計画税の軽減措置の継続につき意見書の提出を求める請願","agenda":"請願第６号および請願第９号、都市計画税の軽減措置の継続につき意見書の提出を求める請願","exchanges":[{"speaker":"伊藤委員","kind":"確認","question":"東京都の事務の内容ですから、東京都が都議会が１年限りということでやっているわけですから、わからないですよね。ですから、確認したいのは、どこへ聞くんでしょうか、この意見書を出すことで、どれだけ区にメリットがありますかということをお伺いしたい。","respondent":"太田税務課長","answer":"メリットということは、意見書を出して東京都に区議会としての民意を出した、その結果として減額されれば、区民の方に還元がされるということになるのではないかと思いますけれども。","id":"exchange-038"}]},{"id":"topic-04","title":"請願第７号および請願第１０号、小規模非住宅用地の固定資産税・都市計画税の減免措置の継続につき意見書の提出を求める請願","agenda":"請願第７号および請願第１０号、小規模非住宅用地の固定資産税・都市計画税の減免措置の継続につき意見書の提出を求める請願","exchanges":[{"speaker":"林（宏）副委員長","kind":"意見","question":"わかっていてほしいのは、区の財源とかかわりあるものなんですよ。財源についてはしっかりと皆さんもわかっていらっしゃるということで、違うんだということだけわかってほしいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-039"},{"speaker":"須貝委員","kind":"質問","question":"今回、創業支援センターということなんですけれども、これは製造業の方が主に使われるんでしょうけれども、動力は入っているんですか。観測だけなのか。","respondent":"金子産業振興課長","answer":"こちちはそういった工場、そういった機器を設置することはできませんので、例えば製造業のいわゆる本社機能といいますか、企画営業部分であるとか、あるいはそういう開発部門とか、そういった部門を想定しているものです。","id":"exchange-040"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/678828?Template=document&Id=2436#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2005-01-01&TermEnd=2005-12-31"}],"sourceMeta":{"pages":0,"characters":41824,"voices":127}},{"id":"h17-20050926-7","meetingId":"h17-cm09","date":"2005年9月26日","dateIso":"2005-09-26","committee":"厚生委員会","time":"午前１０時０５分～午後２時２９分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を57件整理しています。","topics":[{"id":"topic-01","title":"の１、議案審査","agenda":"の１、議案審査","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"平成１６年度の障害者福祉会館の指定管理者制度導入の折にも、その点も含めて幾つか伺いたいと思います。欠格事項というのですか、そういった点については、どこを担保されていくのかということを教えてほしいと求めました。","respondent":"早津高齢福祉課長","answer":"全体の調整が企画財政でやっている関係で、私の把握している限りでご説明したいと思います。先ほどの説明の中でも個別の休業日の扱いが違っているですとか、包括条例を選ぶか個別条例を選ぶかというような選択になろうかと思います。","id":"exchange-001"},{"speaker":"飯沼委員","kind":"質問・要望","question":"お伺いしたいのですが、一つは候補者選定の透明性の確保で、議会の代表として中身をどうチェックできるのかということを具体的にお願いします。実際に情報公開を求めたときに、管理とか経費とか収支の中身を求めたときに実際に出てくるのかどうか、その辺をもう１回確認させていただきたい。","respondent":"早津高齢福祉課長","answer":"当然情報公開請求をしても個人情報であったり、先ほどお尋ねになったような決算ですとか、そういうようなことは公開になるものと考えています。それから、管理予定者の職務内容が従来どおりかどうかというお尋ねということでよろしいでしょうか。","id":"exchange-002"},{"speaker":"飯沼委員","kind":"質問","question":"従来どおりのところに指定するということは、条例の中にその点は盛り込まれているでしょうか。根本的なところをお伺いしたかったんです。","respondent":"早津高齢福祉課長","answer":"むしろ、記載できないと言ったほうがよろしいかと思います。改めて議案のときに説明しますが、そのまま指定管理者にする方針であるということを、今の段階でご説明しているというものです。","id":"exchange-003"},{"speaker":"飯沼委員","kind":"質問","question":"現行で出せる範囲は指定管理者制度になっても変わらないで資料は出てくるという受けとめ方でいいですか、その点が１点。結局、議決のところでしか意見が言えなくなるということでしょうか、指定の相手について。","respondent":"早津高齢福祉課長","answer":"指定管理者になったからといって規定が変わるわけではありませんので、情報公開をできるかどうかについての判断は別ものだというふうに思います。現在請求して出してもらったことがあれば、例えば個人情報といったものは、指定管理者後でもだめであろうというふうに思います。","id":"exchange-004"},{"speaker":"飯沼委員","kind":"質問","question":"情報公開のところですけれども、情報公開条例に準ずるという程度のとらえ方がいいのでしょうか。委託をした区というとらえ方でいいのかどうか、その辺のとらえ方がよくわからなかったので質問をさせていただいたんです。","respondent":"早津高齢福祉課長","answer":"したがいまして、管理委託のときから区の条例が直接適用ではなくて、管理委託を請け負っている法人の中での判断になるものです。これを類推しますと、先ほど申しましたように、管理委託をしている団体が文書等に取扱いについて判断するということになろうかと思います。","id":"exchange-005"},{"speaker":"飯沼委員","kind":"意見","question":"そういった面では、各条例のところに個人情報保護のことは書いてあるんですが、情報公開のところがないんですね。そういった面でそれを書き込むこと自体は可能なのか、それを書き込むことに弊害があるのかどうか、その点を大きなところで１点との意見を述べました。","respondent":"早津高齢福祉課長","answer":"先ほど申しましたように、事業者としてどう考えるかということになっているのが基本だと思います。罰則規定というような関係がありますので、より確認をするために条例の中で規定を定めたものと理解しています。","id":"exchange-006"},{"speaker":"川西委員","kind":"提案","question":"確認をしたいんですが、区で指定管理者として指定するという選定のところまでだと、議会の議決を経る前のところですね。候補者の選定の前の段階の報告、ですから条例提案ですねとの意見を述べました。","respondent":"早津高齢福祉課長","answer":"この各法人を予定しているというのは、区の方針として決めているですが、当該の法人からはしていただきます。今回の６議案については行わずに、公募型はしませんけれども、予定のところには手続に定めるとおり申請手続をしていただくということになります。","id":"exchange-007"},{"speaker":"川西委員","kind":"質問・要望","question":"新しいところについては、いわゆるプロポーザル、公募式でやったと。今後指定管理者制度を区がもっと進めていく場合のあり方とのつながりがわかると思うので、ちょっと説明してほしいと求めました。","respondent":"早津高齢福祉課長","answer":"区の基本的な考え方といたしまして、公募型のプロポーザル方式という、旧亀田邸で行ったものを原則とするという考え方は持っております。それ以外の既存施設につきましては、今回については公募型ではなくて、既存の法人から申請をしていただくというものです。","id":"exchange-008"},{"speaker":"川西委員","kind":"質問","question":"直接条例に関係ないんですが、監督官庁ですね。先ほどは障害者施設については都道府県であり、老人保健施設については区という考え方でよろしいか尋ねました。","respondent":"早津高齢福祉課長","answer":"それから、監督官庁といった場合にちょっと説明しにくいのは、例えば特養の場合を取りますと、介護保険施設としての監督官庁は都道府県になります。","id":"exchange-009"},{"speaker":"飯沼委員","kind":"質問・要望","question":"個別のところを具体的にお伺いしたいのが何点かあります。デイサービスの食事代が１０月からどうなるのか、またそういうところはどこで決めていくのかというあたりをまず聞かせていただきたいんですが。","respondent":"早津高齢福祉課長、石田委員長","answer":"この条例の中で新の第７条の２項、ここで読めるということで、この条例の改正には及ばないです。デイサービスセンターの昼食についてもあわせてご説明させていただきたいと思いますので、そちらのほうでということでよろしいでしょうか。 全くそのとおりで、内容が伴う部分と介護保険等の問題もありますが、それを踏まえてお考えいただいて質問していただきければと思います。それはそれで結構ですので、やる場所はたくさんありますので。","id":"exchange-010"},{"speaker":"飯沼委員","kind":"質問","question":"盛り込まれているということがわかったので、後で特養のところで食費について、また後でここの態度は決めていきたいと思っています。修繕にかかったりした場合の業者選定とか費用の負担がどこでどう出されるのか具体的にわからないので、その辺を説明を求めました。","respondent":"蓼沼高齢事業課長","answer":"改修、保全等の費用の関係ですけれども、基本的に委託料の中に含めてお支払いするということが基本ですが、例外的といいますか、その他の大規模修繕ですとか、ケース・バイ・ケースで取り扱うものについては、区と管理者が協議して対応することになろうかと思います。","id":"exchange-011"},{"speaker":"飯沼委員","kind":"質問","question":"その辺の委託費用の内容とか額の決定というのは、どういうふうにされるのか。そういった面で、業者との癒着防止というか、その辺の選定については何かあるのか尋ねました。","respondent":"蓼沼高齢事業課長","answer":"それについて区のほうで協議をして、検討して、適切な価格を設定するということになります。","id":"exchange-012"},{"speaker":"飯沼委員","kind":"意見","question":"第６１号議案の知的障害者生活ホーム条例ですけれども、例えば利用者の苦情の対応とか第三者評価とか、そういうものがあるのかどうか、その点をお聞かせてくださいとの意見を述べました。","respondent":"西島障害者福祉課長","answer":"それから、２点目の第三者評価ですけれども、現在まだグループホームにつきましては第三者評価を実施しておりません。高齢者福祉障害者サービス向上委員会を実施しておりますので、その中でサービス向上について取り組んでまいりたいと考えているところです。","id":"exchange-013"},{"speaker":"飯沼委員","kind":"質問","question":"最後ですが、第６４号議案の障害者住宅条例のところで、利用料金が７万７,０００円ということだったんですが、この辺の料金の改定はどのように行われるのか、現在の利用料金改定の仕組みを教えてほしいのと、指定管理者になった場合に、その辺が変わるのかどうかお知らせください。","respondent":"西島障害者福祉課長","answer":"利用料金ですが、設置した際に建築費等も勘案いたしまして、面積あるいは近隣の住宅の状況等を勘案しながら区のほうで定めているところです。この料金につきましては、指定管理者は徴収をしませんので、区のほうで決定をするということになると思います。","id":"exchange-014"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"指定管理者制度の概要の別紙１の件でお伺いしたいんですけれども、他区の状況になっていると思うんですけれども、それが一つ。それから協定の締結、一番最後には報告書の提出となっていますけれども、具体的な中身はそれぞれどんなものなのか教えていただけないか尋ねました。","respondent":"早津高齢福祉課長","answer":"先ほど申し上げましたように一括条例という選択をしているところと、そうでないところがあるだろうという認識ではおります。経費の収支状況ですとか、利用状況の実態を年度が終了した時点で報告をしてもらうと、今の段階ではそのように認識しております。","id":"exchange-015"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"報告書はどういうものを求めていくかとかということについては、規則という形の中で定められるのか、そこのところをお知らせいただきたい。それから、規則で定められたら、出されたそれぞれの協定や報告書、申請書は情報公開の対象になるのかどうか、そのことを説明を求めました。","respondent":"西島障害者福祉課長","answer":"実は心身障害者福祉会館が今年度から実施してございまして、事業を受託したところについて評価というものは当然必要になってまいります。","id":"exchange-016"},{"speaker":"鈴木（ひ）副委員長","kind":"意見","question":"どういうものについて区長と協定を結んでいくかとか、こういうものについてはきちんと規則で中身についても示されるような形になるのか、そこのところを説明を求めました。","respondent":"早津高齢福祉課長","answer":"規則で示すのかというお尋ねかと思いますけれども、協定書の中でそれはうたっていくということになります。委員が例に挙げられたことも、ここに書いてあるとおり申請書の場合は、事業計画書ですとか収支計画書等を出していただくというのは想定しているです。","id":"exchange-017"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"できるだけこの辺のところが区民に公開され、チェックできるような情報公開という形で、ぜひやってほしいと求めました。もう一つ、ここのところは今まで認識していなかったんですが、それが区民に情報提供されるという仕組みになっているのか尋ねました。","respondent":"早津高齢福祉課長、木下福祉高齢事業部長","answer":"それに基づいて、請求があった場合に判断をするということだと思います。それぞれの法人の中でどう規定されているのか、私がこの場で責任を持ってお答えするまでの知識を持っておりませんので、よろしくお願いします。こういう意味での私どものチェックをさせていただいているということも十分承知しておいていただいて、お願いしたいと思います。","id":"exchange-018"},{"speaker":"鈴木（ひ）副委員長","kind":"確認","question":"手続として情報公開や個人情報の保護がすごく重要になってくるのではないかと思ったので、今までの質問をさせていただいたんです。協定書、申請書については、区の情報公開条例に基づいて情報公開されると考えていいのかどうかだけ確認させてください。","respondent":"早津高齢福祉課長","answer":"提出された書類については、その書類についての請求があれば、区の条例に基づいて判断をするです。","id":"exchange-019"},{"speaker":"山路委員","kind":"質問・要望","question":"今までどおりの流れの中で、区民が事業者に対する苦情というのは、先ほどの部長の説明の中にあったチェックということで解決するのでしょうか。どういうふうに活かされていくのか、そこを聞かせていただきたいのですが。","respondent":"早津高齢福祉課長","answer":"運営法人として対応が基本になりますけれども、先ほども説明がありましたように、さまざまかと思います。その苦情の内容に沿って、運営事業者と区が連携を取りながら改善していくということになると思います。","id":"exchange-020"},{"speaker":"山路委員","kind":"質問","question":"改善をするということで、事業者の交代ということも考えられるのでしょうか。そういう中身で、区民の苦情が反映されるということでとらえていいのか尋ねました。","respondent":"早津高齢福祉課長","answer":"仮定の話ですけれども、苦情があまりにも多い、特定の法人に偏っているし、その法人の内容が法人としての力量不足ということを判定するとすれば、場合によっては、そのことを理由に交代ということもあり得ることだと考えます。","id":"exchange-021"},{"speaker":"須藤委員","kind":"質問・要望","question":"今までの管理運営を活かしてということは、当然申請をしてくればそこへ到達するだろうということはわかってくるだろうと思う。だけど、ここまで委員会に出してきて、候補者予定者とするべき自治法改正なのかどうかということを聞かせてほしいと求めました。","respondent":"早津高齢福祉課長","answer":"活字で予定者とまで書く、現行管理委託者ととどめたほうが、資料の活字になっている段階ではよろしかったかもわかりません。区としての方針として、現行の法人が新制度においても十分やれるという判断の中でのことですが、少し先んじすぎているかもわかりません。","id":"exchange-022"},{"speaker":"須藤委員","kind":"質問・要望","question":"それぞれの法人が切磋琢磨して、一つの方向だけでなくていい特徴を出していくことを、行政としても指定管理者制度の根本というのはどういうものだと。その辺のところを今後とも、これから出てくる状況がいろいろな場面であるので、十分な配慮をしてほしいと求めました。","respondent":"木下福祉高齢事業部長","answer":"その中で確かお二人の方に対しまして、社会福祉法人系の部分については現行の法人を予定しているという旨をお答えをさせていただいたかと思います。","id":"exchange-023"},{"speaker":"須藤委員","kind":"質問","question":"なおかつここまで書いてしまうのはいかがなものですかという質問をして、ただここまで議会の中でぽんと出されてしまって、議会として「はい。一応申請だけはしてもらいますよ、そんな意見がここの中で出てきているのは、ちょっといかがなものですかというお話しをさせていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"本多委員","kind":"質問・要望","question":"制度が変わるということで、指定管理者制度そのものについては、ご説明いただきまして理解いたします。１点だけ確認させていただきたいのは、その辺の枠を広く解釈ができるんですかという、そこだけを確認をしたいと思います。","respondent":"蓼沼高齢事業課長","answer":"区立の施設ということもありますので、やはり区のほうが指定管理者と十分協議をして進めていくということが基本になろうかと思います。これまでもそうした形で進めてきておりますので、十分受託者側と区と協議をして今後も進めていきたいと、現時点では考えております。","id":"exchange-025"},{"speaker":"飯沼委員","kind":"意見","question":"指定管理者だけでなくて食事のところが含まれているので、第５８号議案については保留させていただいて、指定管理者の中身自体については賛成です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-026"},{"speaker":"須藤委員","kind":"質問・要望","question":"各条例とも了としていきますけれども、やはり趣旨をよく考えて、そして区民にしっかりしたサービスができるということをベースに、それぞれ今後とも指定管理者というか、業者を選定していただきたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"飯沼委員","kind":"意見","question":"利用料金のところですけれども、規則のところを広げたら、ショートステイとトワイライトステイの料金の表が載っているんですが、その他のかかる料金はどういうのがあって、その辺の記載がないのはなぜか、単純な疑問なのですが、との意見を述べました。","respondent":"辻田児童課長","answer":"育児支援ヘルパー派遣の中で、産後支援ヘルパーということで期間は１カ月、かなり福祉的性格が強いということ。そういうような理由から、この中から省いているということで、必要な部分につきましては規則等で対応していくです。","id":"exchange-028"},{"speaker":"飯沼委員","kind":"質問","question":"必要な部分は規則で記載していくということですが、現状は載っていないので、その辺は規定したほうがわかりやすいですよね。そういった面は規定がないとどこがどう変わるのかといったところのチェックができないと思うんですが、いかがか尋ねました。","respondent":"辻田児童課長","answer":"産後支援ヘルパーにつきましては、いろいろな要件につきましては今後も変わらなく同じような形で実施してまいります。区は積極的にそういうことを実施していくということで、そういう部分につきましては、利用料金がかかるものではございません。","id":"exchange-029"},{"speaker":"飯沼委員","kind":"質問・要望","question":"実際に施設に入っていらっしゃる方に伺うと、別途に医療費や生活費がかかるという部分で、これでは足りないとおっしゃっているんです。この辺でやっていけるのかどうか、またやっていけない場合はどうしたらいいのか、その辺を聞かせてほしいと求めました。","respondent":"早津高齢福祉課長","answer":"なお、これは特養に入っている方の制度上の事柄ですが、入所から１年経ちますと、その方単独でそこが住所地になります。特養に入った方はそこが住所地で、ご家族の方が別に住んでいらっしゃる方とか、そういった方も大勢いらっしゃるのではないかと考えているところです。","id":"exchange-030"},{"speaker":"飯沼委員","kind":"質問","question":"実際的には、どういう状況が生まれるかといったあたりは、把握はできているのか尋ねました。","respondent":"早津高齢福祉課長","answer":"どういった事態が生まれるかというのは、まさにこの制度がスタートしていく中で出てくる事柄かと考えます。先ほども申し上げましたように、これらの方については減額措置が取られておりまして、その減免制度を活用するようにという通知を発送したところです。","id":"exchange-031"},{"speaker":"飯沼委員","kind":"質問","question":"介護報酬についてお伺いしたいのですけれども、介護報酬がどれぐらい下がるのか教えてほしいのですけれども。現場は今後どういうふうに補っていけるものなのか、その辺の区の見方も説明を求めました。","respondent":"早津高齢福祉課長","answer":"１,３００万円とか１,４００万円というような、数字的にはそういうものが出てくるというものです。そういった状況の中で単純にそのまま赤字ということではなく、経営努力に努めていただきたいと考えているところです。","id":"exchange-032"},{"speaker":"飯沼委員","kind":"質問","question":"そういった面では、働く方々の労働条件がさらに悪くなっていくという危惧を持っているんですけれども、その辺で区ができることはないのでしょうか。他区で自治体の補助とかいろいろ考えられつつあると思うんですが、その辺もお伺いしたいと思います。","respondent":"早津高齢福祉課長","answer":"それから、これは運営者である法人が主体的に改善なり工夫する中で、新しい環境の中でやれるかということを総合的に検討していただくというものです。そういった形で、個々の法人の主体的、自主的な経営努力を期待したいと考えています。","id":"exchange-033"},{"speaker":"飯沼委員","kind":"質問","question":"法人の努力に期待をしたいということですが、社会福祉法人から今回の居住費と食費の内容の改定だと思うんですけれども、この内容についてご意見は届いているのか尋ねました。","respondent":"早津高齢福祉課長","answer":"区内の法人からということだと思いますが、制度全体のお話というふうに法人として受けとめているところです。","id":"exchange-034"},{"speaker":"飯沼委員","kind":"質問","question":"制度全体ということで、経営の運営について意見は届いているのか尋ねました。","respondent":"早津高齢福祉課長","answer":"法人の経営者の方とお話しをしている中で、実際に減になるわけですから厳しいだろうと。ただ、法人として頑張りましょうです。","id":"exchange-035"},{"speaker":"飯沼委員","kind":"意見","question":"その辺で段階ごとの違いというのは、どういうふうに示されるのか。これは施設ごとによって、ある程度自由に決められるのかどうか、その点を説明を求めました。","respondent":"早津高齢福祉課長","answer":"第４段階以上の方の食費、居住費については、施設ごとに定めることができることになっております。しかしながら、厚生労働大臣が告示によって定めた金額１,３８０円という食費、居住費については１日３２０円をもって負担額とするものです。","id":"exchange-036"},{"speaker":"須藤委員","kind":"意見","question":"この辺の根拠は国のほうで段階を整理せよという形で来られたのかどうか、その２点をお聞かせください。それから、在宅の方々とここに入っている方々は差異がなくなりますという考え方で見ていっていいのかどうか、その辺を説明を求めました。","respondent":"早津高齢福祉課長","answer":"８０万円の根拠ですが、国民年金の基礎部分をベースにして定めたものと考えられます。２万５,０００円アップになりますので、１０万円という差が少し縮小されて７万円プラスぐらいの差ということになるのではないかと思われます。","id":"exchange-037"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"特養ホームは介護保険になって、第２期目の介護報酬で４％減額されて、そのたびごとに経営が大変になるという状況があると思うんです。そして、さらに経営努力というところで言えば、具体的にどうなるのか、その辺のところを説明を求めました。","respondent":"早津高齢福祉課長","answer":"それと算定方法を同じにして、区立特養には東京都からございませんので、区立特養については同様の考え方で補助を行っているのが１点あります。法令上、３対１基準というのが特養ホームの基準ですけれども、おおむね２.５対１ぐらいの職員配置をしているという状況です。","id":"exchange-038"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"希望が持てる制度にぜひ変えてほしいという要望がずっと出されているわけですけれども、常勤職員がどうなっているかわからないですけれども。１０月から改定されて、区から国に対して働きかけというのはどうしても必要ではないかと思うんですけれども、その点に関してはいかがか尋ねました。","respondent":"早津高齢福祉課長","answer":"これは特養等の施設だけではなく、国民全体が合意できる内容というのはどの辺にあるかというところを審議するべく組織であると考えております。そちらでの議論を待ちたいと考えています。","id":"exchange-039"},{"speaker":"鈴木（ひ）副委員長","kind":"提案","question":"全国市長会でも国として２５％は持つべきだという提案も行っていますので、ぜひ言っていただきたいと要望しておきます。社会福祉法人の減免の内容はどういうもので、対象者はどういうところになるのか、このことについても説明を求めました。","respondent":"早津高齢福祉課長","answer":"その中に要介護２以上の方を基本的に入所対象として、要介護１以上では入所できないということは、まだ出ていないのではないかと思われます。","id":"exchange-040"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"社会福祉法人の４分の１減額ということですけれども、減額された分の負担割合について、社会福祉法人と国のところの割合を教えていただけますか尋ねました。","respondent":"早津高齢福祉課長","answer":"減額したものの割合ですが、これは大変説明が面倒になりますがご勘弁ください。残りの半分のうち半分、つまり４分の１は国、４分の１は自治体という構成です。","id":"exchange-041"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"ここで見ると、第４段階以上の入所者の居住費と食費は利用者と施設の契約によるということを書かれています。ほかのところは施設との契約で、これ以上の部分になる方もあるかと思うんですけれども、その辺のところは実際にどうなるのか説明を求めました。","respondent":"早津高齢福祉課長","answer":"これが第４段階以上の方に対して適用されていきます。委員お尋ねの他の施設はどうかですが、これ以上の額を第４段階以上の方に定めることは可能になりますので、可能であるということであります。","id":"exchange-042"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"当該現に介護福祉施設サービス等に要した費用の額とする」となっています。括弧の中だと、それにかかった額にできるのかなという感じにも読めると思うんですけれども、そこのところを説明を求めました。","respondent":"早津高齢福祉課長","answer":"１,３８０円という額が、現に食事提供に要した額が１,０００円だったとすれば１,０００円ですということです。１,５００円かかったとしても１,３８０円ですよと、こういうのが条文ですから、比較は逆になります。","id":"exchange-043"},{"speaker":"飯沼委員","kind":"意見","question":"特に、デイサービスの食費減免は全くないといった点では、高くて給食を断らざるを得ないような状況も起きるのではないかという心配がされます。特に、高い保険料、そして利用料の負担の上に、さらなる負担増ということで、認められないということで反対をいたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-044"},{"speaker":"須藤委員","kind":"意見","question":"賛成します。そういうものを少しずつ行政としても考えられるところが出てくるのではないかということで、この件につきましては賛成いたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-045"},{"speaker":"川西委員","kind":"質問・要望","question":"私はまだ残念ながら１回も見学したことがないんですが、運営の中心的な人はＮＰＯ法人なのか区の派遣職員なのか教えてほしいと求めました。それを説明を求めました。","respondent":"福島福祉高齢事業部副参事、辻田児童課長","answer":"私のほうからほっとサロンについて、ご説明します。ただ、支援等は行っております。ただ、それから乳幼児の健診未実施の家庭などを対象に虐待保護を行うわけですけれども、積極的に対応していくという状況がこれから増えてまいります。","id":"exchange-046"},{"speaker":"飯沼委員","kind":"質問・要望","question":"そういった面で、特に2)の虐待防止支援訪問事業というところで、実態を少しお聞かせいただきたい。他のところの連携とかいろいろあると思うんですが、具体的にどの程度係わりを持っているのかというあたりを聞かせていただきたい。","respondent":"辻田児童課長","answer":"１月の中頃に話があって、決断したのが１月の終りという形で、早急に対応を取る。というのは、平成１７年４月１日から、要保護児童、虐待も含めた要保護児童の対応が大きく変わってまいりました。","id":"exchange-047"},{"speaker":"飯沼委員","kind":"質問・要望","question":"繰入金などを合計すると２億６１３万円の減になっているんですが、それぞれの介護報酬の減額分ということで受けとめていいのかどうか、まず基本的なところでそこを教えていただきたい。","respondent":"早津高齢福祉課長","answer":"区からの繰入金については、それも含んでおりますが、前年度決算との調整もしておりますので、それだけではなくということになります。都の支出金と同じ割合ですので、１２.５％ずつということで、これがめどになるかと思います。","id":"exchange-048"},{"speaker":"飯沼委員","kind":"質問","question":"その部分で続いてですけれども、今、区のところは都と大体同じというところでは、特養ホーム、老健施設、ショートステイ、デイサービスなど、それぞれのところでの減額部分というのは、およそ出ているのか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-049"},{"speaker":"飯沼委員","kind":"質問","question":"歳入のところの減の影響が、各施設にどの程度響いてくるかなというところをお伺いしたかったんです。","respondent":"早津高齢福祉課長","answer":"説明の繰り返しになるのは恐縮ですが、３８ページの居宅介護サービス等諸費のところは、ショートステイとデイサービスの合計になります。食費では１日５００円ぐらいの減になるということが、施設当たりというお尋ねであれば、ある程度の目安になろうかと思います。","id":"exchange-050"},{"speaker":"飯沼委員","kind":"質問","question":"その辺は各施設ごとにモデルケースみたいなもので説明されているのでしょうか。ショートステイを利用している方々が、実際に自分がどう変化するのかわかるような状況になっているのかどうか、その点を知りたいのですが。","respondent":"早津高齢福祉課長","answer":"一人ひとりが、まず制度全体の説明については８月ぐらいに行っておりまして、なお減額制度がありますというところにとどめてあります。先ほども第１段階の人は何人ということを申し上げましたが、対象者ごとに「あなたの場合はどうなります」という説明もその段階でしているです。","id":"exchange-051"},{"speaker":"飯沼委員","kind":"質問","question":"その辺が利用者の皆さんに、あなたは幾らから幾らになりますよという具体的に見えない状況だということを伺ったので、そこが一番大事だと思うんです。モデルケースとか基本的なところはわかっても、あなたがどうなるのかという説明までいかないと思うんですが、その辺はどうなのか尋ねました。","respondent":"早津高齢福祉課長","answer":"それ以前も全体の説明をして、減額制度もあります。現実に問い合わせのあった方は何件かいらっしゃいまして、その方については所得を判定してご説明をしているです。","id":"exchange-052"},{"speaker":"飯沼委員","kind":"質問","question":"これから利用したいと思うような方も含めて、全体的な説明会とか、その辺のお考えがあるのかどうか。ぜひやってほしいんですけれども、その辺はいかがか尋ねました。","respondent":"早津高齢福祉課長","answer":"介護保険制度が新たに制定されたときとは、やはり様相も随分変わっていると思います。今回の改正は、とは言いながらも例えば民生委員協議会での説明ですとか、そういった形の中でも触れたりということで行っていく予定です。","id":"exchange-053"},{"speaker":"飯沼委員","kind":"質問・要望","question":"説明会のところは、なるべく広く区民に知らせる手立てをしていただきたいというのが要望です。ぜひ区独自の食事、特にデイサービスのところ区独自補助で対策をしていただきたいと思うんですが、いかがか尋ねました。","respondent":"早津高齢福祉課長","answer":"さらに激変緩和ということで、６カ月間について５５０円に減額的な措置をしているです。要支援の方で週１回、法制度全体の改正の中で区としも一定の措置を行い、ご負担をお願いしたいと考えているところです。","id":"exchange-054"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"それを７で割って４４４人となったんですけれども、そうするとおよそ４,６００人ぐらいが影響を受けることになると考えていいのでしょうか、このことを一つ説明を求めました。","respondent":"早津高齢福祉課長","answer":"第２段階の方は３,０００円ほど減になりますので、第３段階、第４段階の方は影響を受けるということになります。ですから、施設の人数の中から第１段階、第２段階を引いた人の数と考えたほうがよろしいかと思います。","id":"exchange-055"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"このことについてはぜひ区としても説明会をご検討いただけたらと、これは要望しておきたいと思います。それから、これは平成１６年度での決算をした結果、平成１６年度までの基金の積立合計額が幾らになったのか説明を求めました。","respondent":"早津高齢福祉課長","answer":"先に基金の積立金の内訳といいますか、どういうことでなったのかということをご説明したいと思います。基金の残が幾らかということですが、確か１８億５,０００万円に３,８００万円を足して１８億８,０００万円ぐらいではないかと記憶しております。","id":"exchange-056"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"よくわからないのですけれども、基金積立金が定期預金だとすると、平成１５年度の残が普通預金のところからという、普通預金というのはどこのことを言われているのか尋ねました。","respondent":"早津高齢福祉課長","answer":"繰越金の中には、前年分ですから保険料の余ったお金もあるわけです。その余った保険料のお金をまず先に使ったということです。","id":"exchange-057"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/948006?Template=document&Id=3122#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2005-01-01&TermEnd=2005-12-31"}],"sourceMeta":{"pages":0,"characters":53566,"voices":193}},{"id":"h17-20050926-8","meetingId":"h17-cm09","date":"2005年9月26日","dateIso":"2005-09-26","committee":"建設委員会","time":"午前１０時０５分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を72件整理しています。","topics":[{"id":"topic-01","title":"平成１７年請願第５号 投資用ワンルームマンション建設計画地の公園化に関する請願","agenda":"平成１７年請願第５号 投資用ワンルームマンション建設計画地の公園化に関する請願","exchanges":[{"speaker":"井上委員","kind":"質問・要望","question":"少しお伺いしておきたいことがあるので、その辺について伺いたいんですが、その辺のことをお伺いしたいということと今回。どういう問題点が考えられるのかという、そういったところを品川区はどう考えるのかということまで、とりあえず３つ伺いたいと思います。","respondent":"松代管理工事課長","answer":"伝承や学問的な発掘・調査研究等で、その場所が遺跡であることが地域社会においてよく知られている土地を言うと説明書きがございました。突き当たりの私道のところから建築計画の説明では地上８階、そこからは５階ということで、一応３階ほどの高低差があろうかと思います。","id":"exchange-001"},{"speaker":"井上委員","kind":"確認","question":"上の方では５階建ての安全の確認がされてから、安全確認がされるでしょうということなんですが、その安全の確認というのはどなたがどういうふうにされるんか尋ねました。","respondent":"松代管理工事課長","answer":"この試掘調査において埋蔵文化財の存在が確定されますと、引き続き本調査を実施するというような手続になってあります。建築申請が出されれば、構造的な部分も含めて、建築課の方で内容的に審査をしていくことになろうかと思います。","id":"exchange-002"},{"speaker":"井上委員","kind":"確認","question":"教育委員会がここは保存するべき地域なのであるというようなことの権限は品川区にはあるのかどうかということと、今おっしゃった確認申請が出されたときに、今日見た感じでその安全性というものはどのような感触を持たれているんか尋ねました。","respondent":"片田建築課長、松代管理工事課長","answer":"その辺の原則論が１つ排除される場面がございまして、建築計画の中では、まだ建築確認としては民間の方あるいは区の方にいずれかに出していただく。ただ、現在のところにおいて、申請されてございませんでしたので… 先ほどご説明しましたように、本調査ということになりますと、東京都の調査委員会立ち会いのもとで発掘調査が行われます。","id":"exchange-003"},{"speaker":"林（和）委員","kind":"質問","question":"地元の説明会を２回ほどやられたんですけれども、地元の方々の意見をただ聞いているだけで、全然前に進まないような状況だと聞いております。技術的にあの道路でもって今の予定されている建築物が建設できるのかどうなのか、その点、どうか尋ねました。","respondent":"片田建築課長、浜脇住宅課長","answer":"ご案内のとおり、当該地につきましては、ご説明させていただきましたように、崖の下ですと、狭い４ｍ以上の公道が、それは事業ができると。建築できるかどうかについては、かなり見通しを立てて… それから建築主からの説明会は説明不足だということで、これは１回に数えませんということで、９月１８日に改めて第１回の説明会をやっています。","id":"exchange-004"},{"speaker":"林（和）委員","kind":"確認","question":"先ほどの建築課長の説明では、今の状況からすると、確認がおりても、そういうところの調整がつかない限りにおいては、なかなか建築するのは難しいのではないかという説明ですね。","respondent":"片田建築課長","answer":"なかなか工事を明確にすることは、そういうご理解を得ないと、難しいです。","id":"exchange-005"},{"speaker":"林（和）委員","kind":"意見","question":"そうなってくれば、やはり私道の持ち主との合意がなければ建築はできないというのが現実だと思うんですけれども、そうですよねとの意見を述べました。","respondent":"片田建築課長","answer":"私道といっても、工事で必要とされた部分につきましては、基本的に代表の方と合意していただくということが確かに前提としてはあります。ただ私道の中の埋設物というのは、そういうものもやはり私道の持ち主の方のご了解が前提ということは、一点言えるかなと思います。","id":"exchange-006"},{"speaker":"林（和）委員","kind":"質問","question":"あれで２トントラックで運べますかね。どうか尋ねました。","respondent":"松代管理工事課長","answer":"現況をちょっとご説明しますと、区道の部分は４.５９ｍあります。ちなみに、下の方の区道からの部分についてはぎりぎり入るのではないかということだそうです。","id":"exchange-007"},{"speaker":"林（和）委員","kind":"質問・要望","question":"現状は非常に建設が難しいような状況にあるわけですから、そういうことも考慮いたしまして、品川区でやっぱり考えていただきたいと思うわけです。できるだけ早く結論を出していただきたいというのが私の願いですけれども、しかしながら、そういうところは私は様子を見るです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"土井委員","kind":"質問・要望","question":"教えていただきたいのは、その概要的なものをわかる範囲で教えていただいて、お聞きしたいと思います。新たにいろいろな形で出てくるやもしれませんので、その意味ではもう少し見るといいますか、協議する中でお話をしていったらと思います。","respondent":"片田建築課長","answer":"崖地とか丘陵地とか、そういう検討しているところがありますけれども、品川区については確かに御殿山あるいは島津山といった山があります。先ほどもご説明をしたように、崖が安全になるといったような一方の効果も出てきますので、今後の課題があるということで認識しています。","id":"exchange-009"},{"speaker":"菊地委員","kind":"質問","question":"法的にその辺はどうなのかというのをお聞きしたいのと、この場合、５階建ての地下３階という形ですね。それともう一つ、８５戸の住宅に対して車庫の設置義務というのはどうなっているのかなと思って、その辺も教えていただけますか。","respondent":"片田建築課長、浜脇住宅課長","answer":"したがいまして、いろいろな車線の整備とかということを考えた場合には、かなり崖上だとかなり難しいのかなということを考えております。恐縮ですのは、すべての問題内容を見ているというわけではございませんので… 私の方に、事前協議ということで相談に来ているんですけれども、事業者に対して、ワンルームマンションの場合には２棟につき１台となっています。","id":"exchange-010"},{"speaker":"菊地委員","kind":"確認","question":"確かにこれはいつも建物についてのみ確認をおろすんだということはよく言われるんですけれども、確認は確認としておりるのか知らないですけれども。崖下は二項道路という形になっているみたいですし、いずれにしても３０台以上の車両があの狭い道路を出入りをしていくというのはどうなのか。","respondent":"浜脇住宅課長","answer":"失礼しました。自動車の方は予定では11台なくてはいけないんですが、９台が隔地ですので、上の方から２台出入りをするというようなことになっています。","id":"exchange-011"},{"speaker":"菊地委員","kind":"質問","question":"ということは、９台はなしということになるんですか。ですから、これはやっぱりかなりしっかりした私道というのは必要ではないかなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"堺委員","kind":"確認","question":"１つは、現時点で明確なのは建築確認申請がまだ出されていないです。建築確認が出されて受理されたとしても、課長の立場から結論を出すのは難しいのではないかというコメントもございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"井上委員","kind":"意見","question":"私は採択というところで、今日、結果を出せればと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-014"},{"speaker":"林（和）委員","kind":"意見","question":"本来ならば、私は採択してというような意見です。そのようなことも含め、本件はこれで終わらせていただきますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-015"}]},{"id":"topic-02","title":"平成１７年陳情第５号 教育施設周辺における環境配慮に関する陳情","agenda":"平成１７年陳情第５号 教育施設周辺における環境配慮に関する陳情","exchanges":[{"speaker":"井上委員","kind":"質問","question":"説明会を何回かされている中で、テーマとしては反対だということなんですが、なかなか業者と住民の間の接点というか、改善される事項のようなものはなかったのか、今のご説明ですと、ただただ平行線の状態で回数を重ねたように聞こえたんですが、その辺はいかがか尋ねました。","respondent":"浜脇住宅課長","answer":"アスベストがあったのではないかということについて事業主で説明して、話し合いはしていますけれども、何か一致したとは聞いていません。","id":"exchange-016"},{"speaker":"菊地委員","kind":"質問","question":"今の２つの説明だと、陳情項目の１番目は話として進んでいますよという話ですが、この辺はまだクリアできていない部分ということなんでしょうか。そこがよくわからないのですけれども。","respondent":"浜脇住宅課長","answer":"７月１９日に第１回説明会をやって以来、なれてなかなか説明の理解ができないというか、あるいは説明が不十分というんでしょうか。","id":"exchange-017"},{"speaker":"菊地委員","kind":"質問","question":"過程の説明とこの中身とで、どうも一致しないものですから、通常の項目とね。業者さんの方が住民の皆さんの聞く耳を持ちませんよという形になっているのか、それともまた別の理由があるのか、そこだけ。","respondent":"浜脇住宅課長","answer":"数としてはここで言ったように３回やって、何とかいい対応をしてもらおうと思って、やっているとは思うんですね。８階のことか、それから建築主の話、どちらかというと施工・設計者が説明会をやっていますから。","id":"exchange-018"},{"speaker":"林（和）委員","kind":"意見","question":"これは全くそのとおりでございまして、当然、これはやってもらわなきゃいけない問題だと思います。１回だけ、結論を出しますということを言っていますので、今日のところはひとつ継続でとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-019"},{"speaker":"土井委員","kind":"確認","question":"もう一度、再確認だけします。後々よろしいのではないかと思いますので、しばらく今後、その意味で継続してください。","respondent":"浜脇住宅課長","answer":"改めてこの４項目について、どういう形でどういう方がご承知になっているのか、ちょっと私どもは承知していないんです。改めてこの４項目については、こういう動きについてしっかりやるようにということを申し伝えて、報告を求めるということです。","id":"exchange-020"},{"speaker":"土井委員","kind":"質問","question":"今の話は要するに何か話があったよというふうには聞いているという程度の話ですね。みんな満足しないわけでしょうから、そこら辺も含めて、とりあえずは話し合いでやってもらうしかないと思います。","respondent":"浜脇住宅課長","answer":"ちょっと時期的な問題もありますけれども、改めて要綱等もありますので、もし説明されて、どういう説明があって、どんな形にしたかというのは、改めて、私の方では把握したいと思います。","id":"exchange-021"},{"speaker":"堺委員","kind":"質問・要望","question":"区側に可能ならということで要望しておきたいのは、８ページにありますように、これはもう少し改善をされてくださいという趣旨かなと思えるんですね。どうしてもこういう要望をせざるを得ないのは当然だろうと思いますので、業者さんにもそういうことを伝えて、いい形で改善されるようにしてください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"}]},{"id":"topic-03","title":"審査の順番につきましては、午前中に申し上げましたとおり、(2) の第６６号議案を最後にいたしまして…","agenda":"審査の順番につきましては、午前中に申し上げましたとおり、(2) の第６６号議案を最後にいたしまして…","exchanges":[{"speaker":"菊地委員","kind":"質問","question":"旗ですけれども、店があくと同時に、ガードレールに縛りつけることがあったり、それから街路樹のところに旗を立てることがあったり、あるいは自分の店の軒先に出したり、いろいろあるんですけれども、あれを一本一本、調査していくということなんか尋ねました。","respondent":"松代管理工事課長","answer":"そういった対応等については今、その辺を見ながら、区もそれに準じて対応をまた考えていきたいと思っているところです。","id":"exchange-023"},{"speaker":"菊地委員","kind":"質問","question":"撤去というのは、さっき出ましたガードレールに縛りつけておくとか何とかというところでの話か尋ねました。","respondent":"岩田まちづくり事業部次長","answer":"この場合、それはその家に対して、すぐどかしなさいという命令ができることになっております。そうではなくて、軒並み放置して逃げちゃった者については、見つけ次第、撤去を現在もしております。","id":"exchange-024"},{"speaker":"井上委員","kind":"質問","question":"条例に広告旗がついたということは、届け出規定があるということであれば、今度つきましたから、届け出をしてくださいねという、届け出をされれば、年間だと思うんですけれども、４５０円でいいということで、そういう届け出がなかったら、強制撤去できるようになりますということか尋ねました。","respondent":"岩田まちづくり事業部次長","answer":"商業地域なんかはほとんど規制がないわけですけれども、住宅系の地域については、かなり厳しい色指定の規定があります。一般の袖看板や、自宅に張りつけている看板もすべてそういった取り扱いになっております。","id":"exchange-025"},{"speaker":"井上委員","kind":"質問","question":"立看板４５０円で、広告幕およびアドバルーンと書いてあるように、今までこういうのは届ける規定が自宅のところにやるときはあったと。広告旗と言わないかもしれないんですが、あの取り扱いは現在、どうなっているんか尋ねました。","respondent":"山口交通安全担当課長","answer":"区の対応はどうすればいいかということで、なかなかできませんので、詰めているところです。そういう法的にも万全な体制で行かないと、取り締まりの公平性を欠くと思いますので、これからもそういう対応を順次詰めていきたいと思っています。","id":"exchange-026"}]},{"id":"topic-04","title":"第６７号議案 品川区営住宅条例の一部を改正する条例","agenda":"第６７号議案 品川区営住宅条例の一部を改正する条例","exchanges":[{"speaker":"土井委員","kind":"提案","question":"それともう一つ、いや指定管理者制度に移しましょうというのが、今議会には両方提案される。指定管理者にいたしますよという部分が出てくるはずだと思うんだけれども、それとの兼ね合いも含めた計画、日程等、考え方はどうなっているんか尋ねました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-027"},{"speaker":"土井委員","kind":"質問","question":"私はこれについて聞いているんですから、この住宅の条例、どういう基準とどういう理由によって決められたのかということを聞いているんです。そしてまた、それは指定管理者を指定する必要があるので、それのかかわりはどうなっていますかということを聞いています。","respondent":"浜脇住宅課長","answer":"公の施設については直営でやるか、あるいは指定管理者制度になるか、どちらかを選ぶというふうに伺っています。区営住宅と区民住宅に対して、指定管理者制度を導入して、あわせて一歩ずつやっていくということになっております。","id":"exchange-028"},{"speaker":"土井委員","kind":"質問","question":"これは３年間の猶予が一応あるわけですから、その間のさまざまな行程、過程等も議論されているのではなかろうかと思う。この指定管理者をどうするかという問題が必ずそこの次に来る問題ですから、それに対するスケジュールは今、どうなっているんか尋ねました。","respondent":"浜脇住宅課長","answer":"改正後には、指定管理者の予定となる団体からの申請の提出を速やかにします。それで終わったところで協定を結んで、締結をして、指定管理者による管理は来年の４月開始を目途に行うというふうに予定を考えています。","id":"exchange-029"},{"speaker":"土井委員","kind":"質問","question":"流れはわかったとして、予定者からの申請というところが引っかかるんですけれども、予定者はだれなんですかということがありますね。手続をしているとなれば、出てくるような仕組みになっているかどうかがポイントなんですけれども、それはどうなっているんか尋ねました。","respondent":"浜脇住宅課長","answer":"本来ならば一般的にプロポーザル的なものを基本とする予定ですけれども、区民住宅は大くくりで３つのグループに分けて、実は委託をしています。","id":"exchange-030"},{"speaker":"土井委員","kind":"質問","question":"ということは今の時点では、今お願いをしている委託の業者さん、３つのグループの皆さんに、とりあえず引き続きやっていただきますよと。５年後なり、場合によってはこういう中身ですから、変えないとかいう形の議論をしますよという予定になっているということか尋ねました。","respondent":"浜脇住宅課長","answer":"３グループの３企業に対して、それをまず１回目にして、そのまま１年やってもらうと。それが５年過ぎたら、改めてこの３グループに対して公募といいますか、業者を決めるというふうになります。","id":"exchange-031"},{"speaker":"土井委員","kind":"質問・要望","question":"ということは、とりあえず選定委員会はどなたがおやりになるんですか。少なくともその形で、どうなるのかということを出していただきたいのが１つありますし、選定委員の関係はどうなるのか。","respondent":"浜脇住宅課長","answer":"その選定委員会なんですが、まちづくり事業部内に指名選定委員会をつくる予定です。今、まちづくり事業部内に指定管理者候補者を選定する委員会を設置すると考えています。","id":"exchange-032"},{"speaker":"土井委員","kind":"質問","question":"５人なんですか。全部なんですかということだから、そこら辺もちょっとやっておいていただかないと、だれに聞いていいかわからない。","respondent":"浜脇住宅課長","answer":"今考えておりますのは、委員長につきましては、まちづくり事業部長をもってやっていくというふうになってあります。委員につきましては、課長数名です。","id":"exchange-033"},{"speaker":"土井委員","kind":"質問・要望","question":"よろしいですか。今のところは一たん、とりあえず了解までいかないかもしれないけれども、次回のテーマにさせてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"菊地委員","kind":"質問・要望","question":"ですから、これまでの業務委託料というのでしょうか、そこも教えていただきたい。ただ指定管理者を定めるよという条例ですから、これ以外にこれから指定業者というのがまた別に出てくるわけですから。","respondent":"浜脇住宅課長","answer":"連携が図られるというふうに考えられますし、お互いの連携が図れるようにも改めて、サービスができるように図っていくというのが今の考えです。情報公開条例によって、これらについては、当然、行政情報ですので、できると思われます。","id":"exchange-035"},{"speaker":"菊地委員","kind":"質問","question":"私はそこは押さえていくべき部分だろうなと思っています。その辺の指定管理者になった状況と、これまでの業務委託との状況の違いというのは何か尋ねました。","respondent":"浜脇住宅課長、福田まちづくり事業部長","answer":"変更があるといいますか、もちろん連携もそうなんですけれども、自主的にやってもらっている部分がいっぱいあります。違いがこんなにあるというよりは、さらに我々とすれば、住民に対するサービスが行き届くのではないかという眼目です。 その中に反映させていきたいということを今、検討をしております。そういう空き家も何とか解消するような方向で、そういう利用料金制にかわるシステムについて、勉強させていただきたいと考えているところです。","id":"exchange-036"},{"speaker":"菊地委員","kind":"質問","question":"利益をどういうふうに上げていくかという、そこの追求をせざるを得ないわけですから、何らかの形でそこに住まわれている皆さんに負担を押しつけるか。これは別にＮＰＯだとか何とかだったら、また別なのかもしれませんけれども。","respondent":"浜脇住宅課長","answer":"今ありました区営住宅の滞納者への対応ですが、こういった督促や催促なり、また滞納者の相談なりは行うということであります。そういう方たちに対する新たな住宅の紹介であるとか、そういったものについてはご協力いただきたいということで、区の仕事として残る方向です。","id":"exchange-037"},{"speaker":"井上委員","kind":"質問","question":"私たちにはどういう議論がされて、どういうふうにこういう形になっていくのかということは、質問します。既に決まっている団体に対して、きっちりとここで公募も含めて考えるべきだと思ったんですけれども、公募という考えは１つもなかったんか尋ねました。","respondent":"浜脇住宅課長","answer":"来年度につきましては１年間継続という形に多分なりますけれども、当然、５年後に改めて公募による選考とするということでなってあります。","id":"exchange-038"},{"speaker":"井上委員","kind":"質問","question":"先ほどおっしゃいましたプロポーザルをして５年間、契約は基本的には５年間とか、方針としてはそういう契約を結ぶと思うんです。その施設だけに限って５年過ぎたところで、同じ業者という話だと、今までの方たちではないということがどこかにきちっと明記されるんか尋ねました。","respondent":"岩田まちづくり事業部次長","answer":"選定委員会の中でよく説明を聞いて、これでは委託と変わらないというような低い提案の内容であれば、そこの業者を選ばない可能性も残っていると。ですから、必ずしもその今ある業者が１００％、随意契約の形でその第４回定例会にご提案をするということではありません。","id":"exchange-039"},{"speaker":"井上委員","kind":"質問","question":"指定管理者制度は一般原則、公募であるという認識なのか、部長に伺いたいんですが。","respondent":"福田まちづくり事業部長","answer":"区としてというのではなくて、広くその可能性を求めるということが１つの方法論としては注目すべきものだろうとは考えております。私どもが当面選択をしたのは、先ほど次長が申し上げたような方法論を採用したということです。","id":"exchange-040"},{"speaker":"井上委員","kind":"質問・要望","question":"住宅ごとの登録ではなく、そういったところは区できちんと確認をしていくということがありましたけれども、確保できていけるのかということ。前年度が委託経費よりも赤字が出た場合には、区としてはどうされるのか尋ねました。","respondent":"福田まちづくり事業部長","answer":"したがいまして、実施主体が仮に変わったといたしましても、その規定に変更がない限りは変わるものではございません。そのマイナス、負のものにつきましても、次期の委託料の中に反映させるべきものであると考えております。","id":"exchange-041"},{"speaker":"井上委員","kind":"質問","question":"ぷりすくーる西五反田と心身障害者福祉会館などで伺ったときには、こういうところはどういうふうに考えて、今後盛り込まれていくのか尋ねました。","respondent":"浜脇住宅課長","answer":"施設は今、都市整備公社を通じてやっている３グループですけれども、これも今まで同様やっていただくことになってあります。","id":"exchange-042"},{"speaker":"井上委員","kind":"質問","question":"そこに行くと、大きな修繕はなかなかその経費ではできないとか、そういうことにはならないんですか。全然変わらないとおっしゃるけれども、本当は業務委託で経費に何億だかでやったときに、その経費はそこには使えないとかいう話にはならないんか尋ねました。","respondent":"浜脇住宅課長","answer":"これが今度どこかの区営団地で例えば雨漏りがしたら、雨漏りに幾らという修繕のことついてはプラスアルファして、委託の中に含めてやるというふうになっています。","id":"exchange-043"},{"speaker":"井上委員","kind":"質問","question":"指定管理者制度そのものがそういう委託ではないんじゃないですか。どういうふうに事業をしようかというものだと、私は理解しているんですけど、違うんか尋ねました。","respondent":"浜脇住宅課長","answer":"今回考えたのは、区がいただきますので、お金が向こうに全部行くという自由性というのはないんです。やはり検討して、そのまま予算をつけるという話をしておかないと、いい管理はできないのかなと考えております。","id":"exchange-044"},{"speaker":"菊地委員","kind":"質問","question":"最後に井上委員も言っていましたけれども、包括的なきちんとした条例をつくるべきだと思うんですね。株式会社そのものはやっぱり営利が上がれば上がるほどいいわけですから、この条例に関しては、反対をいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-045"}]},{"id":"topic-05","title":"の第６８号議案 品川区立区民住宅条例の一部を改正する条例","agenda":"の第６８号議案 品川区立区民住宅条例の一部を改正する条例","exchanges":[{"speaker":"井上委員","kind":"質問","question":"区民住宅の場合には、どのぐらいのコスト削減というような見通しが検討されて、なっているんでしょうか。で、この料金制度ではない部分で、コスト削減というところでは、どういう判断をされて、指定管理者になっているんか尋ねました。","respondent":"浜脇住宅課長","answer":"コスト削減もそう考えていますけれども、削減する方向で、委託をしていきたいということです。","id":"exchange-046"},{"speaker":"井上委員","kind":"質問","question":"仕組みとして伺いたいんですが、毎年毎年の契約になるのか、５年間は決定されているのか。その辺の契約の仕組み、協定書の中になるかと思うんですが、仕組みはどうか尋ねました。","respondent":"浜脇住宅課長","answer":"若干の想定所得も考えたり、そういったものも織り込んできますので、そういったものを盛り込んだ委託方法を考えています。これまでですと、最終的にこういった成果といいますか、あるいは削減になったらよいと考えています。","id":"exchange-047"},{"speaker":"井上委員","kind":"提案","question":"第４回定例会に事業者の選定が提案をされて、設置条例のところで、本当にこの業者が適切なんでしょうかという確認ができないかと思うんです。その辺の仕組みは今、品川区の方として提案をされる準備をしていると思いますけど、どこでどう議会や委員会は協議ができる仕組みになるんか尋ねました。","respondent":"浜脇住宅課長","answer":"この事業は指定管理者と予定される団体の応募を受けて、審査しながら、やっていく。議会に提出する資料としてどうなるか、また考えてございませんけれども、その辺の選定や決定の方法等も何かわかる方法で今は考えております。","id":"exchange-048"},{"speaker":"井上委員","kind":"提案","question":"最も適したと思われる事業者を区の方から議会に提案をされたときに、どういう内容で協定を結ぶとか、議論していく必要があるのではないかということを今後の課題として提案をしておきたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-049"},{"speaker":"堺委員","kind":"質問・要望","question":"事業部単位にそれぞれの戦略が練られているわけですから、各事業部単位に、この指定管理者制度の選定委員会が設けられるだろうなと。これについて、確認をしていきたいと思います。","respondent":"浜脇住宅課長、福田まちづくり事業部長","answer":"検討中ですが、一部連携する課がありますので、それにその他の委員長が必要と認める分についても入れるということを検討しているんです。というのは先ほど申し上げましたように、そういうようなこともありましたので… 端的にお答えいたしますが、選定の方法、それからその期限、それから結果および理由については公開ということが妥当だろうと思います。","id":"exchange-050"},{"speaker":"堺委員","kind":"質問・要望","question":"そして公平性が保たれているという選定委員会の位置づけは必要である。ぜひひとつ外部の有識者というのは、重ねて加えていただきたいと、これも要望として申し上げる次第です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-051"},{"speaker":"菊地委員","kind":"質問","question":"三井不動産ですか、あそこはプロポーザルをしたということですけれども、三井不動産なんていうのは本当に日本でも一流の大手ですよね。いずれにしても、あれだけの大きな不動産ですから、私はその辺はしっかりと開示すべきだと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-052"},{"speaker":"井上委員","kind":"質問・要望","question":"傍聴ももちろん当然可能ですし、本当にきっちりと透明な公平な選考がされているということでは、区民にとっても知るべきだと思います。公正で透明性のある選定を、そこは今後のいろいろな検討の中だとは思いますけれども、原則公開ということをもっと適用してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-053"},{"speaker":"土井委員","kind":"質問・要望","question":"さあ、これでどうだというふうにやれるように、ぜひ努力をしていただきたい。いいや、すばらしい案が提出をされるものと、期待をしております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-054"}]},{"id":"topic-06","title":"最後でございますが、(2) 第６６号議案 品川区地区計画の区域内における建築物の制限に関する条例の一部を改正する条例","agenda":"最後でございますが、(2) 第６６号議案 品川区地区計画の区域内における建築物の制限に関する条例の一部を改正する条例","exchanges":[{"speaker":"井上委員","kind":"質問・要望","question":"今後、学校の校庭に与える１年間の日照が子どもたちの学ぶ場として問題がないかどうかということを資料で確認させていただいた上で。いまだにこういう状況で私たちは確認をしないで条例案を審議したのかと言われることは、春秋図などと言うんですか、そこの状況がわかった上で。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-055"},{"speaker":"堺委員","kind":"提案","question":"委員長にちょっと確認をしたいんですが、ご提案のような、必要な資料を請求するということについては可能なんか尋ねました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-056"},{"speaker":"堺委員","kind":"質問","question":"可能だということで理解していいですか。委員会として特に諮ってどうこうというものではないように、私は思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-057"},{"speaker":"菊地委員","kind":"質問・要望","question":"区内では最高の高さを持つ建物がＡ１地区に建てられるということと、中塚議員の質問というのは、ぜひとも私も請求させていただきたいです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-058"},{"speaker":"土井委員","kind":"質問","question":"その質問の後でも十分申請をしていただければ、飛行機でとりにいくわけではありませんから、場合によっては何とかなったのかもしれないお話ですよね。どうしても出せない、それは出すべきものなのかどうかというお話になって、これはまた別な話だと思いますが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-059"},{"speaker":"井上委員","kind":"質問・要望","question":"答弁が出た４時間とか、こういうデータに基づいて、どういう審議を私たちは具体的にしましたと。委員会としてそのことはきっちりとしていただきたいということで、冬至ではなく、夏至の資料をぜひ出してもらいたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-060"},{"speaker":"井上委員","kind":"質問・要望","question":"再開発とかそういう部分には１階建てが建つとか、区民の方たちの説明を求めるたくさんの声があったんですが、その辺のことを説明を求めました。","respondent":"上野都市開発課長","answer":"周辺の住民の方々には十分さまざまなご意見をいただきましたものに対して、区なり事業者なりの対応をさせていただいてまいりました。引き続き事業者の方から継続して説明するように指導してまいっておりまして、事業者の方で個別に対応していますが、まだ変わってございません。","id":"exchange-061"},{"speaker":"菊地委員","kind":"質問","question":"説明をということですか。小中一貫校の方はどういう形になるのか、隣地境界からＡ１地区への距離は、小中一貫校からＡ１地区まで壁面地は１２ｍというふうに見ていいんか尋ねました。","respondent":"上野都市開発課長","answer":"今、お手元の資料には歩道状空地の幅が４ｍという形で、小学校側にこれを確保する形で書いてありますけれども、壁面の分につきましては、今、委員のご指摘のあった高層部につきまして、１２ｍ道路際から離すこととしています。","id":"exchange-062"},{"speaker":"菊地委員","kind":"質問・要望","question":"１２ｍということで、あまりこっちの一貫校の方はまだ動いていないので、ちょっとグラウンドのところになるんでしょうか。３時間、３時間という答えをしてくださいましたけれども、何時から何時までが日を落とすのかということを教えてほしいと求めました。","respondent":"片田建築課長","answer":"今回、東五反田二丁目第２地区については、１時間から２時間ほどの日照時間を落としているというご説明をさせていただいているところですけれども。","id":"exchange-063"},{"speaker":"菊地委員","kind":"質問","question":"大型工事が実際に始まっているわけですから、答弁では配慮していると言いますけれども、実質的にはやっぱりおかしな話ではないかなと思います。Ａ３地区の３１７号線に接続する道路ですけれども、改めてお聞きしたいんですけれども、ちょっとそこだけ考え方をお教えほしいと求めました。","respondent":"上野都市開発課長","answer":"それにつきまして、東五反田二丁目第２地区につきましては、こういう制限におさめたというものです。非常に支障が出てまいりますので、そういう面からここにつきまして指導をして、この区域の中に入れたという経緯があります。","id":"exchange-064"},{"speaker":"井上委員","kind":"質問・要望","question":"思い浮かべて、これだけ周りに高い建物がある学校はないというのを確認したいんですけれども、その辺をご存知であれば教えてください。情報として教えていただきたいということと、学校の教育に対する十分な配慮を行ったとおっしゃいましたけど、その３点をお願いします。","respondent":"上野都市開発課長","answer":"それから２点目のイマジカにつきましては、今のところ計画等、特に具体的な話は地元から聞いてございません。この設計計画を進めるに当たりましては、その認識につきましては前回、一般質問での教育委員会事務局教育次長のご答弁のとおりです。","id":"exchange-065"},{"speaker":"井上委員","kind":"質問","question":"まだここは建てていないわけですから、９年間をここで過ごす子どもたちにとって本当に適切かどうかといえば、その隣ですから。ここが１５３ｍも許可されているという地区整備計画になっているということは、区として、きちっとした考え方を示していくべきだろうと思います。","respondent":"上野都市開発課長","answer":"具体的な協議がありましたら、その内容を十分見ながら、適切に対応していきたいと考えています。その際に必要に応じて、教育委員会とも十分協議しながら、区としてのまとまった考えとして、調整を進めていきたいと考えています。","id":"exchange-066"},{"speaker":"菊地委員","kind":"意見","question":"今、あるいはどういった状況になるのかということをきっちりと事前に、区の責任で住民に説明していくべきだと思います。その問題のことと、教育施設への影響の問題のことにつきまして、反対をいたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-067"},{"speaker":"井上委員","kind":"意見","question":"私もいろいろなこの計画の審議の中で、住民の方たちに、事業者も含めて、区の方から納得する説明をしてほしいというお話を再三させていただきました。本当にここは１３年も前に計画が明らかになるというようなことで、悪影響を及ぼすような計画に対して、反対をしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-068"},{"speaker":"堺委員","kind":"質問","question":"協定書はまちづくり事業部内の選定委員会で指定管理者が案として出されて、議会の議決を経てしまった後に、事業部が指定管理者と結ぶ協定書を出してくださいと言っているんか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-069"},{"speaker":"井上委員","kind":"提案","question":"ここと契約するんですかということがわからないと、その協定書がどうでも、確定してから結ぶというものでもないはずだと思うんです。前回のぷりすくーる西五反田も、審査が議会に提案される前に協定書は協議としてはもう示されているわけですから、そのことを審議するためにはとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-070"},{"speaker":"堺委員","kind":"質問","question":"本会議にかけていかれるようにしなければいけない。選定委員会で検討してもらうわけですから、何が何でも全部議会に出すんだという、性格なものかどうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-071"},{"speaker":"菊地委員","kind":"提案","question":"これはいろいろな区によってどうしてもまだ案として出ないような区なんかもあるみたいですけれども、指定機関、いわゆる基本協定の案ですね。そういうことも含めて、これから具体的に業者を含めて議会に提案をされるというのであれば、それは必要な部分ではないかなと思いますとの意見を述べました。","respondent":"福田まちづくり事業部長、築舘委員長","answer":"今日１日、時間をいただいて、あすの委員会には考えをお示しさせていただきたいと思います。 では、そういうことで、明日の委員会で考えを示していただくことでよろしいですね。","id":"exchange-072"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/825107?Template=document&Id=3828#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2005-01-01&TermEnd=2005-12-31"}],"sourceMeta":{"pages":0,"characters":61980,"voices":177}},{"id":"h17-20050926-9","meetingId":"h17-cm09","date":"2005年9月26日","dateIso":"2005-09-26","committee":"文教委員会","time":"午後１０時０５分～午後２時５６分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を90件整理しています。","topics":[{"id":"topic-01","title":"第６９号議案、品川区立学校設置条例の一部を改正する条例","agenda":"第６９号議案、品川区立学校設置条例の一部を改正する条例","exchanges":[{"speaker":"沢田委員","kind":"質問・要望","question":"その後の検討は、どうなんでしょうか。そこは変わったのか、変わってないんか尋ねました。","respondent":"中島指導課長","answer":"小中一貫教育の内容で、小学校で指導する漢字の状況につきましては、以前に資料でお知らせしてあるとおりで、変わってございません。","id":"exchange-001"},{"speaker":"沢田委員","kind":"質問","question":"４年生で繰り返すから大丈夫なんだと言うけれども、総量が増えているわけですから、ほんとうに私は心配します。これ以上やると、中身の問題は今までやってきましたのでやりませんけれども、そのことだけ言っておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"南委員","kind":"質問","question":"学校は朝８時半ぐらいから始まるんですけれども、いわゆる学校の開校時間というんでしょうか、どの程度日が当たるのか。この間の質問では、そんな具体的な状況がちょっとわかりかねたので、改めてその部分を質問したいと思っているんですけれども、説明を求めました。","respondent":"市川庶務課長","answer":"日影の問題というのは、個々の計画に基づいて、例えば冬至のときに、こういうように動いていきますという計画の説明として示されてきます。","id":"exchange-003"},{"speaker":"南委員","kind":"質問","question":"朝８時半から、夕方子どもたちが下校するのが４時か４時半ぐらいだと思うんですけれども、それをちょっと伺いたいんです。予測の問題ですからあれなんですけれども、ちょっとその辺も、もしあるとしたら説明を求めました。","respondent":"市川庶務課長","answer":"繰り返しの説明になりますが、今の時点では、詳しい説明を受けていないということが一つあります。その他については、先ほど答弁したとおり、計画の複合については、今のところ、確たる説明がないです。","id":"exchange-004"},{"speaker":"南委員","kind":"質問","question":"必ずしも間に合わないという状況ではないわけですから、それについては、積極的に教育委員会として表明していくべきではないかと思っているんです。それについてはどうか尋ねました。","respondent":"古川教育次長","answer":"先だっての一般質問の中でお答えしたとおりでございまして、教育委員会がこの問題についてどう考えているかということの基本は同じです。この計画を実施してきましたので、それも含めた教育環境はすばらしいものがあると、このように考えております。","id":"exchange-005"},{"speaker":"南委員","kind":"意見","question":"そこの時点で、まず選択が省かれてしまうような気がしてなりません。したがって、非常に残念な思いをするところですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-006"},{"speaker":"西本委員","kind":"確認","question":"一つ確認なんですが、日野学園という愛称が決められたと思うんですが、それはこの規定の中に、何か入れることがあるのか尋ねました。","respondent":"古里学務課長","answer":"学校教育法上はそのまま残ってありますので、この設置条例の中に、日野学園という名称を提示するつもりはございません。あくまでも愛称ですので、そのようにご理解いただければと思います。","id":"exchange-007"},{"speaker":"西本委員","kind":"意見","question":"第二日野小学校、日野中学校の名前との関連とはどうなっていくのかなという思いで聞いたんですが、その辺はどういうふうに考えられていますかとの意見を述べました。","respondent":"市川庶務課長","answer":"果たして１年後なのか、あるいは３年後なのか、その辺もまだ見当がたってございません。大崎地区に設置いたします日野学園を、名称も含めて、改めて検討することになろうかと思います。","id":"exchange-008"},{"speaker":"沢田委員","kind":"意見","question":"品川区のプラン２１のシンボル的な存在だと言って建てて、１００億円近いお金を投入してやるというのは、私は疑いたくなりますね。これ以上言ってもあれですけれども、以上３点の理由で、この設置条例に、私は賛成するわけにはいかないということを述べておきたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-009"}]},{"id":"topic-02","title":"続きまして、(2) 第７０号議案、品川区立学校施設使用条例の一部を改正する条例","agenda":"続きまして、(2) 第７０号議案、品川区立学校施設使用条例の一部を改正する条例","exchanges":[{"speaker":"沢田委員","kind":"意見","question":"どういう条文というか、法文でそうなっているのか、そこのところを説明願いたいと思いますとの意見を述べました。","respondent":"富田生涯学習課長","answer":"平成１５年７月１７日、学校教育法等、指定管理者制度をとることができないものであること」という定めがあるものです。この学校の設置者というのは、地方公共団体ということになってまいります。","id":"exchange-010"},{"speaker":"沢田委員","kind":"意見","question":"今度は直営にするということなんですが、具体的には変化があるのか、ないのか。そこら辺を、ちょっと説明願えますかとの意見を述べました。","respondent":"富田生涯学習課長","answer":"お示ししました第１２条の中で、旧の地方自治法の解釈で実施したところですけれども、管理委託制度から直営を想定しているものです。実質的な運営の場面におきましては、現行のスポーツ協会が実施するということになれば、区民の皆様へのサービス面等々含めて、大きな変更はない。","id":"exchange-011"},{"speaker":"沢田委員","kind":"意見","question":"あまり変わりないというと、管理委託と業務委託とどう違うのかなと、そのぐらい疑問がわくんです。業務委託と、管理委託、今度、指定管理者制度の違いみたいなものとの意見を述べました。","respondent":"富田生涯学習課長","answer":"現在、利用料金制をとっておりまして、区は委託料の支払いをしていない形をとっております。事務的な面では、管理の部分をお任せすることで、安定した運営を図れているということがあろうかと思います。","id":"exchange-012"},{"speaker":"沢田委員","kind":"質問","question":"今まで利用料金制をとって、その利用料の上がりはスポーツ協会のほうに行っていたと。今度、直営になって業務委託になると、それは区に入って、今度は委託料と名前が変わって出ていくということの判断でよろしいんか尋ねました。","respondent":"富田生涯学習課長","answer":"委員おっしゃるとおりです。","id":"exchange-013"},{"speaker":"西本委員","kind":"質問","question":"業務委託になりますと、当然、行政側の管理が強化されるかもしれませんけれども、自由がなくなるということがあるとは思うんです。直営にすることによって、逆にそれを阻害してしまうのではないかなというような危惧もあるんですが、その辺はいかがなんか尋ねました。","respondent":"富田生涯学習課長","answer":"区民の皆さんの利用の部分を、日野中学校のプールでは果たしていくという部分も含めて実施をしていかなければならないと考えています。そういった部分での自由度という面では、経費の切り分け方等々の部分がありますけれども、大きな差異はないものというふうに考えてあります。","id":"exchange-014"},{"speaker":"西本委員","kind":"質問","question":"その点は、いかがでしょうか。現在も、考えが進んでいるかどうかわかりませんけれども、評価ということでは、いかがか尋ねました。","respondent":"富田生涯学習課長","answer":"そういった評価につきましては、事務事業評価というのも、区として実施しているところですし、直営の事業ということで、歳入、また委託料の支払い等々の場面もありますので、区民の皆さんからのお声も含めて、評価というものは、今後とも行っていくものと考えております。","id":"exchange-015"},{"speaker":"西本委員","kind":"質問","question":"事務事業評価というのは自己評価にすぎなくて、第３者評価というスタンスになっていない部分があるわけですね。いろいろと学校教育の中で第３者評価というのもありますので、ちょっと困るなと思ったんですが、その辺はいかがか尋ねました。","respondent":"富田生涯学習課長","answer":"直営の事業になるですが、温水プール、または学校施設の使用条例で行っております業務のみでの単独の評価ということは考えてないところですが、先ほども申し上げましたが、区の事務事業全体の評価を行っていく中で、この事業の評価というものは実施していくものと考えています。","id":"exchange-016"},{"speaker":"西本委員","kind":"質問・要望","question":"仕組み等々を考えていただきたい、環境面もつくっていただきたいという希望を持っておりますので、それをお願いをしたいと思います。もう一つ確認なんですが、第１２条の委任ということで、「委員会規則で定める」ということですが、これは公開できるものの一つなんか尋ねました。","respondent":"富田生涯学習課長","answer":"それは、教育委員会規則ですので、当然のことながら公開できます。","id":"exchange-017"},{"speaker":"南委員","kind":"質問","question":"簡単なんですけれども、業務委託に変わることに伴って、利用者とか区民への案内というのはするんですか、しなくていいと考えているんですか。周知徹底というんですか、変更の周知はされるのかなと、ちょっとご説明をお願いします。","respondent":"富田生涯学習課長","answer":"利用料が使用料になることもあり、区の歳入に入ってくるというところでは、お知らせをしていく必要があると考えています。お知らせのタイミングといたしまして、複合施設での温水プールのお知らせのタイミング等々、全体を勘案しながら考えてまいりたいと考えています。","id":"exchange-018"}]},{"id":"topic-03","title":"第７１号議案、品川区立体育館条例の一部を改正する条例","agenda":"第７１号議案、品川区立体育館条例の一部を改正する条例","exchanges":[{"speaker":"山村委員","kind":"質問・要望","question":"値段が若干変わるのはわかるんですが、戸越体育館のほうは、計算すると別に変わっていないということでよろしいんでしょうか。そこら辺を教えていただけるとありがたいんですが。","respondent":"富田生涯学習課長","answer":"ただいまご指摘の、まず１日の利用ですが、利用方法等は従前と同様に考えております。変更はございませんので、時間が短くなった分、料金的には安価になっているです。","id":"exchange-019"},{"speaker":"山村委員","kind":"質問・要望","question":"区民で夜間６時から９時半ぐらいまで借りたとして、今までだと、５時半から９時半まで４時間ぐらい借りていたわけですね。延長は４時半からやるのか、それとも１０時まで延長させちゃうのか、どちらなのか教えてほしいと求めました。","respondent":"富田生涯学習課長","answer":"夜間の延長の利用というのは、９時半までが基本的な区分ですので、この後の定めということになってまいります。延長に対しての考え方等々、教育委員会の考え方等々がありますので、延長の時間の期限等々の定めというものをしてまいりたいと考えています。","id":"exchange-020"},{"speaker":"山村委員","kind":"意見","question":"今までの５時半から９時半で４時間を、延長料金を含めて６時から１０時まで借りると、現行より高くなるということですね。たしか、現行より１,５００円ぐらい高くなるでしょとの意見を述べました。","respondent":"富田生涯学習課長","answer":"考え方といたしましては、４時間が３時間半にはなりますが、できるだけ効率的な利用をしていただきたいと考えているところです。９時半に限定することなく、９時３０分からの延長３０分の定めというものを設けたですので、お願いしたいと考えています。","id":"exchange-021"},{"speaker":"山村委員","kind":"質問","question":"戸越体育館は、ほとんどの利用条件によって、今回の改定で高くなるということはないんですね。それとも、利用の仕方によっては、今までより高くなるということはあるんか尋ねました。","respondent":"富田生涯学習課長","answer":"区分の中の時間の単価は同じですので、そこでは変わらない、時間分安くなるですが、例えば、２時間３０分では足りないと、３時間ということで３０分延長したいとなった場合には、延長料金の分が、若干割高になるということは出てまいるかと思います。","id":"exchange-022"},{"speaker":"山村委員","kind":"質問","question":"新しい条例で３０分間延長すると、３０分につき３０分相当額だけだから、単純な計算で９,３６０円で収まる。そうすると、今までは９,４００円だから、４０円安いということでいいか尋ねました。","respondent":"富田生涯学習課長","answer":"１日に２時間のインターバルがございましたけれども、４区分にするために、インターバルを３０分ずつにしています。２万９,３００円ですが、新条例で１日借りた場合には、３万５６０円程度になると考えております。","id":"exchange-023"},{"speaker":"山村委員","kind":"質問","question":"そうすると、戸越体育館は場合によっては高くなってしまうということでよろしいんか尋ねました。","respondent":"富田生涯学習課長、古川教育次長","answer":"基本的な計算、考え方については従前とおりの単価、延長料金の考え方でやっておりますが、利用区分になって伴って、利用のされ方によっては、そういう場合も出てくると考えております。 先ほど来ご説明しておりますように、夜間という３区分を４区分に分けた、その費用を検討したということなんです。２時間半、あるいは３時間半という中で、よろしくお願いしたいと思います。","id":"exchange-024"},{"speaker":"山村委員","kind":"質問・要望","question":"教育次長のおっしゃるとおりだとは思っておるんですけれども、何も変わっていない戸越体育館が、１日利用料金が、１,２６０円ほど高くなるということで、区民サービスの低下にならないように、いろいろと考えてやっていただきたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"南委員","kind":"質問・要望","question":"そもそも、体育館を指定管理者制度を利用して指定管理をしていくという、そこのところの区の思いを、まず教えていただきたい。この改正のところでは、情報公開が出ていなので、改めて伺いたいと思います。","respondent":"富田生涯学習課長","answer":"は、区民の皆さんにとってどのようなメリットがあるのか、これを打ち出していくことが大事だと考えております。２点目の情報公開の点につきましては、指定管理者として、区としての全体の基本的な考え方を持っておりますので、それと同様と考えているところです。","id":"exchange-026"},{"speaker":"南委員","kind":"確認","question":"もう１回確認なんですけれども、区としてはきちんとして対象として位置づけて、指導していくということでいいんか尋ねました。","respondent":"富田生涯学習課長","answer":"体育館のみならず、指定管理者となるところにつきましては、区全体の情報公開の判断と同様に、区全体で指定管理者となるところと同様に、体育館についても、情報公開については考えてまいります。","id":"exchange-027"},{"speaker":"南委員","kind":"質問・要望","question":"そういうことで、姿勢をはっきりと打ち出していただきたいと思っているんですけれども、それが条例に載っていないのが非常に不安なところなんです。教えていただきたいんですけれども、その辺が不勉強があって十分に確認できてなかったので、どういうふうになっているのか教えていただきたいんです。","respondent":"富田生涯学習課長","answer":"区全体の方針というものも受けとめて、企画部サイドのそういった部分のすり合わせを行いながら、判断をしてまいりたいと考えております。","id":"exchange-028"},{"speaker":"南委員","kind":"質問・要望","question":"条例のところで、それを確認したいと思っているので、そこを教えていただきたいんです。","respondent":"富田生涯学習課長","answer":"先ほどと繰り返しになりますけれども、指定管理者制度を導入するに当たっての条例改正の中では、ここの部分では、個人情報保護について、管理の基準の一つとして盛り込んでいくという区の方針を受けて、この条例をつくったものです。","id":"exchange-029"},{"speaker":"南委員","kind":"質問","question":"個人情報と情報公開とは、また別次元のものですから、情報公開という文言がきちんと体育館条例の中に盛り込まれてほしいと思ったんです。何かそういうところできちんと確保されていくのかと、ちょっと思っているので、ちょっとその辺の考え方について伺いたいんです。","respondent":"市川庶務課長","answer":"大もとのほうの問題として、当然、検討される問題だと考えています。条例立案ということについて言えば、なじまないという条項だと考えます。","id":"exchange-030"},{"speaker":"南委員","kind":"質問","question":"全部適用するというふうなことでくくられてしまっていいのかなという心配をすごくしますので、ちょっと改めて、この問題について伺ったんです。ご答弁をお願いします。","respondent":"古川教育次長","answer":"あるいは、新しく体育館ができることによっての一定のサービスの変更の部分、こういったことについての条例の改正です。今後とも、事業を実施していく中で、私どもも十分に大事にしていきたいと考えております。","id":"exchange-031"},{"speaker":"南委員","kind":"確認","question":"そうすると、指定管理者に選定していって、新たな管理委託をする業者に対して、情報公開を義務づけるとする姿勢があるのか、どうか。最後にそこだけ確認して、終わります。","respondent":"古川教育次長","answer":"区のみならずさまざまな団体でその趣旨が生かされるように、私どもは努力していく立場にあろうと、このように考えています。義務づけそのものについては、現実的な問題としては、今、この場でお答えする内容ではないだろうと考えています。","id":"exchange-032"},{"speaker":"南委員","kind":"質問・要望","question":"ですから、ぜひ義務づけるような方向で、姿勢を明確にしてほしいと求めました。今は、ちょっとそこまで答弁いただけないので、あえて申し上げておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"},{"speaker":"沢田委員","kind":"確認","question":"いわゆる第３セクター並の扱いなのか、ちゃんとしてほしいし、個人情報保護条例そのものを変えなきゃならないと思うんです。全体にまたがることで恐縮なんですけれども、その辺はどういう論議がなされているのか、ちょっとお尋ねしたいんです。","respondent":"富田生涯学習課長","answer":"指定管理者が実施機関の扱いになるのか、従来どおり第３セクターというような扱いになるのかというようなご質問でございましたけれども、そういったところと調整しながら検討してまいりたいと思っています。","id":"exchange-034"},{"speaker":"沢田委員","kind":"質問・要望","question":"ちょっと別件で質問したいんですが、選定委員会の審議を経てやるということとの兼ね合いでは、どうなっていくのか。ちょっとそこらの中身を説明を求めました。","respondent":"富田生涯学習課長","answer":"体育館条例の改正案第１３条にありますように、選定委員会でもって審査を行っていくという考え方です。","id":"exchange-035"},{"speaker":"沢田委員","kind":"質問","question":"それから、選定基準については公開するけれども、選定をする会議については傍聴させないと。私は、その会議の選定の過程こそ公開すべきだと思うんですが、そこら辺はいかがか尋ねました。","respondent":"富田生涯学習課長","answer":"選定委員会のメンバーにつきましては、今後、検討してまいりたいと考えています。従前、行財政改革特別委員会で資料として提出しているとおり、非公開という考え方でいくです。","id":"exchange-036"},{"speaker":"沢田委員","kind":"質問・要望","question":"私は、こここそ公開すべきだということで、ぜひ再考を願いたいと思います。あったら困っちゃうんですけれども。","respondent":"富田生涯学習課長","answer":"改正条例第５条にありますように、「利用料金および別表第２の範囲内において」ということですので、こちらに載せております別表を上限として、です。","id":"exchange-037"},{"speaker":"西本委員","kind":"意見","question":"それとも、区としての補助とか、そういうのはあるのか、どうか。運営自体はどういうふうな形で、指定管理者はしていくのかとの意見を述べました。","respondent":"富田生涯学習課長","answer":"利用料の収入が見込まれると、精算をするという形を、現在はとっております。大きな変更はないんですけれども、委託料ではなく、管理運営経費といったようなもので、その必要経費を支出していく形になってきます。","id":"exchange-038"},{"speaker":"西本委員","kind":"質問","question":"第１４条の指定管理者の行う業務の中での施設等の維持および修繕等もありますので、指定管理者制度というのは、どういう形が出てくるんですか。それとも、区の責任下において、ある程度の必要経費については補助していくというふうに考えていくのか。","respondent":"富田生涯学習課長","answer":"今、委員おっしゃった後段のほうに近いかと思います。新たに指定管理者の努力の部分を入れていくというような考え方ですので、委託料と変わらず支出をしていくということになってまいります。","id":"exchange-039"},{"speaker":"西本委員","kind":"意見","question":"１時間当たりの単価ということもあるでしょうし、今は管理委託でいろいろ委託をされていると思うんですが、そこまでの権限がないんですよね。どこまで、議会はチェックができるものなのかとの意見を述べました。","respondent":"富田生涯学習課長","answer":"事業の達成状況やコストの検証ですとか、サービス向上のための評価などを行っていくということを、区全体の方針として持っているところであります。１年、２年のそういった全体経費の収支等々といったものが必要になろうかと、思っているところであります。","id":"exchange-040"},{"speaker":"西本委員","kind":"質問","question":"どうかという雇用の問題になりますけれども、そこに区の関与ができるのか、できないのか。そこまでは立ち入れませんという話になってしまうと、非常に不安になりますので、その辺の区の考え方を説明を求めました。","respondent":"富田生涯学習課長","answer":"現在も管理委託しておりますので、そういった面については、大きな変化はないものと考えていますが、議会のチェックという点では、現在のすべての事業は同様ですけれども、議会での予算、決算なり審議していただく上で、同様に審議いただけるものと考えております。","id":"exchange-041"},{"speaker":"西本委員","kind":"質問・要望","question":"ですから、この制度を導入することの大きなメリットだと、私は思っているのは、どこまでチェックができるのかなんです。第２条の関係のところで、１回５００円とありますが、これはどういうわけで５００円となっているのか。","respondent":"富田生涯学習課長","answer":"ある程度フリーに使える時間帯の設定等々も行いたいと考えており、初心者教室、指定管理者からの提案を受けて定めていきたいと考えております。金額的にどうかといいますと、現在、あります金額を参考にしながら、内容等を含めて検討していきたいと考えているところです。","id":"exchange-042"},{"speaker":"西本委員","kind":"質問・要望","question":"５００円払って、分割された形で、何時からの利用では何とか教室という形で区切られちゃうわけですね。その辺は、委託者のほうときちんと話をして、自由なところも確保しつつしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-043"},{"speaker":"山村委員","kind":"質問・要望","question":"質問を聞いていて、三疑問に思っている部分を聞かせていただきたいんですが、１回５００円ということですよね。そこが借りて運営するようなものでしょうから、そういうことが可能なのか、どうかというのをひとつお聞きしたいと思うんです。","respondent":"富田生涯学習課長","answer":"妥当であるというようなことが考えられるのであれば、ないとは言えないと考えておりますが、難しい面が多いかなというのが実際のところです。","id":"exchange-044"},{"speaker":"山村委員","kind":"質問・要望","question":"今はチケットとかいろいろあるわけですから、やろうと思えば、どうにかできるかなということを言いたかったというのが一つあります。場合によっては値上げになっているわけですから、いろいろとサービス向上のために頑張っていただきたいということ、以上です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-045"}]},{"id":"topic-04","title":"では、ちょっと時間が早いですけれども、第５２号議案の説明だけ聞いて、質疑については午後にしたいと思います。 それでは、(4) 第５２号議案…","agenda":"では、ちょっと時間が早いですけれども、第５２号議案の説明だけ聞いて、質疑については午後にしたいと思います。 それでは、(4) 第５２号議案…","exchanges":[{"speaker":"山村委員","kind":"意見","question":"情報モラル教育のあり方を実践的に研究するというか、どのようなことをやるのか、これだけちょっといまいちわからない。どのようなことをやるのか、わかっていたらとの意見を述べました。","respondent":"中島指導課長","answer":"そういったようなことに巻き込まれないようにするために、情報モラルという視点からの情報教育のあり方を検討していこうという趣旨です。市民科の中で実施をしていくことになりますけれども、こういったような点について、それぞれの学校の実態に合わせる形で研究をしていく。","id":"exchange-046"},{"speaker":"山村委員","kind":"質問","question":"いまいち指導内容がわからないんですが、まず最初に趣旨のところでお聞きしたいのは、これは要するに、子どもたちが情報をうまく操作できるように教育するという形か尋ねました。","respondent":"中島指導課長","answer":"そういう形をとることによりまして、最終的に、子どもたちが犯罪に巻き込まれないようにするための取り組みを重視していくという形になります。","id":"exchange-047"},{"speaker":"山村委員","kind":"意見","question":"犯罪に巻き込まれないようにするということは、要するにネット上のそういうことだとは思うけれども、今、ネット上であふれている情報によって、みずからが犯罪を犯さないようにする教育的なこともされるのかどうかとの意見を述べました。","respondent":"中島指導課長","answer":"小学校の高学年の段階から、例えば携帯電話とのかかわりですとか、こういった内容を具体的に指導していくような計画になっていくものと考えられます。基本的には、学校のほうで、これからこの内容、方法等を研究していくです。","id":"exchange-048"},{"speaker":"山村委員","kind":"質問","question":"すごくリアルなゲームですから、戦場でどういうことをするのかというのが全部ゲーム体験できるようになっているゲームが、日本でもやれますけれども。僕だって、大学生になってから持ったんですから、小学生は持つ必要はないとか言いたくなることはあります。","respondent":"中島指導課長","answer":"中学校ＰＴＡ連合会でも講演会を実施しておりますし、また、小学校ＰＴＡ連合会のほうでも分科会をつくって取り組んでいくような状況があります。","id":"exchange-049"},{"speaker":"山村委員","kind":"意見","question":"そういうことは、本来、学校がそこまで責任を負うことじゃないような気がいたしますので、重要だとは思うんですけれども。本来は自分にも責任があるのに、転嫁する材料に使われないようにしてほしいなと、私は思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-050"},{"speaker":"沢田委員","kind":"質問","question":"情報モラル教育事業で１６万円を組まれていますけれども、具体的にはどんなふうに使われるのか、教えてもらえますか。","respondent":"中島指導課長","answer":"講師謝礼に関しましては、さまざまな形でお呼びした講師への支払いということ。それから、報告書の印刷といったようなものが、予算の中で消化されていくという形です。","id":"exchange-051"},{"speaker":"沢田委員","kind":"質問","question":"大体、どのぐらいあって、品川区はそのうちどうなのかという資料はないんですか。なければないでいいんですけれども、どうなんですかね。","respondent":"中島指導課長","answer":"１８年度、すべての教科で実施をされていくですから、非常に多くの研究指定という形になります。情報教育だけではなくて、さまざまな形でこういう事業に取り組んでおりますので、その数はかなりにのぼるのではないかなと考えています。","id":"exchange-052"},{"speaker":"沢田委員","kind":"質問","question":"これは一貫教育の中の位置づけというふうになっているんですけれども、市民科か何かで使うんですか。どんな使い方をするんか尋ねました。","respondent":"中島指導課長","answer":"こちらのほうは、来年度から市民科で実施をしていきます茶道教育の貸出用の茶器一式という形になります。私どものほうで、２セットを貸し出しできる体制をつくりまして、そのはざまを埋めながら導入をしていきたいと考えているところです。","id":"exchange-053"},{"speaker":"西本委員","kind":"質問","question":"上神明小学校と御殿山小学校を選んだ経緯、どういう観点から選ばれたのか。それをまずお聞きしたいんです。","respondent":"中島指導課長","answer":"校長が小学校の教育委員会の視聴覚部の部長をずっと務めてまいりまして、校内全体として情報教育に先進的に取り組んでいるという状況があります。","id":"exchange-054"},{"speaker":"西本委員","kind":"質問","question":"では、区はどうなのか。せっかくこういう研究資金がきているわけですから、区としての活用の仕方、それはどのようになっていますか。","respondent":"中島指導課長","answer":"いずれも、何か発表会のようなものを実施するというような規定は、要綱上はございません。さまざまな形での情報教育の研修会が実施されておりますので、今後、考えていくところです。","id":"exchange-055"},{"speaker":"西本委員","kind":"質問","question":"校長一人でできるわけではなくて、学校としてくるわけですから、その学校の中での先生方の意識がどういう形なっているのかなと。そういう中で、これらが負担という形になるのではもったいないと思いますので、そこのやり方、指導はどういうふうにされるんか尋ねました。","respondent":"中島指導課長","answer":"今、取り組んでいる結果が、そのまま文部科学省の指定に反映できるものと考えております。より深みを与えてくれるという形で、両方とも、小中一貫教育の中での位置づけがより深まるものと見込んです。","id":"exchange-056"},{"speaker":"西本委員","kind":"確認","question":"最後に一つお願いと確認なんですが、今後、考えられていないんでしょうか。なるべく多くの方に、それが見えるような仕組みがつくれないかなと思うんですが、どのようにお考えか尋ねました。","respondent":"中島指導課長","answer":"ホームページ等で、そういったところにアクセスしていただく方に関しては、こういう研究をやってきたんだという部分は見ていただけるかなと思います。","id":"exchange-057"},{"speaker":"西本委員","kind":"意見","question":"今、こういう取り組みになっているとかということについては、いろいろな媒体を使って報告のお願いをしておきたいと思います。これはお願いですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-058"},{"speaker":"南委員","kind":"確認","question":"１年間かけての教育ということで、これは上神明小学校ですから、１年生から６年生まですべての授業が対象だと受けとめていいんでしょうか。学校関係は、５校ですべて終了だと確認していいのかどうか。","respondent":"中島指導課長、市川庶務課長","answer":"こういう単年の形式のモデル校実施、指導計画につきましては、１年生から６年生までの全体の指導計画を立てていく形になろうかと思います。教員のほうに、さまざまな視点をサジェスチョンしていただけるような講師もいますので… 学校関係のアスベストにつきましては、先般、委員会報告のときに報告させていただいた囲い込みという処理をした学校があと２校あります。","id":"exchange-059"},{"speaker":"南委員","kind":"質問・要望","question":"ほかの５校が開設した時期とアスベストの関係のところで、なぜ八潮小学校だけというのが、それはそれとして伺っておきたいと思います。ほかのところがないということで確認されているようなので、周知のほうは、ぜひよろしくお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-060"},{"speaker":"松澤委員","kind":"質問","question":"こんな質問はどうかと思うんですけれども、ここの校長は長いですよね、１０年近くになるんですかね。ちょっとその辺、何か理由があるんだったら。","respondent":"中島指導課長","answer":"上神明小学校につきましては、文部科学省の系の学習という研究開発学校を受けた経緯がございましたので、それがベースとなった形での取り組みです。情報モラル教育という形で、またそれとは違った視点から受けるというのは、久しぶりの形になろうかと思っています。","id":"exchange-061"},{"speaker":"松澤委員","kind":"質問","question":"ここの校長は家庭科出身ですから、すばらしい校長なのかなと思ったものですから、ちょっと質問させてもらいました。いろいろあるということですので、またの機会に。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-062"},{"speaker":"三上委員長","kind":"質問・要望","question":"では、ちょっと私のほうから、確認と、伺わせていただきたいことがあります。やっていらっしゃるのか、どうか、確認したいと思います。","respondent":"中島指導課長","answer":"それから２点目の、研究学校のこれまでの経緯ですが、現在、区のホームページには、一覧表としては掲載してございません。今後また、今のお話を受けまして、検討をしてまいりたいと思います。","id":"exchange-063"}]},{"id":"topic-05","title":"平成１７年陳情第４号、区立小学校に関する陳情","agenda":"平成１７年陳情第４号、区立小学校に関する陳情","exchanges":[{"speaker":"西本委員","kind":"質問・要望","question":"前回は、教育委員会でも同じような案件というのはないというふうにお聞きしたんですが、その後、何か各学校にそういうのはありますか。校長のお話ですと、何か情報がありましたら、教えてほしいと求めました。","respondent":"中島指導課長","answer":"その後、こちらのほうでこういうふうな話題が出ているという形で、何校か各学校と話をする機会がございました。その中で、同様の申し入れなり、苦情みたいものが届いているということはございませんでした。","id":"exchange-064"},{"speaker":"西本委員","kind":"質問・要望","question":"それは要望として言っておきましょうとか、この陳情をどういうふうに受けとめていいのかなと、非常にわかりづらいなと思っているんです。その辺は何か、学校のほうでどうであったのかというのは、わかりますか尋ねました。","respondent":"市川庶務課長","answer":"このご質問の答えは、非常にデリケートな部分もあるので、その辺、ちょっとあらかじめご了承いただいて、説明します。わかりにくい説明で、申しわけありません。","id":"exchange-065"},{"speaker":"西本委員","kind":"質問","question":"担任の先生から校長へという形の流れで、学校における問題というふうにとらえて、いろいろ検討していくという形が本来の姿であってほしいなと。違うかもしれませんけれども、そうならないでほしいなというのが、私の願いとしてあります。","respondent":"市川庶務課長","answer":"そういうことで、こういう手段を取られたんじゃないかなと、私は思ってあります。それと同時に、当該校は、一般的に、今、委員が懸念されたようなことはないと、私は判断しております。","id":"exchange-066"},{"speaker":"西本委員","kind":"質問・要望","question":"当然、それぞれの学校で努力されていると思います。子どもたちの要望を区のほうに伝えていくというのは、そういう話しやすい環境づくりを進めていただきたいという要望で終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-067"},{"speaker":"南委員","kind":"質問・要望","question":"いろいろなご要望を受けとめて、私もちょっと質問させていただいたように、あるんじゃないかと思っているんです。ですから、お伝えしていただていると受けとめましたので、そういうことで受けとめていきたいというふうに思っております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-068"},{"speaker":"松澤委員","kind":"質問","question":"それなりにいろいろな改善をしてきているということですから、全体として、これを趣旨採択するのがいいのかなという気がするんです。ですから、継続はいかんという声もありますけれども、私は、これは継続するかなという気がするんですけれども、結論を出しづらいですからね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-069"},{"speaker":"沢田委員","kind":"意見","question":"私学へ行けということかとかなり激しい文章なんで、ちょっとどうかなという気もしないではないというのは、確かに私も思うんです。全体の声を聞いてほしいという格好で、趣旨採択しかないんじゃないかと思うんですけれども、私の思いですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-070"},{"speaker":"大沢副委員長","kind":"意見","question":"限られたサンプルですけれども、私の子どもも１年生で、行っているんですけれども、お母さん方に聞いても、それは大して苦にならないと。趣旨はわかるんですけれども、私は、これは採択すべきではないと考えますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-071"},{"speaker":"若林委員","kind":"質問","question":"前回、黄色い帽子が小学校を通じて新１年生に配布をされているという事実、詳しく経緯をお聞きいたしました。ご本人も、ああそうかというふうに納得をしたと、私の思うところが正しいのであれば、継続をしないで、何らかの結論を出すのも一つかなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-072"},{"speaker":"山村委員","kind":"意見","question":"暑かったら脱ぐだろうという気はするんです。どうしていいのか、私も一致しましたので、結論は出すべきだと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-073"},{"speaker":"西本委員","kind":"意見","question":"継続というよりは、ここできちんとけじめをつけたほうがいいんじゃないかと、私として判断したいと思います。今のお話ですと、幾つかお話を聞いている状況も受けましたので、ここで結論を出すということの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-074"},{"speaker":"三上委員長","kind":"確認","question":"もう一度確認をするということで、十分に反映されていると受けとめていただいたとするならば、それはそれで取り下げるということも一つの手ではある。２回にわたりまして、ご本人のを意思をもう１回確認をさせていただいて、いかがか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-075"},{"speaker":"南委員","kind":"確認","question":"どういう結論になるにしても、２回に分けて議論し、３回の議論をする。委員長がご本人に確認して、そういうことも含めて扱っていきたいということで、言っていただければいいんじゃないかなと思っているんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-076"},{"speaker":"沢田委員","kind":"質問","question":"そうすると、別に義務というか、黄色い帽子であれば、どれでもいいというスタンスなんか尋ねました。","respondent":"市川庶務課長","answer":"もう３０年来、４０年来、一般の帽子店でも別途売っております。これが実情です。","id":"exchange-077"},{"speaker":"山村委員","kind":"質問","question":"ちょっと沢田委員と同じようなことですが、要するにじゃあ黄色い帽子をかぶらなきゃいけないんですか、かぶらなくてもいいんか尋ねました。","respondent":"中島指導課長","answer":"交通安全指導として、今、庶務課長のほうから話をしたように、定着している認識の部分があります。規則として決めている部分ではございません。","id":"exchange-078"},{"speaker":"山村委員","kind":"質問","question":"そうすると、教育委員会の皆様方、我々もそうですけれども、告知不足ということで、よろしいんじゃないですか。そういうことになってしまうんか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-079"},{"speaker":"若林委員","kind":"提案","question":"ご本人に、ここまで審議を尽くして、こういうことでしたよと。私は委員長の提案を受けると思ったので、そういう意味であれば、私は委員長の提案に従ったほうがいいなと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-080"},{"speaker":"西本委員","kind":"提案","question":"非常に自然な採決だなと思っていまして、委員長のほうからいいご提案があったと思っているんですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-081"},{"speaker":"沢田委員","kind":"提案","question":"扱い的には、委員長の提案で結構です。だから、そういう点で、その可能性を探る意味で、委員長提案に賛成ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-082"}]},{"id":"topic-06","title":"に入りたいと思います。 平成１８年度使用中学校教科用図書採択","agenda":"に入りたいと思います。 平成１８年度使用中学校教科用図書採択","exchanges":[{"speaker":"山村委員","kind":"質問","question":"私もあまりよくわかっていないので質問するんですが、理科１、理科２は学校図書で、同じ会社が採用されているんですけれども、音楽一般と音楽器楽ですと、会社が変わりますけれども、僕から見ると、同じ教科だという気がするんですが、教科書の会社が違うことによる弊害というのはないんか尋ねました。","respondent":"中島指導課長","answer":"ただ、音楽ですとか、技術、家庭といった教科につきましては、単元ごとの学習を行います。一般の音楽の教科書としての中身、器楽としての中身を重視して選んだ結果が、このような結果になってきてあります。","id":"exchange-083"},{"speaker":"山村委員","kind":"質問","question":"そうすると、例えば理科１、理科２とかは、国語、書写とかは、同じ出版会社になっていますけれども、大体普通はそういうふうにやるものなんか尋ねました。","respondent":"中島指導課長","answer":"関連する内容を扱ったような部分もございまして、書写の教科書を選択する一つの理由になっている部分はございました。しかしながら、理科につきましても、書写につきましても、総合的な見地から判断をして、結果的には同じ教科書会社という形になってあります。","id":"exchange-084"},{"speaker":"南委員","kind":"質問・要望","question":"よその教育委員会と、いい、悪いの比較をするつもりはないんですけれども、大体そういうものなんですか。その辺の状況を教えてほしいと求めました。","respondent":"中島指導課長","answer":"その中でポイントになるところを、指導主事が説明をさせていただいてあります。こういった調査研究資料を、指導主事がその場で説明をして、採択に入っていただくといった品川区の形をベースにしたものになっていると考えています。","id":"exchange-085"},{"speaker":"南委員","kind":"質問・要望","question":"傍聴者に資料を配ってほしいなんていう声を、区民の皆さんから伺うんですけれども、事前にいただけないんでしょうか。ちょっと検討していただきたいと考えていますので、それについて、最後に質問して終わります。","respondent":"市川庶務課長","answer":"教育委員会の審議の場で、いろいろなものがあります。まさに意思形成過程のものも含めてありますので、一律に傍聴者に資料を配るということは、今の時点ではできないと考えています。","id":"exchange-086"},{"speaker":"松澤委員","kind":"質問・要望","question":"テレビでやっている扶桑社の教科書ですかね、この扶桑社の教科書って、うちの教科書と何か違うところがあるんですか。私はよくわからないんですけど、その内容について、ほかの教科書と特に大きな差異がありましたら、お教えほしいと求めました。","respondent":"吉村小中一貫教育担当課長","answer":"学習指導要領の内容に沿った内容であると、まず原則的には、そういうことが言えるかと思います。校長を含めた検討委員会等で話し合われたことを見ますと、学習指導要領にのっとって、原則にのっとっている教科書だと言えると思います。","id":"exchange-087"},{"speaker":"松澤委員","kind":"質問","question":"大体、品川区では継続してこの教科書を扱っているということですか。それとも、ときどきは変わっているんか尋ねました。","respondent":"吉村小中一貫教育担当課長","answer":"その前は、そうではなかったと思います。今回、そして来年度は東京書籍ということになります。","id":"exchange-088"},{"speaker":"沢田委員","kind":"質問","question":"私は、思想どうのこうのというよりは、むしろ、戦後の日本の憲法なんかをやって、立脚点そのものを覆すような記述になっているところに問題がある。ちょっと全然別で１点だけ質問したいんですが、購入費用というのはどのぐらいになるんでしょうか、わかりますか。","respondent":"古里学務課長","answer":"教科書の無償配付は私どもの仕事ですが、きょう、資料を持ち合わせてございません。改めて、ご報告します。","id":"exchange-089"}]},{"id":"topic-07","title":"行政視察","agenda":"行政視察","exchanges":[{"speaker":"山村委員","kind":"意見","question":"１２月の土曜日というと、いろいろ大変なことが多くなるとは思うんですが、今、１２月と決められても困るという思いが少しはあるんですが、そこら辺は、どういうふうに日程を調節したらいいのかとの意見を述べました。","respondent":"三上委員長","answer":"１２月の土曜日と申し上げますと、１０日、１７日、それから、１月になりますと１４日、２１日、２８日、２月でいきますと、１８日、３月でいけば４日と１１日が実施日になります。","id":"exchange-090"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/270991?Template=document&Id=4548#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2005-01-01&TermEnd=2005-12-31"}],"sourceMeta":{"pages":0,"characters":66173,"voices":222}},{"id":"h17-20050926-5","meetingId":"h17-cm09","date":"2005年9月26日","dateIso":"2005-09-26","committee":"総務委員会","time":"午前１０時０６分～午後３時３０分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を66件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"宮崎委員","kind":"質問","question":"参考に伺いたいんですけども、選挙管理委員会のほうですかね、どういうふうになるの。","respondent":"野田口選挙管理委員会事務局長","answer":"ですから、基本的には国の選挙の執行基準に基づいて予算は立てている。それで、お金はどういうふうに来るかといいますと、国から都を通じて、都の支出金という形で区のほうの歳入になる、こういう流れになっております。","id":"exchange-001"},{"speaker":"宮崎委員","kind":"質問","question":"わかりました。細かいことが違ってくるときがあると思うんですが、それは最後になって修正というか、訂正するということになるんか尋ねました。","respondent":"野田口選挙管理委員会事務局長","answer":"最終的には、調整費という形で最後に調整しますけれども、基本的には基準額を超えないようにそれぞれの事務の中身をやりくりしているというのが現状です。","id":"exchange-002"},{"speaker":"鈴木（真）委員","kind":"確認","question":"数字だけちょっとわからないところがあったので確認をさせてもらいたいんですけれども。その前１４ページに特別職の報酬７３８万８,０００円と出てくる、どこから歳出のほうは出ているのかなと思うんですけど、確認です。","respondent":"日下部企画財政課長","answer":"１４ページにその他ということで出てまいりますけれども、こちらの２７３人の方というのは、それから開票の管理者の方を指しております。７３８万８,０００円です。","id":"exchange-003"},{"speaker":"高星委員","kind":"意見","question":"余りにも見すぼらしい形でやって、これはどう見たって素人でもこんな仕事をしない。どんどんお金をかけないような形でやられてきているのかどうなのか、その辺の、今回どうであったのかというのをちょっと聞きたいなと思うとの意見を述べました。","respondent":"野田口選挙管理委員会事務局長","answer":"２４時間体制、すぐ駆けつけて修繕できるようにというような、そういった内容もあります。万が一のときには、急きょその経費の中で対応できるようにということで、というふうな仕組みです。","id":"exchange-004"},{"speaker":"高星委員","kind":"意見","question":"１２日間もてばいいという話もわかるんだけれども、見てくれも含めて、余りにも素人じみたことをやっちゃうと、どう見たって、あれはおかしいですよ。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-005"},{"speaker":"宮崎委員","kind":"質問","question":"投票所にシティコート目黒というのがありますけど、これはいわゆる学校だと場所代とかかからないと思うんですが、こういう場合どうなんでしょう。国の基準の中には、民間の施設の場合どうなのか、決まりがあるんか尋ねました。","respondent":"野田口選挙管理委員会事務局長","answer":"第１３投票所は民間施設ですけども、場所的にいい施設がないということで、シティコート目黒が住宅都市整備公団のときがあった、建つときですね。それで、経費としましては、当然執行経費の中に含んで、わずかではありますけれども、私有地賃借料の中でお金を支払っているです。","id":"exchange-006"},{"speaker":"宮崎委員","kind":"質問","question":"そういうのは、国の基準にはあるんでしょうか。それと、先ほどの公営掲示板の設置のところで、お礼というか、出しているという話だったかなと思うんですが、それはなかったですか、公営掲示板。","respondent":"野田口選挙管理委員会事務局長","answer":"ありがとうございましたということで謝礼は、謝礼といいますか、ちょっとしたものをお出ししているです。一応大体１投票所、そこが承諾を得られるかというと、なかなか難しいというのが現状です。","id":"exchange-007"},{"speaker":"宮崎委員","kind":"意見","question":"僕らの場合もポスターを張ったりするのもなかなか大変になってきているのでわかるんですけども、やっぱり人の通りだとか。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-008"},{"speaker":"中島副委員長","kind":"質問","question":"何のお金かなと思ったんですが、個人演説経費というのが入っているんですが、これは候補者に何か出すお金なんか尋ねました。","respondent":"野田口選挙管理委員会事務局長","answer":"その施設１回限り無料で使用することができるということで、その１回分を予想して、そういったようなことです。","id":"exchange-009"},{"speaker":"原委員","kind":"確認","question":"それはこの中では全体的に賃金としては、どの部分まで含まれているんでしょうか。要するに、今回の選挙でかかわった方々の総賃金みたいな形に出るのはあるんか尋ねました。","respondent":"野田口選挙管理委員会事務局長","answer":"職員給与費に当たる部分ですけれども、これは選挙管理委員会事務局の職員の超勤手当、それから地域センター、１３カ所で期日前投票を行います。やはり、多く比重を占めているのは、人に対する手当の部分が相当占めているという内容です。","id":"exchange-010"},{"speaker":"原委員","kind":"質問","question":"そうしますと、選挙にかかわる費用のうちの人件費にかかわる部分というのは、どのぐらいの割合なんですか。８０％になるとか、８５％ぐらいになるとか、出ているんじゃないかと思うんですが、ちょっとわかったら説明を求めました。","respondent":"日下部企画財政課長","answer":"人件費、実は１０ページの報酬から旅費に至る大体５項目をあわせますと、概ね５,５００万円ということになりますので、割合からいたしますと大体４５％、全体の経費の４５％をこの人件費が占めている、そのような内容です。","id":"exchange-011"},{"speaker":"中島副委員長","kind":"質問","question":"先ほどほとんどが人件費だということで、職員の給与費、投票事務、開票事務とあるんですが、この下に事務費とあるんですが、この事務はどういった事務なんか尋ねました。","respondent":"野田口選挙管理委員会事務局長","answer":"本部の従事者ということで、そういった対応のために選挙管理委員会事務局ＯＢの方たちにお願いして、本部の従事をしていただいているというものです。","id":"exchange-012"},{"speaker":"藤田委員","kind":"質問","question":"これはかなり突っ込んだ質問、どういう理由で今回投票したのかと、細かいことがずっと書いてあるんですね。こういうあれで調査したいんだということを選挙管理委員会事務局まで申し出るのか、この辺、ちょっと聞いておきたいと思います。","respondent":"野田口選挙管理委員会事務局長","answer":"地域センターでは、１週間ということで、期日前投票を行ってあります。１週間に限っては、厳重に保管するというようなことで、地域センターで保管しています。","id":"exchange-013"},{"speaker":"藤田委員","kind":"確認","question":"確認しますけれども、１週間の投票したものは、その中に入っているのか、そのまま金庫に入れるということなんですね。ですから、項目自体も、やはりちょっとここまでやるのかなというぐらいの調査項目があるものですから、ちょっと聞いてみたんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"鈴木（真）委員","kind":"質問","question":"その後の質問からすると、例えば１０ページだと１２節の役務費とか１３節の委託料、これもほとんどが人件費なのかなという感じもするんですけど。人件費の比率は４５％じゃなく、８０％、９０％ぐらいになっちゃうのかなという感じがするんですけど、その辺はどうでしょう。","respondent":"野田口選挙管理委員会事務局長","answer":"委託料の中に含まれていますので、そういった意味では、直接すべてがそういうわけではございません。そういった意味で、それだけ精査しないと、すぐには出ませんので、申しわけございませんけども。","id":"exchange-015"},{"speaker":"鈴木（真）委員","kind":"質問","question":"何かのとき、ちょっと１回どのぐらい出ているのかというのは知りたいなというところなんですけど。別に今日すぐ間に合わなければ、後で教えてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"高星委員","kind":"質問・要望","question":"勉強のためにちょっと今日は序曲ということで教えてもらいたいんですけど、１日何カ所までいいのか、ちょっと教えていただきたい。","respondent":"野田口選挙管理委員会事務局長","answer":"そういった意味で、夜１２時までであり、なおかつ５枚の表示物を掲示できる限りで可能な回数までできるです。時間的にどれだけ可能かというと、いろいろ考えれば、やっぱり５カ所で十分じゃないかというふうに思っております。","id":"exchange-017"},{"speaker":"高星委員","kind":"質問","question":"品川区全域にわたるわけですから、５枚まで看板いいですよとなると、２５枚になる。５時間というのはどういうふうに見るかというのはあるが、そうすると、個人演説会を開いていますよという看板が１人の人が２５枚用意する。","respondent":"野田口選挙管理委員会事務局長","answer":"大体１候補者は多くて２カ所というのがこれまでの実態です。普通は１日１カ所が多いですので、ちょっと現実的な話ではございませんので、そういうことでご理解いただきたいと思います。","id":"exchange-018"},{"speaker":"高星委員","kind":"質問","question":"５枚使っているのか、６枚使っているのかという表示物も、これもわからないと。そういうことをチェックする機能が選挙管理委員会事務局にあるやなしやをお聞きしたいと思います。","respondent":"野田口選挙管理委員会事務局長","answer":"これは５枚しか、同時には５枚しか掲示できないです。５時間というのは、公営施設は設置届出を受けることで、時間的な制限について守っているかどうかということは確認できるです。","id":"exchange-019"},{"speaker":"宮崎委員","kind":"意見","question":"なぜこの鋼矢板があったのかというのを、もう一度説明をお願いしたいのと、請求するところがあるのかどうなのか。検査して、そういうところはどういうふうになっているのかと思うんですけど、わかっている範囲でちょっと答えてほしいと求めました。","respondent":"原田下水道河川課長","answer":"それから、もともとは平成１７年６月に終わる予定でしたので、完成時期が延びたということも今回の影響です。それから申しわけありません、１点、これについては今のところ考えておりません。","id":"exchange-020"},{"speaker":"宮崎委員","kind":"質問","question":"随意契約に至った説明を伺ったんですけど、予定価格というのが全部出ていないんですけども、予定価格というのは一体幾らだったのか。ちょっとそこのところをあわせてお伺いしたいと思います。","respondent":"鷹倉経理課長、原田下水道河川課長","answer":"予定価格の件で、予定価格というのは、通常制限付の一般競争入札にする場合に、予定価格というふうな形でお示し協議するというものです。一番価格的にも妥当だというふうな判断のもとに協議をしながら進めていくというものですので… 損害部分の先ほどの推進機のマンホールの額ですが、推進機は我々で見積もったのは約５,３００万円、それから人孔２カ所については約３００万円、それに付帯する部分があるのかなという感じです。","id":"exchange-021"},{"speaker":"宮崎委員","kind":"質問","question":"予定価格のほうなんですけど、やっぱりそもそも随意契約というのは、相手を当初からお宅に決めるよというところから始まるんですよね。この場合ですと、どうやって透明性を担保するのかなというような心配があったものですから、どういうふうにとらえたらいいんか尋ねました。","respondent":"鷹倉経理課長","answer":"協議と申し上げたとすれば、訂正いたします。相手から申し出があって、うちのほうで、所管のほうで厳しく査定をして、この中でこちらのほうで決めていくという、協議ということはないと思います。","id":"exchange-022"},{"speaker":"宮崎委員","kind":"確認","question":"例えば、そこでのやりとりでかなり金額が変わってくるものなんですか。具体的に今回の場合はどういうふうになっているんか尋ねました。","respondent":"鷹倉経理課長","answer":"一般的にはその申し出の中で抑えられるということがあります。今回の場合は、引き続きということ、前回の関係といろいろございましたので、今回はかなり難しい要素があったというふうに所管からも聞いています。","id":"exchange-023"},{"speaker":"宮崎委員","kind":"意見","question":"価格はどういうふうに決められていくのかという、非常に今契約の問題ではニュースでもにぎわせたり、いろいろありますよね。随意契約でかなり高額な金額になっていますから、そこのところはちょっと指摘しておきたいなというふうに思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-024"},{"speaker":"鈴木（真）委員","kind":"質問","question":"どこにこんな差が出てくるのかというのを１点お聞きしたいのと、試掘なさったというお話がありましたけど、そのお金というのはどこで出ているのか。前の契約で出ているのか、今回のほうに絡んできているのか、その辺はどっちなんでしょう。","respondent":"原田下水道河川課長","answer":"そのほかにも立坑を新たに設置しますので、この辺が５,４００万円等ありまして、そういうことで全体で約４億５００万円工事費にかかるです。","id":"exchange-025"},{"speaker":"鈴木（真）委員","kind":"質問","question":"大分わかったんですけど、前回の契約のときには地盤改良の必要はなかったから安い金額で上がったということなわけですか。その点。","respondent":"原田下水道河川課長","answer":"そういうことになります。","id":"exchange-026"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"大もとの全体のその１工事、その６工事まで、当初から設計をしていた形なんですか。それを教えていただきたい。","respondent":"原田下水道河川課長","answer":"その１からその６工事まで当初から予定しておりまして、その１、その３工事からその６工事までが一つの工事ということになります。ポンプの設備を設置したという工事がありまして、その６が一つの組み合わせ、それでその４工事がまた別という流れです。","id":"exchange-027"},{"speaker":"鈴木（真）委員","kind":"質問","question":"工事を行う業者については、これはその１工事からその６工事までですか、それともその１、その２、その４、その３、その５、その６工事ですか、その辺はどうなっているの。","respondent":"鷹倉経理課長","answer":"今下水道河川課長が申し上げましたように、その１とその２と、それからその４工事が関連が出てまいりますので、ここは同じ業者がやっております。今回該当しておりますその３、その５、その６工事、今回その７工事については同じ業者、こういう流れになってあります。","id":"exchange-028"},{"speaker":"鈴木（真）委員","kind":"意見","question":"結果その７工事になっちゃいましたけど、随意契約がいいのかどうか、早く工事を終わらせてほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-029"},{"speaker":"藤田委員","kind":"質問","question":"もし５カ所設置した場合、どういうような影響が地域に対してあると思われるのか、一つ初歩的で申しわけないんですが。かむろ坂のほうから来ているバイパスと今回新たにやるその７工事の枝線なんですけれども、目黒川に対する影響というのはないんか尋ねました。","respondent":"原田下水道河川課長","answer":"工事説明会についてのご質問ですが、この工事は平成１６年度から行っておりますので、随時今回の内容で何度か周辺の方々にご説明しております。","id":"exchange-030"},{"speaker":"藤田委員","kind":"質問・要望","question":"そういう点も含めて住民にこういうふうになるんだということを懇切丁寧にやらないと、我々素人は不安だけがよぎってしまうということもありますので、ぜひとも説明会のときには区のほうが出ていって懇切丁寧にお願いしたいなということを要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"三村委員","kind":"質問","question":"先ほどの説明のところで、もうちょっと詳しくお伺いしたかったところが、契約の相手方というのは、こちらの都市再生機構以外のところというのは、該当するような会社はなかったということなんか尋ねました。","respondent":"上野都市開発課長","answer":"先ほど経理課長から説明がございましたけど、都市再生総合整備事業を実施するに当たりまして、契約の相手方はこの一つに絞られるということになります。","id":"exchange-032"},{"speaker":"三村委員","kind":"質問・要望","question":"委託内容というのは、すべて一式ということで詳しい内容が書かれていないんですけど、その辺の内容について、もう少し詳しくご説明いただきたい。","respondent":"上野都市開発課長","answer":"それからあとは、駅前広場につきましては、道路の築造とほぼ同じような工事内容となります。それからあと、地下の掘削する工事、そういったものが内容となります。","id":"exchange-033"},{"speaker":"三村委員","kind":"意見","question":"すべてどのぐらいの、金額的には幾らかかる形になるのかと、次回からでいいんですけど、もう少し詳しくこういった資料、委託内容のところももう少し詳しく、事前の資料として見せていただければと思うんですけれども、金額だけとの意見を述べました。","respondent":"上野都市開発課長","answer":"都市再生機構は国土交通省の外部団体として位置づけられていたものですけれども、工事費を積算するに当たりましては、国の基準である土木・造園工事の積算要領ですとか、公共住宅の建築工事の積算基準を使ってありますので、区が積算したものとほぼ同等の積算額となります。","id":"exchange-034"},{"speaker":"宮崎委員","kind":"意見","question":"費用の負担はどこで負担するのか聞いておきたいと思います。それとあと、区と都市再生機構の間では随意契約なんだけど、都市再生機構は施工者のところとはどういう契約になるのかというのを聞かせてくださいとの意見を述べました。","respondent":"上野都市開発課長","answer":"それから２点目の実際の施工者ですけれども、そちらのほうで指名競争入札等を行って、業者を選定することになってあります。その契約の仕方は、都市再生機構の基準に従ってプロポーザル方式とか種々のものを採用することになっているようです。","id":"exchange-035"},{"speaker":"宮崎委員","kind":"質問・要望","question":"ちょっと国費のほうが幾らになるかというのが具体的にわかったら教えていただきたいのと、もう一つ、それはどういうふうに扱っていくのかな。そこの仕組みがちょっとわからないので教えていただきたい。","respondent":"上野都市開発課長","answer":"国の補助金につきましては、国費で６億４００万円が入ってくる見込みです。都市再生機構が契約した金額でもって最終的に区も都市再生機構と決算をするということになります。","id":"exchange-036"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"９ページの右のほうに地下駐輪場出入口階段となっているんですけど、ここも入口になっているのかどうか１点教えてください。平成１７年度の予算に明電舎とソニーからの寄附金になるのかな、どういった名目になるのか、そこら辺を教えていただきたい。","respondent":"上野都市開発課長","answer":"これから平成１９年度まで工事はかかりますけれども、各年度ごとにそれぞれ明電舎とソニーから区のほうに納入される予定となっています。これは協定に基づきまして、各年度に入ってくるということになってあります。","id":"exchange-037"},{"speaker":"鈴木（真）委員","kind":"確認","question":"平成１７年度の予算書を持ってきていなかったので確認できなかったので、質問させていただきました。この交通広場は平面のままでいけるのかなというのが、ちょっとそこら辺が気になるんですけど。","respondent":"上野都市開発課長","answer":"補助１６３号線については若干高低差、地下を少し削る考え方でＪＲはおりますけれども、この交通広場には影響しない予定です。もう少しソニー側のもっと南のほうに下ったところで下がっていく構造になろうかと考えています。","id":"exchange-038"},{"speaker":"鈴木（真）委員","kind":"意見","question":"反対側の百反側というのはほとんど使いにくいような状態になるんじゃないかなとちょっと気になったので、その辺どうなのかなと。５２ｍというと結構端に置きに行くには、駐輪場としては、駅前駐輪場、ちょっと気になるんですけど、どうでしょうとの意見を述べました。","respondent":"上野都市開発課長","answer":"今のところ６００台のうち、稼働するのはおそらくこのうちの６割ぐらいというふうに見ておりますけれども、ご案内などをすることで調整したいと思います。","id":"exchange-039"},{"speaker":"原委員","kind":"質問・要望","question":"ちょっとだけ確認させていただきたいんですが、その整備に１１億円かかるという話をされていたんですが、できるような形になっているのか。例えば、ソニーの負担とか、あるいは明電舎の負担とかいろいろあるのか、その辺ちょっと。","respondent":"上野都市開発課長","answer":"それから負担につきましては、デッキと交通広場につきましては、明電舎全額負担の予定です。駐輪場につきましては、明電舎とソニーでそれぞれ７対３の割合で負担する予定となっています。","id":"exchange-040"},{"speaker":"藤田委員","kind":"質問","question":"やっぱりＪＲと国、この周辺は副都心というふうに位置づけられていますので、一番ネックになるのは百反隧道ではないかと思うんですね。現段階での考えというのはどういうふうに思っていらっしゃるんか尋ねました。","respondent":"上野都市開発課長","answer":"両方の方がご利用できるような形での改修する方向での検討を進めていきたいと考えてございまして、ＪＲの短絡線計画にも関係してきますので。基本的な考え方として、構想レベルでは、これは超長期的な課題というふうに認識しています。","id":"exchange-041"},{"speaker":"藤田委員","kind":"質問・要望","question":"これは要望しておきます。ぐるっと回って、せっかくの街づくりを進めているわけですから、もうちょっとこの辺を考える必要性があるんじゃないかなというふうに思います。","respondent":"上野都市開発課長","answer":"今の百反隧道を車がもっとスムーズに通れるような形で解消することで、当面の交通管理は処理できるというふうに見込んでいるところです。長期的な形については、十分検討していきたいと考えております。","id":"exchange-042"},{"speaker":"宮崎委員","kind":"質問","question":"将来的に再開発の促進という目的を持っているんですけども、住民との関係はどういうふうに、うまく説明されているんか尋ねました。","respondent":"上野都市開発課長","answer":"この地区の中でソニー通りと環状６号線を結ぶ非常に重要な道路でございまして、この道路、それを促進するためにまず橋の整備を先行的にやるです。","id":"exchange-043"},{"speaker":"鈴木（真）委員","kind":"質問","question":"契約で１３億円のうちの先ほど現場で仮の橋の架け替えというお話があったんですけど、仮の橋はどのぐらいそのうち占めているんでしょうか。下流側に橋を架け替えるとおっしゃったじゃないか尋ねました。","respondent":"上野都市開発課長","answer":"架け替えするのはいわゆる除却費になろうかと思います。","id":"exchange-044"},{"speaker":"鈴木（真）委員","kind":"意見","question":"今の橋じゃなくて、今度つくったところのもっと下流側に今の橋が通れなくなるからかわりをつくるという話だと思ったんですね。なぜかというと、ちょっとあそこでも何人か声が出ていたんですけど、下にもありますよね、小関橋とか、そこまでどうなのかなと、ちょっと金額的にとの意見を述べました。","respondent":"上野都市開発課長","answer":"架替工事が行われる、新たに新設される橋の下流側に仮設の歩道橋を設置します。その仮設の歩道橋の工事費は大体今２,０００万円ぐらいを見込んです。","id":"exchange-045"},{"speaker":"鈴木（真）委員","kind":"質問","question":"歩くだけだから安いという意味なのか、こっちが広いからというのか、その辺はどうなっているのかな。もう一つは、さっきと同じになるんですが、財源的には北品川五丁目第１地区市街地再開発組合がこの費用を負担するということでよろしいんか尋ねました。","respondent":"上野都市開発課長","answer":"今のところ、地元の組合としては、平成１９年度には設立したいというふうに考えているところです。組合設立以降、事業を完了するまでの間、区のほうに納入していただくという調整をする予定です。","id":"exchange-046"},{"speaker":"鈴木（真）委員","kind":"質問","question":"そうすると、平成１７年度契約すると、何割か支払いする、その財源とか、平成１９年度の設立ですと、平成１８年度にも払っていきますね。平成１９年度も当初組合設立していなければ、この費用負担は区の独自の財源ということになるわけか尋ねました。","respondent":"上野都市開発課長","answer":"一部国費が補助金として入ってきますけれども、そういう意味では組合のほうの金額が、負担金が入ってくるまでは一時期区のほうで先行して立て替えという形になるものです。","id":"exchange-047"},{"speaker":"鈴木（真）委員","kind":"意見","question":"平成１９年度に組合が設立、架け替えが２０年、要するに１９年度いっぱいかかっていますよね。そこは非常に車の流れが今後、今からスタートしちゃうと非常にむだな感じもするような気もするんですけど、その辺はどうなんでしょうとの意見を述べました。","respondent":"上野都市開発課長","answer":"事業を促進するという意味合いがありますので、そういう面では、今の時期から着手して整備を図っていくといことです。北品川五丁目第１地区のほうの事業完了までには、平成１９年度に組合設立いたしましても、支障のないような形で対応していく考えです。","id":"exchange-048"},{"speaker":"鈴木（真）委員","kind":"意見","question":"財源のさっきのちょっとしつこいようですけれども、平成１９年度設立見通しでいって、現状で確約できていない状況の中で、負担、区が先に負担していくというのはどうかなと。","respondent":"上野都市開発課長","answer":"組合設立、法的に公的法人として認められることになりますので、その公的法人になれば金融機関も融資する準備が整うということになります。","id":"exchange-049"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"当然必要な分は区でお金を払う、区の一般財源でもいいかもしれないけど、そこら辺のところをきちっとしていっていただきたいなという思いです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-050"},{"speaker":"本田委員","kind":"意見","question":"その辺は今どう進んでいるのか、関連しているんだと思いますけれども。その辺は今少し鈴木真澄委員の議論の中でちょっといま少し第１地区の開発との関連で先行投資することの意味、ご説明を聞きたいと思うんですがとの意見を述べました。","respondent":"上野都市開発課長","answer":"平成２０年３月に完了する予定ですけれども、北品川五丁目第１地区のほうは、順調にいけば平成２０年度中には着手したいという考え方でおります。","id":"exchange-051"},{"speaker":"本田委員","kind":"質問・要望","question":"先行投資を１３億円もしておいて、企業等と詰めていっていただきたいというふうに思いますので、一言要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-052"},{"speaker":"高星委員","kind":"質問","question":"トータル的にしてみたら、品川区の文教委員会が各地方に教育の勉強をしに行って、「何しに来たの。これはどういうふうに扱っていったらいいのかお聞きしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-053"},{"speaker":"高星委員","kind":"意見","question":"これは今日的な経済状況をどう見るかのような大きな課題も含むんだというふうに思うけれども、トップレベルのぜい肉、いわゆる計算されていなかった。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-054"},{"speaker":"三村委員","kind":"意見","question":"資料ありがとうあります。どういう仕組みになっているのか、電子入札制度はどういうふうな形で考えていくのかとかというところもいただけるとありがたいなと思うんですけどとの意見を述べました。","respondent":"塚本委員長","answer":"それは、今日、明日としか日程がとれなかったもので、後日時間をとりたいと考えております。","id":"exchange-055"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"ちょっと確認だけまずさせていただきたいんですが、横長のほうの改定表をあけたところに、(3)住居手当がありますよね。その辺、どうお考えなのかなというのを教えていただきたい。","respondent":"桑村人事課長","answer":"基本的には１人で行って、一定手当も必要なのかなというのは、今のところの考え方です。今の時代背景といいますか、それも必要ないということになればまた検討する必要もあるかと思います。","id":"exchange-056"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"定期代６カ月分、４回分の融資があって、その思いが強かったんでね。大変だというのも十分わかりますので、むだのないような形をお願いしたいなということで、それは要望にしておきます。","respondent":"桑村人事課長","answer":"民間のほうでもらうということだったら、私のほうは出さないし、私どものほうでもらうということであれば、向こうは出さないということになります。私のほうが出すときに、向こうから出ないという証明をもらって出すという、そういう形になっています。","id":"exchange-057"},{"speaker":"中島副委員長","kind":"確認","question":"たしか前にもお伺いしたと思うんですが、今改善の方向に向かっているということなので確認だけしておきたいと思うんですが。「８時間の勤務日に勤務した者（６時間以上勤務）」というのは、どういう意味なのか理解できなかったんですが。","respondent":"桑村人事課長","answer":"６時間以上勤務すればつけようと、そういうところがありまして、こういう表現になってあります。４時間以上幾らというのを廃止しまして、今回これを１本にするときに、こういうふうにさせていただいたです。","id":"exchange-058"},{"speaker":"中島副委員長","kind":"質問","question":"これは結構民間の方からもよく言われるんですけど、こういう方が１週間の中でどこかに休日はとっているわけですよね。ほかの日に休んでいるんだから、特に手当をつけなくてもいいんじゃないかという声があるんですが、この辺の改善の余地はあるんか尋ねました。","respondent":"桑村人事課長","answer":"不規則なところのあり方というのは、それから全くのほんとうに不規則というところでちょっと差があるんだろうと思っています。金額の多寡もあると思いますけど、そういうような気持ちをしています。","id":"exchange-059"},{"speaker":"中島副委員長","kind":"質問・要望","question":"その人の生活のリズムも狂ってしまうでしょうから、メリットもありますから、その辺のところをしっかりバランスをとっていただけるように要望しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-060"},{"speaker":"三村委員","kind":"質問","question":"具体的には扶養手当、第１子から第３子まで徐々に金額が下がっていくような形になっているじゃないですか。第３子は２万円とか、第３子のほうに振り分けていくような戦略的な扶養手当の打ち出し方というのはできないのかなと思うんですけど、どうでしょう。","respondent":"桑村人事課長","answer":"いわゆる１５歳から２２歳というあれなんですけど、４,０００円と今数字出ていますけども、一定の数字を措置したりもします。多子については一定の金額加算、委員がおっしゃっておられたと思いますけれども、財政的なことも含めまして検討させていただきたいと思います。","id":"exchange-061"},{"speaker":"原委員","kind":"質問","question":"１７年の取り組みという大きな形の中で進められているわけですけど、次の時点をまた考えていかなきゃいけないのかなというふうなことを思っているんですけど、その辺はどうなんか尋ねました。","respondent":"桑村人事課長","answer":"それについて、やはり対応というんでしょうか、窓口の方のお話の仕方、あるいは接遇の仕方で、その方がどんな方であるのか、わかると思うんです。それをなるべく減らすということが一つの目標です。","id":"exchange-062"},{"speaker":"原委員","kind":"質問・要望","question":"そこで、じゃあどういうところを求めに応じられるかというのをある程度検証する必要があるのかなと思うんですね。おまえのところはできないじゃないか、その辺のところも今後の中での考え方ですか、そんなところもしっかりやっていただきたいなと思います。","respondent":"桑村人事課長","answer":"そのときどういう対応をしているかを観察して、それを持ち帰ってきて、それぞれの対応とかを評価する。どうしても期限ですとか法律ですとか、そういったものが前面に出てきますので、なかなか納得した答えをお答えするのは難しいということがあります。","id":"exchange-063"},{"speaker":"宮崎委員","kind":"質問","question":"これは例えば平成１７年度、勤続１５年で２４.５０となっているのは２４.５０カ月と、そういうことでいいんでしょうか。それで、掛ける２４.５０ということなんか尋ねました。","respondent":"桑村人事課長","answer":"一番上ですと１５年になりますと、平成１７年度は２４.５０月。それから、調整手当とかいろいろありますけど、そういうのはなくて、いわゆる基本給に２４.５０カ月を掛ける。","id":"exchange-064"},{"speaker":"宮崎委員","kind":"質問","question":"それとあとは、これは定年退職なんですけれども、定年にならない退職とはまた別の基準というふうになっているんでしょうか。例えば同じ勤続で１５年の場合は、定年退職の場合は２４.５０カ月ですけど、具体的に例えば１５年だとどのぐらい。","respondent":"桑村人事課長","answer":"１５年ですと、１６.７５月です。ここですと、２４.５０月ですけども、いわゆる自己都合で普通退職しますと１６.７５月という形になります。","id":"exchange-065"},{"speaker":"宮崎委員","kind":"意見","question":"今のは１５年だったですけど、例えば普通の退職で、２５年ぐらいですと、定年退職の場合だと４５.５０カ月ですよね。定年退職じゃなくて、普通の退職ですとどのぐらいになりますかとの意見を述べました。","respondent":"桑村人事課長","answer":"２５年で３２.５月。","id":"exchange-066"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/594587?Template=document&Id=1696#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2005-01-01&TermEnd=2005-12-31"}],"sourceMeta":{"pages":0,"characters":56827,"voices":205}},{"id":"h17-20050927-6","meetingId":"h17-cm09","date":"2005年9月27日","dateIso":"2005-09-27","committee":"区民委員会","time":"","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を40件整理しています。","topics":[{"id":"topic-01","title":"がとうございます。それでは、本件については終了いたします。 次に、請願第７号および請願第１０号「小規模費住宅用地の固定資産税・都市計画税の減免措置の継続につい…","agenda":"がとうございます。それでは、本件については終了いたします。 次に、請願第７号および請願第１０号「小規模費住宅用地の固定資産税・都市計画税の減免措置の継続につい…","exchanges":[{"speaker":"伊藤委員","kind":"質問","question":"この「比較」の「較」なんですか。これでいいんか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"}]},{"id":"topic-02","title":"の「品川区年末対策特別事業資金２００５」の実施","agenda":"の「品川区年末対策特別事業資金２００５」の実施","exchanges":[{"speaker":"須貝委員","kind":"確認","question":"確認なんですけれども、融資条件をお聞きしたい。というのは、実際ちゃんと返済できているのかとか、その辺の状況もあるんじゃないかと思うんですけれども、その辺、状況を説明を求めました。","respondent":"金子産業振興課長","answer":"参考までに、昨年度の代位弁済の率ですけれども、１６年度は６.２７％ということですね。その意味では厳しくもなく、私どもとしては妥当な紹介状のあっせんをしているかなというふうに考えておるところです。","id":"exchange-002"},{"speaker":"須貝委員","kind":"質問","question":"質問の前段にもちょっと申し上げたんですけれども、融資条件ですか、ここら辺についてはどのような問題点が。融資条件から外れたのか、それとも、そこの企業の方が辞退されたのか、その辺も、もしつかんでいるようでしたら説明を求めました。","respondent":"金子産業振興課長","answer":"平成１６年度の状況で、融資あっせんをして実行されなかったのが全体で２８件あるわけですけれども、このうち保証協会が否決した分が１４件。","id":"exchange-003"},{"speaker":"中塚委員","kind":"質問","question":"前年度の実績で、例えば１６年度もありましたけれども、１４年度、１５年度、近年の傾向ですか、融資、実行の件数等、ご説明いただけますか。","respondent":"金子産業振興課長","answer":"１５年度が３５９万、１６年度が３４６万と、融資額については下がってきています。これが現状です。","id":"exchange-004"},{"speaker":"中塚委員","kind":"質問・要望","question":"融資額が若干減っており、あと、あっせんの数自体は減っているのかなと思うんですけれども、これもやっぱり、融資そのものをなかなか受け入れないぐらい厳しい状況になっているのか、その辺、品川区の中小企業の状況をもうちょっと教えていただきたいんですけれども。","respondent":"金子産業振興課長","answer":"あるいは地銀が、そちらの方でも借りるようになってきているという現状がありますので、全体として減少してきている。そういった理由であるのではないかというのが、私どもなりの見解です。","id":"exchange-005"},{"speaker":"武内委員","kind":"質問・要望","question":"教えていただきたいんですけど、通常だと売り上げが前年比で減っているところというのはなかなか借りられない場合が多いんですけど、そういう企業のための救済措置みたいな意味あいがあるんか尋ねました。","respondent":"金子産業振興課長","answer":"経営の安定性等々、さまざまな要素から私どもとしても紹介状を発行するかの判断をしているところでありますので、単純にこれがそれを保証するものであるというわけではないということは言えると思います。","id":"exchange-006"},{"speaker":"武内委員","kind":"意見","question":"そうすると、逆に、売り上げ等が極端に大幅に減少しちゃったりするとか、危ないとか、そういうようなところもどの辺まで貸してもらえるのか。あまり売り上げが減ってきたりしていると、逆にはねられちゃうのか、その辺はとの意見を述べました。","respondent":"金子産業振興課長","answer":"委員ご指摘の前段の部分は、委員のおっしゃるとおりだろうと思います。適切な対応、紹介状の発行に至る場合が多いわけですけれども、そのように適切に判断して対応しています。","id":"exchange-007"},{"speaker":"武内委員","kind":"質問","question":"逆に、これはちょっと、このままではつぶれちゃって返済能力がないんじゃないかというような判断で紹介状を発行しないということはあるんですか。実際、前年の段階であったかどうか。","respondent":"金子産業振興課長","answer":"通常の相談も含めて申し上げますと、返済がし切れないのではないかという場合には紹介状を発行しないケースも、それはあります。その場合には、さまざまな相談もお受けしながら、融資以外の方法も含めてご相談を受けているです。","id":"exchange-008"},{"speaker":"武内委員","kind":"質問","question":"通常の場合は確かにそういうケースが、私が紹介してもあるんですけれども、この場合は、そういう方たちの救済みたいな意味があるんではないかと思うんですけれども、年末のこの事業についての紹介状を発行しているかしていないかというところまではわからないんか尋ねました。","respondent":"金子産業振興課長","answer":"相談員が相談に当たる基本的な考え方として、返済能力を考えて相談を受けているということですので、そのようにご理解していただきたいと思います。","id":"exchange-009"}]},{"id":"topic-03","title":"のプレミアム商品券の発行","agenda":"のプレミアム商品券の発行","exchanges":[{"speaker":"伊藤委員","kind":"質問","question":"１５年度が２億円で１６年度が１億円になった、半額になったのはどうしてでしょうかということと、これから１億円でするわけですから。考え方と、それからそれを今年も１億円でやるというその考え方、なぜなんでしょうかということを説明を求めました。","respondent":"金子産業振興課長","answer":"１５年度、この２億円を販売するというのは、売り切るというのにかなりの努力を要したということを商店街の方でお聞きをしております。１６年度は１億円に、この２億円よりは１億円が妥当な金額だろうということで、今年度につきましても１億円で実施するというふうにしています。","id":"exchange-010"},{"speaker":"伊藤委員","kind":"質問","question":"ですから、例えば１億５,０００万の枠をつくって考えてみるとか、そのことはお考えにならなかったんでしょうかということを。そういう位置付けを含めて、改めて答弁いただけますか。","respondent":"金子産業振興課長","answer":"この金額についての検討はされたかということですけれども、５％よりは１０％、それなりの効果がなければならない。どういった形が商店街の活性化につながるのかということを、両者で協議しながら、一番いい方法を探っていきたいと考えているところです。","id":"exchange-011"},{"speaker":"藤原委員","kind":"意見","question":"４３の郵便局でまず予約販売して、実際に商品券をもらうのは２３の引換所となっているんですが、直接買えないのかとの意見を述べました。","respondent":"金子産業振興課長","answer":"それで、郵便局で直接の購入ができないのか。私どもも、直接商品券というものを販売できないということがありますので、こういう予約券という形にしておるものです。","id":"exchange-012"},{"speaker":"藤原委員","kind":"質問","question":"３カ月、３カ月ってすぐたっちゃうと思うし、これはむだになっちゃうわけですよね。その辺をうまく工夫をできないかなと思うんですけれども、その辺はいかがか尋ねました。","respondent":"金子産業振興課長","answer":"従来ですと、言葉は悪いですけど、通常の商品券がかなりたんすの中に眠っていたということが当然あります。回収率が上がってきているということがありますので、その意味では、期間を限定するということの意義は高いと考えているところです。","id":"exchange-013"},{"speaker":"木下委員","kind":"質問・要望","question":"期間限定という話ですけれども、今まで大体たんすに眠っていたというのがどのぐらいあるんでしょうか。正直言って、経済波及効果ですとか、いろいろあるじゃないか尋ねました。","respondent":"金子産業振興課長","answer":"私どもの説明が悪かったのかもしれませんが、通常の商品券とプレミアムの商品券の回収率はかなり違います。各商店街でさまざまなイベントを実施しておりまして、かなりの効果が出ているということは、商店街連合会の方からお聞きしています。","id":"exchange-014"},{"speaker":"木下委員","kind":"質問","question":"単純な疑問で出させていただいたんですけれども、要するにお金を払って商品券を購入していただいているわけじゃないですか。その使っていないのも期限が決まっているわけだから、その差額は、例えば販売店の方に行くのかとか、単純な疑問なんですけど。","respondent":"金子産業振興課長","answer":"これについては、商店街連合会の方に、益金として入っていくというものです。ただし、先ほど申し上げたとおり、かなり回収率が上がっていますので、あまり大きな金額ではないということは言えると思います。","id":"exchange-015"},{"speaker":"須貝委員","kind":"質問","question":"波及効果ということならば、実際に取扱店は多数あると思うんですけれども、そのうち何店舗で使われているんでしょうかね。そのうち５００軒しか使われていないのか、１００軒しか使われていないのか、その辺の数字というのは押さえてはいないんか尋ねました。","respondent":"金子産業振興課長","answer":"売り上げの率から言いますと、商店街によって、かなり偏在しているのは事実であります。ただ、個店の段階で何店舗で使われたかというような数字を持っていないので、申しわけありませんが、それは後ほどよろしくお願いしたいと思います。","id":"exchange-016"},{"speaker":"須貝委員","kind":"質問","question":"本店が大阪にあるということになりますと、お金が品川以外に流れる、他府県に流れるということもあるんじゃないかと思うんですね。区内の流通波及効果というのは、その辺でもかなり薄まるんじゃないかとちょっと疑問にも思うんですけれども、その辺はどうなんか尋ねました。","respondent":"金子産業振興課長","answer":"取り扱っていないので、そこでしか使えないということにしておりますので、大型に関してはないということは１点あります。商店街の来店者数ということが増加していくわけですから、私どもとしては、それなりの効果はあるだろうと考えています。","id":"exchange-017"},{"speaker":"中塚委員","kind":"質問","question":"販売促進経費に２００万円とあるんですけど、その内訳を説明を求めました。","respondent":"金子産業振興課長","answer":"販売促進経費の助成金２００万円ですけれども、品川区内の全体を見て、さまざまな販売促進策に使うというふうにしています。駅張りのポスターであるとか、宣伝カーというのを区内全域で巡回させるそうですので、そういった宣伝の方に使うというふうに認識しています。","id":"exchange-018"},{"speaker":"中塚委員","kind":"質問","question":"主にこの助成金の使われ方というのは、ポスターとか宣伝活動に使われているということでよろしいんか尋ねました。","respondent":"金子産業振興課長","answer":"委員ご指摘のとおり、そのように聞いているところです。","id":"exchange-019"}]},{"id":"topic-04","title":"の品川区環境情報活動センターの開設","agenda":"の品川区環境情報活動センターの開設","exchanges":[{"speaker":"武内委員","kind":"質問","question":"予約ということなんですけど、予約なしで、例えばふらっと来て見られるというようなコーナーはあるんか尋ねました。","respondent":"田中環境課長","answer":"申しわけありません、今月末納品予定なものですから、事務室のところがあります。ここで受付をして、資料等を見るとか、パソコンで環境情報等を見るとかいうようなことを、申し込んでいただければご利用できる形になっております。","id":"exchange-020"},{"speaker":"武内委員","kind":"質問","question":"防災センターと同じように、最初から予定せずに来て、環境のがあるからちょっと見てみようかなということを言えば大丈夫だということですね。これは土日祝日も予約なしで行ってもこの展示だけは見ていいということだと思うんですけど、これは職員の方が何人かおられるんか尋ねました。","respondent":"田中環境課長","answer":"土日祝日ですが、環境ＮＰＯのエコタウンしながわの事務局員が事務室に詰めておりますので、そこで受付をしていただくということになります。","id":"exchange-021"},{"speaker":"伊藤委員","kind":"質問","question":"３６５日開いているのか、開店休業みたいな、そういう状況になるような心配はないですかという思いが正直あります。それから小学校、区内のいろいろな環境団体と協働していくとか、そういうふうなことを考えているんでしょうかということを説明を求めました。","respondent":"田中環境課長","answer":"環境団体や個人の簡単な打合せ等、お互いの連携やネットワークも広がっていくと思いますので、そういう使われ方がされればいいなと考えています。","id":"exchange-022"},{"speaker":"伊藤委員","kind":"質問","question":"ですから、そういう枠の中で、品川区の責任で準備はしました。そういうところを、環境課が中心となって働きかけをしていく、そういう構想をしていかないと、非常に怖い気がするんですけど、いかがか尋ねました。","respondent":"田中環境課長","answer":"各地の産業関係の団体ですとか住民団体等に積極的に働きかけていって、環境活動の拠点として有効にご利用いただけるよう、環境課の方としても積極的に働きかけていきたいと考えています。","id":"exchange-023"},{"speaker":"伊藤委員","kind":"質問","question":"そういうふうなことを考えていくと、そこにいろいろな仕組みを入れて、ここが区民と行政の協働で環境情報が発信できる。しかも、環境課なんですからむだなくということを十分考えて、活動の拠点にしていただけますように、。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"中塚委員","kind":"質問・要望","question":"そこを教えていただきたいのと、あと、委託をするエコタウンしながわと書いてありますけれども、この１行だけじゃね。どういう契約、これだけで僕は何もわからないので、ここもちょっと教えていただけますか。","respondent":"田中環境課長","answer":"今、例示にありましたシャンプー等の販売については難しいというふうに考えています。品川の中で持続的に環境活動に取り組んでいこうということで、中核的なメンバーでＮＰＯがつくられて、正式に法人化されているという状況です。","id":"exchange-025"},{"speaker":"中塚委員","kind":"質問","question":"さっきご質問したのは、エコタウンしながわというのは何者なのかどうか。設立や、実績や、委託料や、どういう契約をされているのか説明を求めました。","respondent":"田中環境課長","answer":"理事長は、現在も環境活動推進会議の会長しております。そのほかに中核的なメンバーで、企業のＯＢの方を中心にして１０名程度でＮＰＯをつくって活動しております。","id":"exchange-026"},{"speaker":"中塚委員","kind":"質問・要望","question":"先ほど、環境活動とありましたけど、どうでしょうかね。せっかくつくった施設ですから、最後に伺いたいのは、それ自体は要綱か何かで利用規約を決めていくんか尋ねました。","respondent":"岩崎環境清掃事業部長","answer":"ＣＯ２の問題なんていったら、全然目に見えませんから、グラフだけでしか説明できないわけですよね。ある程度登録団体的な考え方で考えていかなきゃいけないとは思っているんですが、常識の範囲内で進めていくしかないのかなと思っているところです。","id":"exchange-027"},{"speaker":"木下委員","kind":"質問・要望","question":"そこら辺よくわからないので伺いたいのと、意識の啓発というか、そういうのを行っていただきたいと思うんですが。質問とお願いと、ひとつ。","respondent":"田中環境課長","answer":"小学校４０校にご協力いただきまして、ＩＳＯに親子で取り組めるような内容のチラシを、取り組んでいただいています。実際に家庭で取り組みましたというのは５００件強だったんですが、今、昨年より取り組んだご家庭が増えている状況になっています。","id":"exchange-028"},{"speaker":"木下委員","kind":"質問・要望","question":"だけど、ホームページですとそういうのも載っていませんし、議員でもわからないわけですよね。そういう形で広報に力を入れていただきたいのと、こういう情報活動センターを通じて、そういう要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"},{"speaker":"林（宏）副委員長","kind":"質問","question":"端と端に設置する嫌がらせみたいな設置の仕方というのが、どうも気になる。防災と関係あるんか尋ねました。","respondent":"田中環境課長","answer":"防災センターの活用については、特に３階部分の活用については、それを含めて３階の活用については検討されてきた経緯があります。リボンとのかねあいですが、区の庁舎の中では非常に込み合っていますので、そこしか設置できるところがなかったということでご理解いただきたい。","id":"exchange-030"},{"speaker":"林（宏）副委員長","kind":"質問","question":"環境というのはもう少し楽に、続けられるということですから、あまり大きく構えないほうがいいなと思います。あのセキュリティはどのようにするんか尋ねました。","respondent":"田中環境課長","answer":"それから、１０月の当初には間に合いませんが、エレベーター部分の手前のところも施錠できるような形にします。ロビー部分は一般の方は３階から入れますけれども、若干まだ間に合わない部分がありますが、そういう形でセキュリティを確保するように設置するです。","id":"exchange-031"},{"speaker":"林（宏）副委員長","kind":"質問","question":"これは開かないんですか。いろいろ問題になっていることが多いですから、この間もパソコンが持っていかれちゃったとか、いろいろな問題をきちんとしておいて。","respondent":"久保田防災課長","answer":"２階のしながわシアターにつきましては、今、土日は閉館しております。３階についてなんですけれども、３階のロビーを活用して、随時そういう展示をしていくということに変更はございません。","id":"exchange-032"}]},{"id":"topic-05","title":"の東京国際空港再拡張事業に係る環境影響評価準備書のあらまし","agenda":"の東京国際空港再拡張事業に係る環境影響評価準備書のあらまし","exchanges":[{"speaker":"武内委員","kind":"質問","question":"９月１７日に南大井文化センターで説明会があって、１０名ほどの方が出席されたということですが、何か、出席された方の中でどんなご意見とか、主立ったところを説明を求めました。","respondent":"田中環境課長","answer":"一応職員もそこに出て説明を受けたんですが、質疑はありませんでした。","id":"exchange-033"},{"speaker":"中塚委員","kind":"質問","question":"現状の２,７００～２,０００フィートの水平方向を高くして、３,２００フィートとかと。離着陸が多くなるから高くなると、危険じゃないんですかね。","respondent":"田中環境課長","answer":"１９ページの左下段のところに、航空機騒音の部分が出ております。当然、離着陸については、技術的に安全な形で離着陸する角度や高度をとっていると思いますので、あのような形になっています。","id":"exchange-034"},{"speaker":"林（宏）副委員長","kind":"意見","question":"それもあれなんだけど、羽田のいろいろな情報というのは、区議会の方にもできるだけ提供してほしいなと思うんですよね。きょうは環境のことなんで関係ないけど、たまたま羽田空港ということが出たのでとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-035"},{"speaker":"伊藤委員","kind":"質問","question":"上のは朝６時から午後１０時まで、それから午後１１時から午前５時までの間でそれぞれある。そのことについて、品川区の見解を知りたいので、答弁をお願いします。","respondent":"田中環境課長","answer":"これが、当初の４,０００フィートから５,０００フィートに高度を引き上げて、品川に直にかかるようなものはないようには思うんですけれども。高度が高いからほとんど影響がないということになります。","id":"exchange-036"},{"speaker":"伊藤委員","kind":"確認","question":"確認なんですけど、上空を飛ぶことは事実だけれども、高度が高いので影響がないというような意味ですか。それだけか尋ねました。","respondent":"田中環境課長","answer":"品川区の部分については、そのとおりになります。コースも外れています。","id":"exchange-037"},{"speaker":"林（宏）副委員長","kind":"質問","question":"質問をつくって先に相手先に送ると、いろいろ細かく調べてくれて、答弁も資料つきでされる。出てくる資料だとかそういうものがあれば、当日聞くだけよりもいいので、そういうものが何かあれば。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-038"},{"speaker":"木下委員","kind":"意見","question":"まだまだ川の水質というのはよくないかなと思われますので、そういう部分に利用できないかなと思うんですが、そこら辺の資料等ございましたらとの意見を述べました。","respondent":"本間委員長","answer":"そういうふうな考え方がよろしいかなと思いますので、ひとつご意見を述べていただきたいと思いますが、よろしいでしょうか。","id":"exchange-039"},{"speaker":"林（宏）副委員長","kind":"質問","question":"向こうのホームページに出ているとか、そういうものがないと。違う自治体に行って情報をいただくということですから、疑問に思っていることを事前にぶつけることは大変いいことだと思いますから、お願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-040"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/678828?Template=document&Id=2438#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2005-01-01&TermEnd=2005-12-31"}],"sourceMeta":{"pages":0,"characters":31686,"voices":122}},{"id":"h17-20050927-7","meetingId":"h17-cm09","date":"2005年9月27日","dateIso":"2005-09-27","committee":"厚生委員会","time":"午前１０時０４分～午後１時５４分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を34件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"山路委員","kind":"提案","question":"今回の一般質問で、昨年から質問、提案をさせていただいてきたんです。ですので、その辺はどういうふうに考えていらっしゃるか、ちょっとお聞かせほしいと求めました。","respondent":"谷田部健康課長","answer":"来年設置するということで準備をしていると聞いてありますし、またきゅりあんにも設置するということで、計画的に検討はしています。私どもも検討してまいりたいと同時に、今回、こういう庁舎内の設置ということに至ったです。","id":"exchange-001"},{"speaker":"山路委員","kind":"質問・要望","question":"大体、主なところは、今、ご説明がありましたけれども、地域センターとか、駅とかは、やっぱり区のほうで働きかけていただきたいと思うんです。防災訓練をずっと９月からやっていますけれども、活用されたらどうかと思うんですけれども、その辺のお考えをお聞かせほしいと求めました。","respondent":"谷田部健康課長","answer":"やはりこれも、経済的な問題と効果の問題との兼ね合いということもありますので、それは全体の中での検討とさせていただきたいと思ってあります。多分認識していますので、私どものほうとしても、この辺の話を防災課のほうに伝えるということで考えてあります。","id":"exchange-002"},{"speaker":"山路委員","kind":"意見","question":"周知といいますか、ＰＲといいますか、そういうことを含めて。もっともっと区民を、いざというときに救える体制を、そのことをお願いして終わりますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-003"},{"speaker":"飯沼委員","kind":"質問・要望","question":"不整脈の治療ということなんですが、まず入口のところで、心室細動や無脈性心室頻拍ですか、これがどういう状況なのか。とっさにどう行動するのかという判断のところで、その辺がどうなのかなと、やさしく説明を求めました。","respondent":"谷田部健康課長","answer":"それが１５分ほど、循環のサインと心臓マッサージ等々を行いまして、自分で実際につけてみるというようなこと。ですから、先ほど、委員のおっしゃっている、心室細動ですとか、無脈性心室頻拍等々の状況があれば、この器械が自動的にやってくれるというものです。","id":"exchange-004"},{"speaker":"飯沼委員","kind":"質問","question":"まだ新しいところなので、そんなに設置をされていないということなんですけれども、今、愛知万博での話がありましたけれども、実際に、今、どのぐらい使われ始めていて、効果のほどがどうなのかなというところは、幾つか出ているんか尋ねました。","respondent":"谷田部健康課長","answer":"ですから、７８０万人に１回と。それ以上の状況というのは、私ども、つかんでございません。","id":"exchange-005"},{"speaker":"飯沼委員","kind":"質問・要望","question":"まず存在をしっかりと示してほしいのと、これからつくっていっていただきたいし、私たちもぜひ体験をしてみたいなと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"須藤委員","kind":"質問","question":"マスコミでこうしているから、どうどんつくっていくということで、果たしていいのかなと。地震のときの予防というものと一緒ですから、どうか、聞かせてください。","respondent":"谷田部健康課長","answer":"庁舎内で倒れられますと、５階の職員厚生関係の保健士ですとか、健康課におります保健士が対応することになっています。私ども区として、こういう普及に努めるという立場ですから、機会あるごとに、こういう話はしていきたいと思ってあります。","id":"exchange-007"},{"speaker":"須藤委員","kind":"意見","question":"いいものなんですけれども、今言ったように、コストの全体的なバランスを見ながら。そこへ行くまでの時間内に対応できるかどうかということですので、民間の人たち、その辺の配慮をお願いしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-008"},{"speaker":"飯沼委員","kind":"質問・要望","question":"開設、ほんとうに嬉しいことです、ありがとうございました。ピアカウンセリングと、セルフヘルプグループと書いてあるので、ちょっとこの辺の説明をしていただきたいんです。","respondent":"西島障害者福祉課長","answer":"それから、セルフヘルプサービスですが、これはいわゆる自主グループというものができてきた場合に、この活動を支援してまいりたい。自主グループをつくっていきたいと考えているところです。","id":"exchange-009"},{"speaker":"飯沼委員","kind":"質問","question":"この間、登録制とちらっと伺ったので、これは枠が決まっているのか、どうか。ちょっとその辺を説明を求めました。","respondent":"西島障害者福祉課長","answer":"一度、来ていただいて、ご相談をしてということになろうかと思います。どうなのかというようなことも含めて、一応、登録という形をとらさせていただいたものです。","id":"exchange-010"},{"speaker":"飯沼委員","kind":"質問","question":"今までは、精神障害者の相談を受けたときは、まず保健所にお願いをしていたんですけれども、そういった面では、例えば、親御さんとか家族に付き添っていただいて、直接伺うような状況でよろしいのか尋ねました。","respondent":"西島障害者福祉課長","answer":"そういうことも考えられると思いますけれども、精神障害者の場合は、どうしても医療と切り離せない部分が大きな要素になります。気持ちが落ち着いた方に来ていただいて、ここで、地域で活動できるような態勢をとっていきたいと考えているところです。","id":"exchange-011"},{"speaker":"飯沼委員","kind":"質問","question":"ということは、既に保健所でお世話をいただいている方は、適当と思われる方は紹介をしていただけるような状況なんですか、ちょっとその辺。","respondent":"西島障害者福祉課長","answer":"現在、考えている当面の人数ですが、現在、ホームヘルプサービスを受けている方が３４人ほどいらっしゃいます。今後、保健所と連携をとりながら、徐々にそういう方が増えてくるんだろうと考えているところです。","id":"exchange-012"},{"speaker":"山路委員","kind":"質問・要望","question":"１０年ぐらい前からいろいろ言わせていただいていた内容も振り返りながら、就労支援相談というのがありますが、一つお聞かせいただきたい。ここで地域との交流とか、そういうことも考えていらっしゃるのか、３点聞かせてほしいと求めました。","respondent":"西島障害者福祉課長","answer":"その支援の中には、ハローワークと連携をしながら、就労支援についても結びつけていきたいと考えているところです。第３工房でやっておりますジャムの作成、ぞうきんとかアクリルで編んだたわし、ああいうものをここで実施すると考えています。","id":"exchange-013"},{"speaker":"山路委員","kind":"質問・要望","question":"拡大していくに当たっても、非常に楽しみじゃかないかと思いますが、ここは大事にしてほしいと求めました。２点について、わかる範囲で説明してほしいと求めました。","respondent":"西島障害者福祉課長","answer":"常に工夫をして進めていかなければ、障害者がつくったからということでは、なかなか売れない状況です。さまざまなイベントに出展をして、販路の拡大に努めているところですけれども、さらにその辺は、工夫が必要かなということで考えているところです。","id":"exchange-014"},{"speaker":"川西委員","kind":"質問","question":"一つだけ質問をしておきたいと思います。ですから、クリーニングは、そういうシステムはどうなっておりますか。","respondent":"西島障害者福祉課長","answer":"そういう形ではございませんので、特にハローワークを通さなくても、通所することは可能であろうと考えています。第３工房の所長がクリーニングの資格を持ってありますので、その辺では、十分に可能だろうと考えています。","id":"exchange-015"},{"speaker":"川西委員","kind":"確認","question":"そうしますと、確認しておきたいのは、今、福栄会でもクリーニングがありますよね。それから、品福があって、ここが同じような内容で運営されていくという確認でよろしいんか尋ねました。","respondent":"西島障害者福祉課長","answer":"そのようにご理解いただいて大丈夫だと思います。","id":"exchange-016"},{"speaker":"須藤委員","kind":"質問・要望","question":"その辺を踏まえながら、指定管理者に持っていくのかなという気がするんですけれども、その辺のところを教えてほしいと求めました。そのあたりを説明を求めました。","respondent":"西島障害者福祉課長","answer":"かもめ第１から第３工房は福栄会の事業ですので、あそこの場所をお貸しして、それを福栄会として事業を実施するです。精神障害者地域生活支援センターは、あの場所を使って事業を実施するですので、指定管理者にはならないと考えているところです。","id":"exchange-017"},{"speaker":"須藤委員","kind":"質問・要望","question":"それから、今お話を伺うと、こういった支援センターと医療との関係が非常に大切じゃないかなと。医療行為とうまくマッチすることが、患者さんの復帰につながってくるんだろうと思うんですが、その辺の連携はどういうふうになるんか尋ねました。","respondent":"鶴見品川区保健所保健サービス課長、西島障害者福祉課長","answer":"精神障害者の患者さんの人数につきましては、年々増加をしております。これは２年に１回の更新となっておりますけれども、平成１６年度が１,３８６名という形で、増加しているということがわかる状況となっております。先ほどのケアマネジメントの中でアセスメントを行いまして、意見なりもつけて、その中でプランをつくっていくということになります。","id":"exchange-018"}]},{"id":"topic-02","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"川西委員","kind":"質問","question":"それから、一時保育というのがありますよね、これも在宅支援で、在宅支援やオアシスに類するものはほかにはないのか、どうかということ。費用を、これだけ別に出してみるということはできないんか尋ねました。","respondent":"小林保育課長","answer":"それ以外に在宅支援と申しますと、お子さん、子育て支援の一助というふうに考えております。在宅子育て支援トータルでどのぐらいのつかみなのかというのは、保育園の運営経費の中に埋没していて、なかなか分離が困難という状況があります。","id":"exchange-019"},{"speaker":"川西委員","kind":"質問・要望","question":"最近拡大してきて、幼稚園に通っている子どもが、夏休みは約３５日とか、４０日近くお休みですよね。ですから、さらに充実をしていただきたいと感じております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"本多委員","kind":"質問・要望","question":"私立保育園が６２６人で、０歳児の割合が区立保育園のほうが少ないのかなと、園児１人当たり同じ金額なのかなと。やっぱり、これは０歳児の割合ということだと思うんですけれども、その辺、ちょっとお聞かせいただきたいんです。","respondent":"小林保育課長","answer":"人件費のうち、一部いわゆる派遣対応している部分については、物件費のほうに事業費として処理されている部分があります。確かに区立保育園の場合、０歳、１歳というような乳児への配置を若干手厚くしている傾向にはあります。","id":"exchange-021"},{"speaker":"本多委員","kind":"質問・要望","question":"経費が１９％入っているということなんですけれども、それほど開きがないと、ちょっとイメージしているんです。ハード的な部分を入れて、見方がこう変わったとか、その辺をもう少し教えていただきたいんですけれども。","respondent":"小林保育課長","answer":"単純に５で経費総額を割っておりますので、幼稚園のほうは半分に、ないしは保育園のほうを倍に見立てて比べていただくのが正しいのかなと。５時間は本来の事業に使って、それ以外の５時間については、それぞれの実行時間で割るほうが正しい費用把握になるかなと考えたところです。","id":"exchange-022"},{"speaker":"川西委員","kind":"質問","question":"今、本多委員への説明のときに、派遣人件費が公立保育園のほうに入っていない数字で、比較というのはできるんか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"飯沼委員","kind":"質問・要望","question":"オアシスのところの派遣職員のことなんですけれども、現在の派遣の人数、全体と、内訳をちょっと教えていただきたい。本来だったら人件費のところではないかなと思うんですが、それが事業費に入っているというあたりで、そこを説明を求めました。","respondent":"小林保育課長","answer":"それから、それ以外の特別支援のところで３８人、平成１６年度では、マックスですけれども４８人派遣が入っております。年間を通して４８人ということではなくて、特別な障害児対応だとか、手元資料はございません。","id":"exchange-024"},{"speaker":"飯沼委員","kind":"意見","question":"分類が難しいというのは、よくわかりました。すみませんが、今の特別支援というのは、どう理解したらいいのかとの意見を述べました。","respondent":"小林保育課長","answer":"例えば０歳なら１対３とか、所定の保育士配置で対応すべきところ、保育の状況に応じて加算をしている。非常勤等の対応、そういった臨時的な部分の対応に、派遣職員を充当しているケースがあるということでご理解いただきたいと思います。","id":"exchange-025"},{"speaker":"飯沼委員","kind":"質問・要望","question":"Ａ４版の横の資料なんですが、ちょっとお伺いしたいんですけれども、公立幼稚園と私立幼稚園の事業費の差とか、人件費の違いが、保育園と比べると幼稚園のほうが大きいんですが、この辺をどういうふうにとらえたらいいのか、わかる範囲で、中身的な違いを教えていただきたい。","respondent":"小林保育課長","answer":"これは、ちょっと断言するのは乱暴かと思いますが、端的に言って、幼稚園教諭、公立と私立との給与体系の差、年齢等の差が大きいものと思います。１人当たりに割り返していますから、区立の幼稚園は、そういうものが少ないということをあらわしているものではないと考えています。","id":"exchange-026"},{"speaker":"飯沼委員","kind":"質問・要望","question":"事業の中身でどうなのか、職員の配置でどうなのかというところが、しているんです。違いって見えてこないと思うのと、私は特に、幼稚園なんかの違いも明らかにしていただけるような資料をつくっていただきたいと思っています。","respondent":"高橋幼保一元化担当課長、小林保育課長","answer":"これは学校法人の基礎調査をもとに出しているものであって、私立から運営状況等を上げてもらうということは、なかなか困難なことです。公立保育園… 各形態、ないしは各園の実情に応じて異なってきますので、責任を持った数字がお出しできない。もしくは各施設ごとですとか、それで全体の像をご理解いただくのは、各委員のご認識に頼らざるを得ないというのが現状です。","id":"exchange-027"},{"speaker":"飯沼委員","kind":"質問","question":"特にどういう事業にどのぐらい人員が配置されているのかとか、そういう部分がなかなか見えないですよね。その辺のところでは、どの事業にどのぐらいの費用とか、人員が配置されているのかなというのは出ないんか尋ねました。","respondent":"小沼児童保健事業部長","answer":"１、２歳ですから、あるいは幼稚園と保育園での比較はできないというような状況になってあります。１０時間とか、１１時間送っているということで、ひとつご理解いただければと思います。","id":"exchange-028"},{"speaker":"飯沼委員","kind":"提案","question":"そういう見方をしたいなと思ったので、お願いしたんですが、無理だったらいた仕方ないかなと思います。そういう意味あいで、提案してみたんですけれども、その辺はご理解ほしいと求めました。","respondent":"小沼児童保健事業部長","answer":"３０人に１人、あるいは３５人に１人という違いはありますけれども、それに沿ってやっている。一般的な統計資料としての重みというのは、率直に申し上げまして、いかがなものかなということで申し上げているです。","id":"exchange-029"},{"speaker":"飯沼委員","kind":"意見","question":"１.５７ショック以来、プラス１とか、子育て支援の大きな流れがありますよね。その辺での国の予算、都と区の予算の流れあたりも、子育て支援で、今、どういう状況にあるのかということを理解する上で、資料をもらいたいですとの意見を述べました。","respondent":"小沼児童保健事業部長","answer":"むしろそれは議会調査のほうでするべきものかと思います。やっぱり議会調査担当、議会のスタッフの方々でおやりになるほうが、より正確なものができ上がるのではないかというふうに考えてあります。","id":"exchange-030"},{"speaker":"飯沼委員","kind":"質問","question":"だから、そういった面では、所管の担当で携わっている部分で出せるんだと思います。難しいか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"例えばＤの２１階層が、この１年後には、１.９７というのは１.０倍になっちゃうんですよね。０歳児の保育料というのは、２歳になったらがくっと半分以下に下がっちゃいますので、どうか尋ねました。","respondent":"谷田部健康課長","answer":"平成１６年度決算ベースで、０歳から５歳まで預ければ、さまざま難しい問題があります。９月何日の時点ですぱっと切ったときに、子育てをしている１０年間の年限を、ご理解をいただきたいと思います。","id":"exchange-032"}]},{"id":"topic-03","title":"行政視察","agenda":"行政視察","exchanges":[{"speaker":"鈴木（ひ）副委員長","kind":"意見","question":"どういうふうな理念でやっているかというのがたくさん出てくるんですけれども、そういう姿勢がよくわかっていただけるかなと思うんです。そういうところにも、その実践については書かれていましたので、ぜひ行ってみたいということで希望させていただいたところですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-033"},{"speaker":"石田委員長","kind":"質問","question":"本多委員は、いいですか、どこでも。本多委員も、今、入れておいていただければ、正副委員長が後で調整しやすいですから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/948006?Template=document&Id=3124#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2005-01-01&TermEnd=2005-12-31"}],"sourceMeta":{"pages":0,"characters":43191,"voices":104}},{"id":"h17-20050927-8","meetingId":"h17-cm09","date":"2005年9月27日","dateIso":"2005-09-27","committee":"建設委員会","time":"午前１０時０４分～午後 ２時０７分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を65件整理しています。","topics":[{"id":"topic-01","title":"の「目黒川右岸排水施設整備工事その７」","agenda":"の「目黒川右岸排水施設整備工事その７」","exchanges":[{"speaker":"井上委員","kind":"質問・要望","question":"このその７工事に対しての地域の方への説明の周知方法と日程などが決まっていれば教えていただきたいことと、その１からその６まであったかと思うんですが、資料として残っていればお伺いしたいんですが。","respondent":"原田下水道河川課長","answer":"その７工事の周知についてですが、１０月の末からの工事を予定しているということから、１０月の中旬には住民説明会を開きたいと考えております。","id":"exchange-001"},{"speaker":"井上委員","kind":"質問","question":"そういった場合、主に道路の影響かと思うので、住民の方たちには直接関係のあるところもあります。あるいは町会の回覧だけで済まされているとか、その辺の周知方法というのは、通常はどのような形で行っているのか尋ねました。","respondent":"原田下水道河川課長","answer":"周知の方法につきましては、町会での回覧と、それから町会の掲示板を利用しております。","id":"exchange-002"}]},{"id":"topic-02","title":"の「目黒川右岸低地部排水施設整備工事」の着手予定","agenda":"の「目黒川右岸低地部排水施設整備工事」の着手予定","exchanges":[{"speaker":"井上委員","kind":"提案","question":"きちんと住民の説明をしてほしいということを提案をしていますけれども、あるいはされているのだったら、どのような意見が出ているのかというところを説明を求めました。","respondent":"原田下水道河川課長","answer":"住民説明会は既に６月に一度実施しておりまして、これについては今後の説明会の方でしっかり周知、あるいは要望を聞きながら工事を進めていきたいと考えております。","id":"exchange-003"},{"speaker":"井上委員","kind":"質問","question":"住民の方たちだけの説明会なのか、保育園に通わせている方たちへの説明会を行うのか、あるいは園長先生がそのことを保育園で報告するという形を考えているのか、実際そういう、今回、契約も始まるかと思うんですが、業者が決まった段階でどういうふうに考えられているのか尋ねました。","respondent":"原田下水道河川課長","answer":"毎回住民説明会を実施する際に、説明の仕方等もそこで要望があれば聞きながらやっていきたいと思いますので、そういう中で今後検討していきたいと思います。","id":"exchange-004"},{"speaker":"井上委員","kind":"質問・要望","question":"ここの保育園は、あそこを広場というか、遊ぶ場所として使われているかと思うので、もしそういう要望とか意見があれば、誠心誠意対応していただきたいということを要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"}]},{"id":"topic-03","title":"の補助２６号線（品川区平塚橋交差点付近）の事業認可の取得","agenda":"の補助２６号線（品川区平塚橋交差点付近）の事業認可の取得","exchanges":[{"speaker":"菊地委員","kind":"意見","question":"道路事業の場合、強制的に土地をあけたりすることはあるのかなという気がするんですけれども、その辺を少し詳しく権利者との関係をお願いしますとの意見を述べました。","respondent":"阿部都市計画課長","answer":"具体的には、現在は駐車場として使われてございまして、建物が直接かかわっているというところではございません。この部分を第二建設事務所の方で、駐車場として使われているマンション、あるいは駐輪場として使われている部分を買収しようという計画です。","id":"exchange-006"},{"speaker":"菊地委員","kind":"質問","question":"そうすると、何階建てのマンションなのかわかりませんけれども、容積率とか、そういうものとかかわってくるのかなと思うんですけれども、ちょっとその辺は緩和措置みたいなものはあるのか尋ねました。","respondent":"片田建築課長、上野都市開発課長","answer":"買収するときは、やはり一般開発になりますので、容積率等々を含めて勘案した中で買収されるというようなことです。 今、勘案するという発言がありましたけれども、結果をしてそういう状況が生じるかもしれません。既存の建物、既存不適格ということはあり得るかと思います。","id":"exchange-007"},{"speaker":"菊地委員","kind":"質問・要望","question":"必要な道路事業ということですから、その辺は住民の皆さんとのしっかりした話し合いと不安を取り除くというところで、区が直接やるわけではないですからあれですけれども、やっていただきたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"}]},{"id":"topic-04","title":"の中央環状品川線の事業認可の取得","agenda":"の中央環状品川線の事業認可の取得","exchanges":[{"speaker":"菊地委員","kind":"質問","question":"ということは、東京都の街路事業ですから、都道という設定ではないということなんですか。南品川とか、具体的には、この発進立坑というのは一体どこになるのかということをとりあえず教えてほしいと求めました。","respondent":"阿部都市計画課長","answer":"そのための事業認可を受けるです。２点目の発進立坑のことですけれども、あるいはもう１件、多分そこがなると聞いております。","id":"exchange-009"},{"speaker":"菊地委員","kind":"質問","question":"全体の９.４ｋｍのうちの４.２ｋｍを先にやるということは。その辺もお聞きしたいのと、この辺は今どうなっているのか、その辺もお聞かせ願えますか。","respondent":"阿部都市計画課長","answer":"２点目の脱硝装置の件ですけれども、これは区としては換気塔に最新の脱硝装置をつけてほしいという要望は出しております。現在のところ環境影響評価の中では必要ないというふうになっていますけれども、それはその時点で周りの環境を見ながら検討していくです。","id":"exchange-010"},{"speaker":"菊地委員","kind":"質問・要望","question":"その辺をもう少しはっきりさせていただきたい。押していく部分というような、区民の健康を守っていく上で極めて必要なのではないかなというふうに思うんですけれども、その辺ではどうか尋ねました。","respondent":"阿部都市計画課長","answer":"１つ、私が申し上げましたのは、区としては最新の脱硝装置をつけることを当然求めております。ただ、あるいはディーゼル車の規制、あるいは技術革新を含めて検討していくということが東京都の見解だということを申し上げたということです。","id":"exchange-011"},{"speaker":"菊地委員","kind":"意見","question":"１０年後、脱硝装置としてきちんとつけますよというのが入っていない限りは、予算というのは本来成り立たないような気がするんですね。４,０００億円が最終的に別に膨れ上がってもいいんだという話であれば別なんでしょうけれども、でも、最後にそこだけお願いしますとの意見を述べました。","respondent":"阿部都市計画課長","answer":"事業の後半の方に換気所というのは設置するわけです。東京都の考えですけれども、東京都の考えとしては、必要であればつけるというような検討をしているです。","id":"exchange-012"},{"speaker":"土井委員","kind":"質問","question":"お伺いをするならば、何百分の１の地図のところに鉛筆でかいた程度のものなんだよという場合と、どの時点なのかということですよね。今回の場合は、どの時点なんか尋ねました。","respondent":"阿部都市計画課長","answer":"ですから、東京都としては、都市計画決定をしてから１年以上置くということはできない。ですから、その後、詳細な設計をして工事になれば、当然その中で工事説明会を地元の方にしていくということが必要になってくると思っています。","id":"exchange-013"},{"speaker":"土井委員","kind":"質問","question":"したがって、その用地がというときには２つあるんですよね。どういくかわからないけれども、１年間以上たってしまって何もやらないわけにいかないからということでアドバルーンを上げたのか、どっちなんか尋ねました。","respondent":"阿部都市計画課長","answer":"換気所の件ですけれども、隣接の方には説明会をして測量しています。もうすぐ着手するということでは、とりあえずということではなくて、急いでやらなければいけない事業というふうに認識しているということです。","id":"exchange-014"},{"speaker":"井上委員","kind":"質問","question":"最初に質問なんですが、この街路事業と有料道路事業というのが、何がどう違うんか尋ねました。","respondent":"阿部都市計画課長","answer":"もう１つは、民営化後にやりますと、有料道路事業にまで返済が５０年の期間だったんですけれども、それが短縮されるということが１つあります。そうすると、東京都が街路事業として一緒にやっていくというふうなことでスムーズに進めたいということがあります。","id":"exchange-015"},{"speaker":"井上委員","kind":"確認","question":"もう一度確認をさせていただいたほうがいいのかなと思うんですけれども、詳しくはまた個人的に伺ったほうがいいのかなと思っています。できたときにどういう変化があったのかということが明らかにならないわけですから、そのことについて区はどのように考えているのか尋ねました。","respondent":"阿部都市計画課長","answer":"影響評価の中でも事後評価は義務づけられてありますので、その中で事業主体が評価をしていくというふうに考えてございまして、区として独自にそれとは別にやるというふうには現在考えてございません。","id":"exchange-016"},{"speaker":"井上委員","kind":"質問","question":"そういうレベルの問題ではなくて、ここのところでは道路ができることで、西五反田の窪地であるところの換気塔で心配な人たちがいる。品川区としてそういう対応をした上で、事業主がどうとかではなくて、区としてそういう対応をする姿勢が必要かと思うんですがいかがか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"井上委員","kind":"質問・要望","question":"表に立って住民の説明会何かを受けたのはまちづくり事業部であるわけですから、そういう要望もきちんと区民の方たちから出ているので、要望でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"堺委員","kind":"質問・要望","question":"品川区の区民要望というんですか、そういったものを区民の皆さんにかわって区の都市計画課の方が東京都の方に物を申すということが可能なのかどうか。それをちょっと確認します。","respondent":"阿部都市計画課長","answer":"区民の方に十分説明すること、あるいは換気所には最新脱硝装置をつけること等の要望、意見を申し上げております。委員おっしゃったように八潮のところに、３カ所あります。","id":"exchange-019"},{"speaker":"堺委員","kind":"質問","question":"先ほど換気所の用地を取得して、東京都としては合併前に急いで着手しなければならん、そんな換気所に関連したご答弁の中でお話があったやに思うんですが、その辺はそういう理解でいいんか尋ねました。","respondent":"阿部都市計画課長","answer":"今回は、中目黒換気所、目黒区に設置する換気所です。中目黒の換気所の用地を買収する、そのための事業認可をとるという、そういうことです。","id":"exchange-020"},{"speaker":"堺委員","kind":"質問","question":"「全体９.４ｋｍのうち品川区西五反田から目黒区青葉台までの区間４.２ｋｍの事業に着手する」というふうになっていますが、中目黒の方は入っているけれども、今度こっちは入っていないということか尋ねました。","respondent":"阿部都市計画課長","answer":"今回は、中目黒の部分は都道の外に近接してつくりますので、ですから、その部分は東京都の方で用地買収しなければいけないです。今回、ここをすぐ整備をするということではなくて、あくまでも中目黒の換気所の用地を取得するための事業認可を受けたというふうに聞いています。","id":"exchange-021"},{"speaker":"堺委員","kind":"質問・要望","question":"周りの環境を見てどうのこうの、南品川、八潮についてはないんですか。改めて、さっき申し上げた品川区内のところは用地を買収する必要はないのか、ちょっとその辺をもう一回教えていただきたい。","respondent":"阿部都市計画課長","answer":"首都高速新宿線を建設中ですけれども、そこの換気所についても、当初は脱硝装置をつける予定はなかったです。環境がそれほど悪化しない、脱硝装置の必要性が出てくるのではないかというふうに東京都が検討しているというふうに申し上げております。","id":"exchange-022"},{"speaker":"堺委員","kind":"質問・要望","question":"たしか今の国土交通大臣に見解を求めて、八潮の近隣の方々の現時点での住民の意向というんですか、それは何か把握されておられるんですか。参考までに教えていただきたい。","respondent":"阿部都市計画課長","answer":"事実、連絡会の方々と先ほど申し上げた新宿線の見学会もやられているというように聞いてあります。もう１つは、予定地のことにつきましては、近隣の方々に対して用地の測量を行うということで説明会を開いているというように聞いております。","id":"exchange-023"},{"speaker":"堺委員","kind":"質問・要望","question":"そうすると、この辺については、いつごろどういう形になってくるんですか。その事業認可を取得する段階で、南品川の換気所に必要な用地買収を進めていく、そういう流れになっているんか尋ねました。","respondent":"阿部都市計画課長","answer":"１点目の事業認可の件ですけれども、新しい公団が民営化した後の会社と東京都の方で再度全線について事業認可を取り直すというふうに聞いてあります。","id":"exchange-024"},{"speaker":"土井委員","kind":"意見","question":"そこら辺はやっぱりよほどうまく説明をしていただかないと、「着手」と、こういう言葉が出てくると。だから、ぜひそこら辺を誤解を与えないような説明等をお願いをしておきたいとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-025"}]},{"id":"topic-05","title":"の東京湾第７次改訂港湾計画中間報告","agenda":"の東京湾第７次改訂港湾計画中間報告","exchanges":[{"speaker":"井上委員","kind":"質問・要望","question":"これは都の計画ということで、こういう計画の中に策定をする、改訂をするときに区がどの程度かかわってこの計画ができているのか。今、最後の方で、品川区として特にここにこういったところに出しているんだというようなことがあれば教えてほしいと求めました。","respondent":"阿部都市計画課長","answer":"今回のものにつきましては、ここの中央の図面にありますけれども、この中の大井コンテナふ頭というものがあります。大井ふ頭その１という、これについては、ふ頭機能を充実するための施設にしていくというような考え方でここを新設です。","id":"exchange-026"},{"speaker":"土井委員","kind":"質問・要望","question":"さあ、そこでどうするんだというときに、品川区のここの大井ふ頭はどうするのでしょうか。聞いてもしようがないから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"}]},{"id":"topic-06","title":"の小関橋架替整備工事","agenda":"の小関橋架替整備工事","exchanges":[{"speaker":"井上委員","kind":"質問","question":"これからの計画かと思うんですが、大体のスケジュールということで、ここはきのうの説明だと、すべて橋を壊して仮設の歩道をつくって工事をされるということだったんですが、基本設計とか、大体のスケジュールとかは決められているのであれば説明を求めました。","respondent":"上野都市開発課長","answer":"基本設計は既に過年度、実施設計ともども終わってございまして、この委託に着手するです。その時期等はまだ今のところ予定は具体的に明らかになってございませんけれども、その入札手続など、一定の期間を要するものと思われます。","id":"exchange-028"},{"speaker":"井上委員","kind":"質問・要望","question":"平成１８年度の後半からだとか、平成１８年度初めとか、区民の方がイメージするという意味での予定というのはどうなんでしょうか。大体私たちが考える、地域の方たちが思うのにどういうスケジュールなのかなというところを示していただきたいというぐらいのことなんですけれども。","respondent":"上野都市開発課長","answer":"先ほど申し上げましたように、その辺の具体的スケジュールについてはまだ未定です。","id":"exchange-029"},{"speaker":"井上委員","kind":"意見","question":"この３ページの図で、２０年にこの橋ができた状態のときに、どのように連動しているのかという大枠のところが示されればお願いしますとの意見を述べました。","respondent":"上野都市開発課長","answer":"この小関橋の架替工事が平成２０年３月に完了予定ですので、予定どおり進みましたら、この工事架替後に再開発事業の方に着手していくという段取りです。","id":"exchange-030"},{"speaker":"井上委員","kind":"質問","question":"こちらの橋はでき上がったけれども、ここの道路を向こうに渡れないとか、橋がせっかく完成したのに向こうが進まないという状況になるのでしょうか。ここが工事をするということは通行どめになることもあり得るということか尋ねました。","respondent":"上野都市開発課長","answer":"この今回の架替工事は、この架替工事を契機といたしまして、これを契機に北品川五丁目第１地区の市街地再開発事業を促進するです。具体的には、北品川五丁目第１地区の工事のための車両などがここを使うことになりますけれども、交通規制のあり方について検討していく考えです。","id":"exchange-031"},{"speaker":"林（和）委員","kind":"質問","question":"１つお聞きしますけれども、これはたしか１８年ぐらい前だったと思うんですけれども、１８年といいますと新しい橋ですよね。１８年前にこういうふうな形になるというか、今、その当時はこういうことがわからなかったんですかね。","respondent":"上野都市開発課長","answer":"小関歩道橋は昭和６２年に整備してございまして、これは手前の大崎ニューシティの再開発事業にあわせてつくったものです。当時といたしましては、このニューシティに伴って対岸に渡る歩行者の利便性を確保するための歩道橋を設置するという目的で当時整備したものです。","id":"exchange-032"},{"speaker":"林（和）委員","kind":"質問","question":"とにかくまだ１８年しかたっていないというと新しい橋でもありますので、やはりそういうふうに計画を立てていただかなければと思います。もっと先を見ながら計画をとらえていないと、こういうむだな形が多いわけですから、ひとつ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"},{"speaker":"菊地委員","kind":"質問・要望","question":"１つだけ教えていただきたいんですけれども、この橋の架替えのための事業費なんですけれども、ちょっと総務委員会ではないので細かい数字というよりも、どういう形でお金が出てくるのか、そこだけ教えていただけますか。","respondent":"上野都市開発課長","answer":"国費を投入する予定ですけれども、基本的には地元の北品川五丁目第１地区の事業者による負担ということで、事業者の方から地元の負担金として区の方に納入される予定となっています。","id":"exchange-034"},{"speaker":"菊地委員","kind":"質問","question":"当初は全額国の事業として架替えが行われるんですか。そこをもう少しお願いします。","respondent":"上野都市開発課長","answer":"平成１８年度、平成１９年度、各年度国費がそれぞれ入ってくる予定です。組合が設立されて以降、事業者から入ってきますから、そういう面では先行的に区が一時立て替え払いのような形で支払う形になります。","id":"exchange-035"},{"speaker":"堺委員","kind":"質問","question":"私の見方が悪かったらご勘弁してほしいんですが、車道が４.５と４.５で、いわゆる２車線ですね。ところが、今申し上げた橋を渡って品川の方に行くと、従来と同じような細いままで、これは１車線なんか尋ねました。","respondent":"上野都市開発課長","answer":"２車線、片側通行、そういったものの規制のあり方については協議する予定になってあります。物理的には今は双方向の通行は可能となっています。","id":"exchange-036"},{"speaker":"堺委員","kind":"質問","question":"用地買収して拡幅することはできないのか、考えていないのか、その辺はどうなんでしょうか。この辺はいかがか尋ねました。","respondent":"上野都市開発課長","answer":"右側の拡幅予定のところは、予定区域の中に入ってございまして、この部分につきましての拡幅は再開発事業の事業の中で広げる予定になります。ですから、先ほどの平成２０年度以降、再開発事業に着手されますけれども、その事業の中で広げていく予定です。","id":"exchange-037"},{"speaker":"土井委員","kind":"質問・要望","question":"だから、突き当たってしまって行けないような道路になってしまっているんじゃないのという話がここでさえ起こるんですから、そういうふうに明快に。要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-038"}]},{"id":"topic-07","title":"の大崎駅西口駅前交通広場・地下駐輪場整備工事","agenda":"の大崎駅西口駅前交通広場・地下駐輪場整備工事","exchanges":[{"speaker":"井上委員","kind":"質問","question":"駐輪場の台数なんですけれども、大崎には第１、第２、第３と駐輪場があったかと思うんですが、これができることによって、その後はどういうふうになるのか尋ねました。","respondent":"上野都市開発課長","answer":"第２、それから第３駐車場の３つの駐車場の設置台数、約６００台あれば足りるであろうという見込みを立てまして。ただ１点、バイクだけはこの中にはつくりませんので、引き続きバイクにつきましては、西口第３地区の駐輪場の場所を使う予定です。","id":"exchange-039"},{"speaker":"井上委員","kind":"質問","question":"第１、第２をなくしてここになって、第３はそのまま残るということなので、第１、第３というのは、前は何台でしたか尋ねました。","respondent":"上野都市開発課長","answer":"西口第１、これは明電舎の北側の路上に設置してございましたけれども、台数としては２０６台分が設置されてございました。それから西口第２地区といたしまして、明電舎とソニーの間の路上に設置してあった分につきましては、２２０台分がスペースとしてはございました。","id":"exchange-040"},{"speaker":"井上委員","kind":"質問","question":"６００台ということは、なおかつ第３もあるので、そういうその先のことはどのように方針が出ているのか尋ねました。","respondent":"上野都市開発課長","answer":"まだ定まってございませんで、今後、関係機関とも協議しながら検討して定めていく予定です。今のところはまだ具体的な料金等は未定です。","id":"exchange-041"},{"speaker":"井上委員","kind":"質問","question":"これは基本的には品川区がつくっている有料駐輪場と考えるのか、管理の人たちともという話ですので、そこのところは、もし品川区として来るのであれば、品川シーサイドの方の駐輪場とか、同じになるのではないかと思うんですけれども、そこは全然考え方を別にして設定をしていくということか尋ねました。","respondent":"岩田まちづくり事業部次長","answer":"ただ、駐輪場につきましても、今後引き続き指定管理者制度の導入を図ることを今一方で検討しております。非常に鋭意検討中ですので、どういう方法を採用するか現在検討中ということで、はっきりとしたお答えができないということでご勘弁を願います。","id":"exchange-042"},{"speaker":"井上委員","kind":"質問・要望","question":"駅が離れていたり、そこはたくさんの方の利用者の声というものをやっぱり聞き取ってからの検討にしていただきたいということを要望しておきます。この３ページの図面でよくわからないんですが、どういうふうな入りになって、出になるのか尋ねました。","respondent":"上野都市開発課長","answer":"２ページと３ページの平面図をそれぞれ対応しながらごらんいただきたいと思いますが、通常、スロープがついてありますので。図の中にはかいてございませんけれども、２ページの図の右下の方に、その右下の方に明電舎の敷地内に明電舎の建物の中でエレベーターが設置されます。","id":"exchange-043"},{"speaker":"井上委員","kind":"質問","question":"今の説明だと、斜面付階段ということで、エレベーターとおっしゃいましたけれども、そのエレベーターは自転車用に使えるということか尋ねました。","respondent":"上野都市開発課長","answer":"自転車の方もご利用できます。","id":"exchange-044"},{"speaker":"井上委員","kind":"質問","question":"両方で、歩行者もできる。ということは、自転車の方たちは、１カ所しか出入り口がないということか尋ねました。","respondent":"上野都市開発課長","answer":"スロープがついているものは、この左側の階段だけ、１カ所になります。","id":"exchange-045"},{"speaker":"井上委員","kind":"質問","question":"スロープがついていないのが右側にあるということですか、今の説明だと。右側にはないんか尋ねました。","respondent":"上野都市開発課長","answer":"２ページの図の右側にある「地下駐輪場出入り口階段」、この階段につきましては歩行者の方々だけが使えるということになります。自転車はここではスロープがついていませんので、ご不便になるかと思います。","id":"exchange-046"},{"speaker":"井上委員","kind":"意見","question":"そうすると、ここはすべて有料駐車場で一般の一時置き場というか、契約する有料駐車場と、前に大崎のときにはその都度とめられるというスペースがあったんですけれども、この中の仕組みは、そういうふうにはなりますかとの意見を述べました。","respondent":"上野都市開発課長","answer":"今のところ、当日利用の方と定期利用の方、両方の方に対応できるように整備する予定です。具体的な配置等については、今、検討中です。","id":"exchange-047"},{"speaker":"井上委員","kind":"質問・要望","question":"すごく要望があるのは、第３駐輪場では遠かったりするので、ここでは可能性としてはできないのか尋ねました。","respondent":"上野都市開発課長","answer":"バイクの利用者の方につきましては、将来、ソニー地区のほうに交通広場を拡張して整備いたしますので、そちらが整備された後に、当面、第３駐輪場をご利用いただいたものがそちらの方に、ソニー地区の交通広場の方に移設されるという予定です。","id":"exchange-048"}]},{"id":"topic-08","title":"の中原街道の沿道環境整備事業","agenda":"の中原街道の沿道環境整備事業","exchanges":[{"speaker":"菊地委員","kind":"質問","question":"１つだけ肝心な話なんですけれども、この２.４ｋｍ区間を費用助成するというんですけれども、これからやられるんですよね。騒音で生活に支障があるという部分で、調査が後、東京都の調査があってのお話なのか、ちょっと説明を求めました。","respondent":"伊勢住環境整備担当課長","answer":"これから都市計画の手続を進めるに当たって調査をするわけですが、その調査を平成１３年にやってあります。３地点でやっていますけれども、大体７２デシベルから７４デシベル、７５デシベルという範囲で平成１３年に測定した結果をいただいております。","id":"exchange-049"},{"speaker":"菊地委員","kind":"質問","question":"当然、実際にここに土地を持っておられる方、住んでおられる方にいろいろ高度制限にしろ何にしろかかってくるんですよね。やっぱり実際にそこに土地を所有権を持っておられる皆さんと話し合うというのをこういう決定をしていく際にやられることになるんか尋ねました。","respondent":"伊勢住環境整備担当課長","answer":"それから東京都で事業を実施したときにそれに合致するような地区計画を定めるということでして、説明会等はありますけれども、皆さんからの提案をいただいてというようなことではちょっと考えておりません。","id":"exchange-050"}]},{"id":"topic-09","title":"の「品川区建築物の解体工事計画の事前周知に関する指導要綱」","agenda":"の「品川区建築物の解体工事計画の事前周知に関する指導要綱」","exchanges":[{"speaker":"井上委員","kind":"質問","question":"(1) の「解体建築物の用途、構造、規模および近隣住民の建築物との位置関係の概要」。(6) 番の「アスベスト、住民としてはそれを信じるしかないんですけれども、それでは不安だというところはどうしたらいいのか尋ねました。","respondent":"浜脇住宅課長","answer":"いろいろな、中にはそういった材料の中にはアスベストが含まれているということがありますので、それについてはそういう材料すべて説明をしてもらうということです。","id":"exchange-051"},{"speaker":"井上委員","kind":"質問","question":"近隣の方々ではそれを見てもあまりわからないと思うんですけれども、その辺のもう少し実態の伴うというか、何らかの形でそういう方向性は今回の要綱をつくるに当たって何か検討されたのか尋ねました。","respondent":"浜脇住宅課長、福田まちづくり事業部長","answer":"当然こういったことについては説明をやっていただくというのが主旨ですので、さっきの調査も含めた安心した説明を行っていただくということでは、この要綱にも明記されてあります。 そう考えますと、現在のところは１％の含有率を持つ製品等については、動いているわけです。当然のことながら、法に基づく適切な処理を行ったというような説明の義務は解体業者に対して十分に住民にすべきというふうに解釈されます。","id":"exchange-052"},{"speaker":"井上委員","kind":"質問","question":"要綱ですと解体事業者の方の指導要綱ということですから、説明責任を果たしてほしいというようなことが明らかになるという意味では、その辺はいかがか尋ねました。","respondent":"浜脇住宅課長","answer":"あるいはそういったアスベストのかかわりについて説明をしていただくということになってありますので、そういったものの連携のもとにこれを実行していただいて、こういうふうに思っております。","id":"exchange-053"},{"speaker":"井上委員","kind":"質問・要望","question":"区民の方に周知できるような形で、要綱ではなくて実効性のある条例化というものを視野に検討していただきたいということで、要望して終わりにします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-054"},{"speaker":"菊地委員","kind":"質問・要望","question":"届け出をする者というところで１つお聞きしたいんですけれども、届け出をするという、この担保の問題がありますよね。そこを１つお聞きしたいのと、建築の場合の２Ｈとまた別に区分け、説明の範囲を区分けをした理由があれば教えてほしいと求めました。","respondent":"浜脇住宅課長","answer":"当然、リサイクル法の関係や、こういった一定の届け出と一緒に私どもの方では出していただきたいと思ってあります。騒音、１５とか１０ｍの範囲ということになりますけれども、その範囲でやればよろしいのではなかろうかという判断のもとにこういった範囲を決めます。","id":"exchange-055"},{"speaker":"菊地委員","kind":"質問","question":"区内で行われるすべての解体工事についてきっちり押さえることができるのかどうか、そこをちょっとお聞きしたかったんです。だから、その辺を考えると、単純に１０ｍという範囲内で押さえるというのはいかがなものかというふうに思うんですけれども。","respondent":"浜脇住宅課長","answer":"３階だったら説明会をしなければいけないとか、１５ｍから２０ｍの範囲ですから、もし鉄骨の場合にはそういった範囲になるというふうに思われます。大体１０ｍの範囲というのは、今、木造の２階、あるいは３階ぐらいの想定をしたものです。","id":"exchange-056"},{"speaker":"堺委員","kind":"提案","question":"先ほど、条例というお話が出ておりましたが、やっぱり最近幾つかの区では、アスベスト対策について条例という形の提案がされているんです。それについての本区の考え方、ちょっとその辺の確認をしておきたいんですがとの意見を述べました。","respondent":"浜脇住宅課長","answer":"要綱を制定するにあたって一番検討したのは、あるいはリサイクル法ということが法律で義務づけられているといいますか、現実的にあります。これらのリサイクルや大気汚染防止法との連携のもとに、実効性が上がってくるものというふうに考えて、要綱で今やっているところです。","id":"exchange-057"},{"speaker":"堺委員","kind":"質問・要望","question":"その辺はどうなんでしょうか。これから施行日が９月２０日ということは、きょうは２７日ですから、施行日以降７日も過ぎた段階で我々には説明をいただいているんですね。","respondent":"福田まちづくり事業部長、浜脇住宅課長","answer":"１点目のご質問にお答えいたしますが、全く無関係だとは申しませんが、基本的には別物というふうに私は考えております。こういう認識を持っております。 ８月３１日以降ですけれども、すぐにまちづくり事業部のホームページに載せまして出るようにいたしました。この要綱の浸透、ＰＲといいますか、説明を機会あるごとにやってまいりたいという考えです。","id":"exchange-058"},{"speaker":"堺委員","kind":"質問","question":"指導がこのまま行くんですよ、条例化ということは全く考えていませんよという話でしょうか。要するに、区民の心配を解消するために、実効性のあるそれなりのものが担保していくんだということか尋ねました。","respondent":"福田まちづくり事業部長","answer":"どういう効果が得られるのか、あるいはどう得られなかったのか、こういう評価をしていくことが必要になってくるだろうというふうに思っております。そのときの１つの課題ではあるだろうというふうに見ております。","id":"exchange-059"},{"speaker":"大西副委員長","kind":"質問","question":"この点に関しての想定される騒音対策というものをどういうレベルで考えられているかちょっと教えてもらいたいのと、それと、第８条の(6)。そういったときの調査方法についての区としての方針というんですか、考え方、そういうものというのはあるか尋ねました。","respondent":"浜脇住宅課長","answer":"騒音規制法とかがありますので、それに基づいて当然それに合わせるように機械を使うなり、そのための防音対策を講じるということです。私ども、それらについて事前に指導といいますか、そのまま今回も同じように連携を図りながら事業者を指導してまいるということであります。","id":"exchange-060"},{"speaker":"大西副委員長","kind":"意見","question":"私がお尋ねしたいのは、その状況の中で飛散されているものに対しての不安があるときに、どのような対応をされるか。それともそれは申し立てをした住民側がその調査を行っていかなければいけないのかという点に関してお尋ねしたいんですがとの意見を述べました。","respondent":"浜脇住宅課長","answer":"そういったときに不安があった場合には、当然、事業主の責務としてやるというのが基本です。そういった届け出、あるいはそういった条例等に基づくものでやっていなければ、指導してやらせるということになります。","id":"exchange-061"},{"speaker":"大西副委員長","kind":"質問","question":"それが１つ。そういう状況の中で、本当にアスベストを全部排除されていたのかどうなのかと、どのような形での調査が可能なんでしょうかということです。","respondent":"浜脇住宅課長","answer":"３階建てあるいは大規模上のことですので、我々としては、この要綱に基づいて改めて現場へ行って指導する。一定の指導をして、極端に言えば、中止してもらうような話もやはり出てくるのかなというふうに思います。","id":"exchange-062"},{"speaker":"大西副委員長","kind":"質問","question":"本当に全部とれているのかどうなのかということは大変心配なんだと。ぜひ調査をしてほしいんだというような状況が出てきた場合には、どのような対応をされるのでしょうかということなんです。","respondent":"片田建築課長","answer":"今、前にもご説明させていただいたんですけれども、あるいは大気汚染防止法に基づいて区の環境課に届け出るというふうな制度になってあります。どのような対応をするのか、これは行政指導ですけれども、そういうようなことをしております。","id":"exchange-063"},{"speaker":"大西副委員長","kind":"質問","question":"具体的な対処療法というんですか、それに対して今現実として沸き上がっているものに対しては、行政にそれだけの調査能力があるのかと。その部分で環境課の方が出向いていって、その調査自体を現実的にできるのかどうか、ちょっと説明を求めました。","respondent":"片田建築課長","answer":"労働安全衛生法の関係で、実際にそこで作業する方の安全を守るといったような考え方で直接的それに基づいて届け出を行っていただくものです。","id":"exchange-064"},{"speaker":"井上委員","kind":"質問","question":"先ほど、課長がおっしゃった協定項目というところでは、どういう項目について検討していくんだというところでは、そういう案というものは、そのことについて話し合うという前提があるわけですから、その部分では資料提供ということがいただけるのではないかと思うんですが、そこはいかがか尋ねました。","respondent":"福田まちづくり事業部長","answer":"問題ありません。協定項目については、ご提示し、ご用意させていただけるというふうに思います。","id":"exchange-065"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/825107?Template=document&Id=3830#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2005-01-01&TermEnd=2005-12-31"}],"sourceMeta":{"pages":0,"characters":45514,"voices":190}},{"id":"h17-20050927-9","meetingId":"h17-cm09","date":"2005年9月27日","dateIso":"2005-09-27","committee":"文教委員会","time":"午前１０時０４分～午前１１時５６分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件整理しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/270991?Template=document&Id=4550#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2005-01-01&TermEnd=2005-12-31"}],"sourceMeta":{"pages":0,"characters":783,"voices":8}}]);
